INSERT INTO "ActiveSkills" ("_row", "Id", "DisplayedName", "Description", "ActionType", "Icon_DDSFile", "ActiveSkillTargetTypes", "ActiveSkillTypes", "WeaponRestriction_ItemClassesKeys", "WebsiteDescription", "WebsiteImage", "HideOnWebsite", "GrantedEffect", "__col12", "SkillTotemId", "IsManuallyCasted", "Input_StatKeys", "Output_StatKeys", "MinionActiveSkillTypes", "__col18", "IsGem", "SecondarySkillSpecificStats", "SkillMine", "AlternateSkillTargetingBehavioursKey", "__col23", "AIFile", "StatContextFlags", "__col26", "__col27", "__col28", "TransfigureBase", "__col30") VALUES
(0, 'sweep', 'Holy Sweep', 'Swings a two handed mace or a staff in a circle, calling down holy hammers to land randomly on a number of enemies struck. Hits from these holy hammers cannot be evaded.', 0, 'Art/2DArt/SkillIcons/sweep.dds', '[1,2]', '[0,7,23,19,30]', '[17,57,14]', 'Sometimes a good blade just isn''t enough. With a mighty swing, a player wielding a staff, two-handed axe or mace smashes the skulls of many enemies surrounding them. The furious blow breaks armour and bone alike, even knocking foes back a substantial distance.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/sweep.jpg', 0, 'Sweep', 0, 22, 1, '[4087,4340,4253,10675,18239,18240]', '[24,481,436,187,723,2711]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1, 'sweep_alt_x', 'Holy Sweep of Hammerfalls', 'Swings a two handed mace or a staff in a circle, calling down waves of holy hammers for a duration. Cannot be supported by Multistrike.', 1334, 'Art/2DArt/SkillIcons/sweep.dds', '[1,2]', '[0,7,19,30,89,8]', '[17,57,14]', 'Sometimes a good blade just isn''t enough. With a mighty swing, a player wielding a staff, two-handed axe or mace smashes the skulls of many enemies surrounding them. The furious blow breaks armour and bone alike, even knocking foes back a substantial distance.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/sweep.jpg', 0, 'SweepAltX', 0, 22, 1, '[4087,4340,4253,10675,18239,18240]', '[24,481,436,187,723,2711]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 0, ''),
(2, 'sweep_alt_y', '[DNT] SweepAltY', 'Swings a two handed mace or a staff in a circle, calling down holy hammers to land randomly on a number of enemies struck. Hits from these holy hammers cannot be evaded.', 0, 'Art/2DArt/SkillIcons/sweep.dds', '[1,2]', '[0,7,23,19,30]', '[17,57,14]', 'Sometimes a good blade just isn''t enough. With a mighty swing, a player wielding a staff, two-handed axe or mace smashes the skulls of many enemies surrounding them. The furious blow breaks armour and bone alike, even knocking foes back a substantial distance.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/sweep.jpg', 0, 'Sweep', 0, 22, 1, '[4087,4340,4253,10675,18239,18240]', '[24,481,436,187,723,2711]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 0, ''),
(3, 'vaal_sweep', 'Vaal Sweep', 'Repeatedly swings a two handed melee weapon in a circle, knocking back monsters away from the character.', 0, 'Art/2DArt/SkillIcons/sweep.dds', '[1,2]', '[0,7,19,37,121]', '[14,16,17,15,57]', '', '', 1, '', 0, 22, 1, '[4087,4340,4253,10675,18239,18240]', '[24,481,436,187,723,2711]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(4, 'ground_slam_old', 'Ground Slam', 'The character slams the ground in front of them with a Staff, Mace or Sceptre, creating a wave that travels forward and damages enemies with an increased chance to stun.', 1, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,23,19,91,14]', '[12,32,14,17,36,57]', 'Raising a staff or two handed mace high above their head, the player slams it earthward with a crackling thud. The force of this blow sunders soil and rock, forking outward to stun and damage enemies that stand ahead. At greater levels of skill, the fissures from Ground Slam travel a long distance, causing tremendous harm to anything caught in their path.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/ground_slam.jpg', 0, 'GroundSlam', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(5, 'vaal_ground_slam_old', 'Vaal Ground Slam', 'The character slams the ground with a Staff, Mace or Sceptre, creating a wave that travels in all directions and damages enemies with an increased chance to stun.', 2, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,19,37,91,14,121]', '[12,32,14,17,36,57]', '', '', 1, '', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(6, 'ground_slam', 'Ground Slam', 'Slams the ground in front of you, creating a wave that travels forward and damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 3, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', 'Raising a staff or two handed mace high above their head, the player slams it earthward with a crackling thud. The force of this blow sunders soil and rock, forking outward to stun and damage enemies that stand ahead. At greater levels of skill, the fissures from Ground Slam travel a long distance, causing tremendous harm to anything caught in their path.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/ground_slam.jpg', 1, 'DistanceScaledGroundSlam', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[3499]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(7, 'ground_slam_alt_x', 'Ground Slam of Earthshaking', 'Slams the ground in front of you, creating a wide wave that travels forward and damages enemies with an increased chance to stun. Requires a Two Handed Axe, Two Handed Mace, or Staff.', 3, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,23,19,91,14]', '[14,17,16,57]', 'Raising a staff or two handed mace high above their head, the player slams it earthward with a crackling thud. The force of this blow sunders soil and rock, forking outward to stun and damage enemies that stand ahead. At greater levels of skill, the fissures from Ground Slam travel a long distance, causing tremendous harm to anything caught in their path.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/ground_slam.jpg', 1, 'DistanceScaledGroundSlam', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[3499]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 6, ''),
(8, 'ground_slam_alt_y', '[DNT] GroundSlamAltY', 'Slams the ground in front of you, creating a wave that travels forward and damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 3, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', 'Raising a staff or two handed mace high above their head, the player slams it earthward with a crackling thud. The force of this blow sunders soil and rock, forking outward to stun and damage enemies that stand ahead. At greater levels of skill, the fissures from Ground Slam travel a long distance, causing tremendous harm to anything caught in their path.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/ground_slam.jpg', 1, 'DistanceScaledGroundSlam', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[3499]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 6, ''),
(9, 'vaal_ground_slam', 'Vaal Ground Slam', 'Slams the ground in front of you, creating a wave that travels in all directions that damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 4, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,19,37,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, 'VaalDistanceScaledGroundSlam', 0, 22, 1, '[4051,4240,5599,18238]', '[24,436,8189,11626]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(10, 'cleave', 'Cleave', 'The character swings their weapon (or both weapons if dual wielding) in an arc, damaging monsters in an area in front of them. Only works with Axes and Swords.', 5, 'Art/2DArt/SkillIcons/iconcleave.dds', '[1,2]', '[0,7,23,19,43]', '[9,10,11,15,16]', 'Wielders of the axe and sword often find themselves beset by multiple foes. Expecting this, a trained armsman will employ the deadly Cleave. With a single practiced stroke, a Cleave sweeps sideways to inflict grievous harm to anyone standing nearby, lopping off heads and limbs with ease. As a player gains skill with Cleave, they strike harder with each swing of their blade.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/cleave.jpg', 0, 'Cleave', 0, 22, 1, '[4044,4269,4239,5477,17439,17445,17447,18066]', '[24,70,436,5514,591,17440,17441,18065]', '[]', 1, 1, '[5479]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(11, 'cleave_alt_x', 'Cleave of Rage', 'The character swings both their weapons in an arc, damaging monsters in an area in front of them. Requires dual wielding both an Axe and a Sword.', 5, 'Art/2DArt/SkillIcons/iconcleave.dds', '[1,2]', '[0,7,23,19,43,3,118]', '[9,10,11]', 'Wielders of the axe and sword often find themselves beset by multiple foes. Expecting this, a trained armsman will employ the deadly Cleave. With a single practiced stroke, a Cleave sweeps sideways to inflict grievous harm to anyone standing nearby, lopping off heads and limbs with ease. As a player gains skill with Cleave, they strike harder with each swing of their blade.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/cleave.jpg', 0, 'Cleave', 0, 22, 1, '[4044,4269,4239,5477,17439,17445,17447,18066]', '[24,70,436,5514,591,17440,17441,18065]', '[]', 1, 1, '[5479]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 10, ''),
(12, 'cleave_alt_y', '[DNT] CleaveAltY', 'The character swings their weapon (or both weapons if dual wielding) in an arc, damaging monsters in an area in front of them. Only works with Axes and Swords.', 5, 'Art/2DArt/SkillIcons/iconcleave.dds', '[1,2]', '[0,7,23,19,43]', '[9,10,11,15,16]', 'Wielders of the axe and sword often find themselves beset by multiple foes. Expecting this, a trained armsman will employ the deadly Cleave. With a single practiced stroke, a Cleave sweeps sideways to inflict grievous harm to anyone standing nearby, lopping off heads and limbs with ease. As a player gains skill with Cleave, they strike harder with each swing of their blade.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/cleave.jpg', 0, 'Cleave', 0, 22, 1, '[4044,4269,4239,5477,17439,17445,17447,18066]', '[24,70,436,5514,591,17440,17441,18065]', '[]', 1, 1, '[5479]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 10, ''),
(13, 'table_charge', 'Table Charge', 'Charges at an enemy, bashing it with the character''s shield and striking it. This knocks it back and stuns it. Enemies in the way are pushed to the side. Damage and stun are proportional to distance travelled.', 6, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2]', '[0,19,20,33,78]', '[6,7,9,10,11,12,32,36,56]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 1, 'TableCharge', 0, 22, 1, '[4276,4073]', '[70,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,37]', 0, 0, 1, NULL, ''),
(14, 'shield_charge_old', 'Shield Charge', 'Charges at an enemy, bashing it with the character''s shield and striking it. This knocks it back and stuns it. Enemies in the way are pushed to the side. Damage and stun are proportional to distance travelled.', 7, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2]', '[0,19,20,33,78]', '[6,7,9,10,11,12,32,36,56]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 1, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,37]', 0, 0, 1, NULL, ''),
(15, 'new_shield_charge', 'Shield Charge', 'Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies.', 8, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2,23]', '[0,9,19,7,33,78]', '[6,7,9,10,11,12,32,36,56]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 0, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,37]', 0, 0, 1, NULL, ''),
(16, 'shield_charge', 'Shield Charge', 'Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing off-hand damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies.', 9, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2,23]', '[0,9,19,7,33,78,27]', '[26]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 0, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(17, 'shield_charge_alt_x', '[DNT] ShieldChargeAltX', 'Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing off-hand damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies.', 9, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2,23]', '[0,9,19,7,33,78,27]', '[26]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 0, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 16, ''),
(18, 'shield_charge_alt_y', '[DNT] ShieldChargeAltY', 'Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing off-hand damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies.', 9, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2,23]', '[0,9,19,7,33,78,27]', '[26]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 0, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 16, ''),
(19, 'shield_charge_cooldown', 'Shield Charge', 'Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing off-hand damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies.', 9, 'Art/2DArt/SkillIcons/iconshieldcharge.dds', '[1,2,23]', '[0,9,19,7,33,78,27,89]', '[26]', 'In the hands of a talented combatant, even a shield becomes a deadly weapon. With Shield Charge, a warrior dashes forward at a single enemy, slamming them senseless. The violence of the charge will push nearby foes out of its path, and inflict great damage on target. An opponent unlucky enough to be struck by the full brunt of a Shield Charge will be knocked back and stunned for a time.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/shield_charge.jpg', 0, 'ShieldCharge', 0, 22, 1, '[4276,4073,18214]', '[70,24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(20, 'enduring_cry', 'Enduring Cry', 'Performs a warcry, taunting all nearby enemies to attack the user and granting a buff to the user and nearby allies. The user and allied players also gain endurance charges.', 10, 'Art/2DArt/SkillIcons/WarCryEnduring.dds', '[4]', '[4,7,8,62,89]', '[]', 'In battle, it''s often someone''s job to stand in the front line, and take most of the punishment. Few relish this task, but those who do know the secret of the Enduring Cry. This battle shout taunts all nearby enemies, compelling them to attack the offender, while simultaneously boosting his ability to absorb punishment in direct proportion to the number of nearby foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/enduring_cry.jpg', 0, 'EnduringCry', 0, 22, 1, '[9796,5623,4576,4433]', '[9795,4602,4602,3396]', '[]', 1, 1, '[12473]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(21, 'enduring_cry_repeatable', '', '', 10, '', '[4]', '[4,7,8,21,62]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(22, 'inspiring_cry', '[DNT] Old Rallying Cry', '[DNT] Unused (replaced)', 11, 'Art/2DArt/SkillIcons/InspiringCry.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, 'RallyingCry', 0, 22, 1, '[9796,5623,4578,4414]', '[9795,4602,4602,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(23, 'abyssal_cry', 'Abyssal Cry', 'Performs a warcry, Hindering nearby enemies and causing them to explode when killed. The Hinder effect is proportional to the number of surrounding enemies. Taunts all nearby enemies to attack the user. Shares a cooldown with other Warcry skills.', 12, 'Art/2DArt/SkillIcons/AbyssalCry.dds', '[4]', '[7,8,41,6,62,89]', '[]', '', '', 1, 'AbyssalCry', 0, 22, 1, '[9796,4128,4415]', '[9795,24,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17,4,18,29,19,26]', 0, 0, 1, NULL, ''),
(24, 'leap_slam', 'Leap Slam', 'Jump through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff.', 13, 'Art/2DArt/SkillIcons/iconleapslam.dds', '[1,2]', '[0,7,19,33,78,91,14]', '[9,10,11,12,32,14,15,16,17,57]', 'Long ago, the marauders of Oriath perfected a devastating battle technique - the ferocious Leap Slam. With a guttural cry, the leaper hurtles forward and smashes the ground at the feet of the enemy. The force from this blow deals substantial damage in a circle around the targeted spot, and will even knock back and stun. The Leap Slam is useful not only as an offensive technique, but also because it can serve, in a pinch, to escape from danger. The Marauders of Oriath were famous for attacking their foes from above, leaping down from high ledges to crush their enemies'' skulls.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/leap_slam.jpg', 0, 'LeapSlam', 0, 22, 1, '[4275,4069,4248]', '[70,24,436]', '[]', 1, 1, '[]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(25, 'leap_slam_alt_x', 'Leap Slam of Groundbreaking', 'Jump a short distance through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff.', 13, 'Art/2DArt/SkillIcons/iconleapslam.dds', '[1,2]', '[0,7,19,33,78,91,14]', '[9,10,11,12,32,14,15,16,17,57]', 'Long ago, the marauders of Oriath perfected a devastating battle technique - the ferocious Leap Slam. With a guttural cry, the leaper hurtles forward and smashes the ground at the feet of the enemy. The force from this blow deals substantial damage in a circle around the targeted spot, and will even knock back and stun. The Leap Slam is useful not only as an offensive technique, but also because it can serve, in a pinch, to escape from danger. The Marauders of Oriath were famous for attacking their foes from above, leaping down from high ledges to crush their enemies'' skulls.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/leap_slam.jpg', 0, 'LeapSlam', 0, 22, 1, '[4275,4069,4248]', '[70,24,436]', '[]', 1, 1, '[]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 24, ''),
(26, 'leap_slam_alt_y', '[DNT] LeapSlamAltY', 'Jump through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff.', 13, 'Art/2DArt/SkillIcons/iconleapslam.dds', '[1,2]', '[0,7,19,33,78,91,14]', '[9,10,11,12,32,14,15,16,17,57]', 'Long ago, the marauders of Oriath perfected a devastating battle technique - the ferocious Leap Slam. With a guttural cry, the leaper hurtles forward and smashes the ground at the feet of the enemy. The force from this blow deals substantial damage in a circle around the targeted spot, and will even knock back and stun. The Leap Slam is useful not only as an offensive technique, but also because it can serve, in a pinch, to escape from danger. The Marauders of Oriath were famous for attacking their foes from above, leaping down from high ledges to crush their enemies'' skulls.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/leap_slam.jpg', 0, 'LeapSlam', 0, 22, 1, '[4275,4069,4248]', '[70,24,436]', '[]', 1, 1, '[]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 24, ''),
(27, 'leap_slam_cooldown', 'Leap Slam', 'Jump into the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff.', 13, 'Art/2DArt/SkillIcons/iconleapslam.dds', '[1,2]', '[0,7,19,33,78,91,14,89]', '[9,10,11,12,32,14,15,16,17,57]', 'Long ago, the marauders of Oriath perfected a devastating battle technique - the ferocious Leap Slam. With a guttural cry, the leaper hurtles forward and smashes the ground at the feet of the enemy. The force from this blow deals substantial damage in a circle around the targeted spot, and will even knock back and stun. The Leap Slam is useful not only as an offensive technique, but also because it can serve, in a pinch, to escape from danger. The Marauders of Oriath were famous for attacking their foes from above, leaping down from high ledges to crush their enemies'' skulls.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/leap_slam.jpg', 0, 'LeapSlam', 0, 22, 1, '[4275,4069,4248]', '[70,24,436]', '[]', 1, 1, '[]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(28, 'leap_slam_behind', 'Leap Slam', '', 13, 'Art/2DArt/SkillIcons/iconleapslam.dds', '[9]', '[0,7,19,33,78,91,14]', '[9,10,11,12,32,14,15,16,17,57]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(29, 'double_strike', 'Double Strike', 'Performs two fast strikes with a melee weapon.', 14, 'Art/2DArt/SkillIcons/icondoubleswing.dds', '[1,2]', '[0,20,23,19,27]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'Originally perfected by the renowned Duelist Fammal during his reign in the arenas of Oriath, the deadly Double Strike brings fame and renown to those who master it. A Double Strike performs two regular melee attacks in the blink of an eye, dealing twice as much damage in a single span of time. Foes caught unawares will find themselves cut to ribbons or stunned into submission beneath a flurry of blows.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/double_strike.jpg', 0, 'DoubleStrike', 0, 22, 1, '[4045,4270,4306,8089,18237]', '[24,70,556,8090,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(30, 'double_strike_alt_x', 'Double Strike of Impaling', 'Performs two fast strikes with a melee weapon.', 14, 'Art/2DArt/SkillIcons/icondoubleswing.dds', '[1,2]', '[0,20,23,19,27]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'Originally perfected by the renowned Duelist Fammal during his reign in the arenas of Oriath, the deadly Double Strike brings fame and renown to those who master it. A Double Strike performs two regular melee attacks in the blink of an eye, dealing twice as much damage in a single span of time. Foes caught unawares will find themselves cut to ribbons or stunned into submission beneath a flurry of blows.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/double_strike.jpg', 0, 'DoubleStrike', 0, 22, 1, '[4045,4270,4306,8089,18237]', '[24,70,556,8090,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 29, ''),
(31, 'double_strike_alt_y', 'Double Strike of Momentum', 'Performs two fast strikes with a melee weapon, gaining stages which cause this skill to attack faster. All stages are lost when you move.', 14, 'Art/2DArt/SkillIcons/icondoubleswing.dds', '[1,2]', '[0,20,23,19]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'Originally perfected by the renowned Duelist Fammal during his reign in the arenas of Oriath, the deadly Double Strike brings fame and renown to those who master it. A Double Strike performs two regular melee attacks in the blink of an eye, dealing twice as much damage in a single span of time. Foes caught unawares will find themselves cut to ribbons or stunned into submission beneath a flurry of blows.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/double_strike.jpg', 0, 'DoubleStrike', 0, 22, 1, '[4045,4270,4306,8089,18237]', '[24,70,556,8090,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 29, ''),
(32, 'vaal_double_strike', 'Vaal Double Strike', 'Performs two fast strikes with a melee weapon, each of which summons a double of you for a duration to continuously attack monsters in this fashion.', 15, 'Art/2DArt/SkillIcons/icondoubleswing.dds', '[1,2]', '[0,20,19,8,37,27,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, 'VaalDoubleStrikeTwo', 0, 22, 1, '[4045,4270,4306,8089,18237]', '[24,70,556,8090,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(33, 'vaal_double_strike_old', 'Vaal Double Strike', 'Performs two fast strikes with a melee weapon, and summons your double for a duration to continuously attack monsters in this fashion.', 16, 'Art/2DArt/SkillIcons/icondoubleswing.dds', '[1,2]', '[0,20,19,8,37,27,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4045,4270,4306,8089,18237]', '[24,70,556,8090,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(34, 'elemental_hit', 'Elemental Hit', 'Each attack with a melee weapon will choose an element at random, and will only be able to deal damage of that element. If the attack hits an enemy, it will deal damage in an area around them, with the radius being larger if that enemy is suffering from an ailment of the chosen element. It will avoid choosing the same element twice in a row.', 17, 'Art/2DArt/SkillIcons/iconelementalhit.dds', '[1,2]', '[0,20,23,19,28,29,30,7,101]', '[9,10,15,11,16,12,32,17,14,36,57,7,56,6]', 'Cold steel tends to solve most problems, but sometimes it''s not quite enough. With Elemental Hit, a player infuses their weapon with the heat of a furnace, the electricity of a Summer tempest, or the icy chill of the Winter night. The specific element is randomly chosen, but the result is the same: tons of extra damage dealt, often killing the target with a single blow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/elemental_hit.jpg', 0, 'ElementalHit', 0, 22, 1, '[4343,4278,4090,18212]', '[1917,70,24,18127]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(35, 'elemental_hit_alt_x', 'Elemental Hit of the Spectrum', 'Fires a projectile with a wand or bow that deals fire, cold and lightning damage. If the projectile hits an enemy, it will deal damage in an area around them.', 17, 'Art/2DArt/SkillIcons/iconelementalhit.dds', '[1,2]', '[0,2,56,14,13,15,28,29,30,40,57,7,31,126]', '[13,8]', 'Cold steel tends to solve most problems, but sometimes it''s not quite enough. With Elemental Hit, a player infuses their weapon with the heat of a furnace, the electricity of a Summer tempest, or the icy chill of the Winter night. The specific element is randomly chosen, but the result is the same: tons of extra damage dealt, often killing the target with a single blow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/elemental_hit.jpg', 0, 'ElementalHit', 0, 22, 1, '[4343,4278,4090,18212]', '[1917,70,24,18127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 34, ''),
(36, 'elemental_hit_alt_y', '[DNT] ElementalHitAltY', 'Each attack with a melee weapon will choose an element at random, and will only be able to deal damage of that element. If the attack hits an enemy, it will deal damage in an area around them, with the radius being larger if that enemy is suffering from an ailment of the chosen element. It will avoid choosing the same element twice in a row.', 17, 'Art/2DArt/SkillIcons/iconelementalhit.dds', '[1,2]', '[0,20,23,19,28,29,30,7,101]', '[9,10,15,11,16,12,32,17,14,36,57,7,56,6]', 'Cold steel tends to solve most problems, but sometimes it''s not quite enough. With Elemental Hit, a player infuses their weapon with the heat of a furnace, the electricity of a Summer tempest, or the icy chill of the Winter night. The specific element is randomly chosen, but the result is the same: tons of extra damage dealt, often killing the target with a single blow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/elemental_hit.jpg', 0, 'ElementalHit', 0, 22, 1, '[4343,4278,4090,18212]', '[1917,70,24,18127]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 34, ''),
(37, 'elemental_hit_monster', 'Elemental Hit', 'Each attack with this skill will choose an element at random, and will only be able to deal damage of that element. If the attack hits an enemy, it will deal damage in an area around them, with the radius being larger if that enemy is suffering from an ailment of the chosen element. It will avoid choosing the same element twice in a row.', 17, 'Art/2DArt/SkillIcons/iconelementalhit.dds', '[1,2]', '[0,2,56,14,13,15,20,23,19,28,29,30,40,57,7,31,101]', '[]', 'Cold steel tends to solve most problems, but sometimes it''s not quite enough. With Elemental Hit, a player infuses their weapon with the heat of a furnace, the electricity of a Summer tempest, or the icy chill of the Winter night. The specific element is randomly chosen, but the result is the same: tons of extra damage dealt, often killing the target with a single blow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/elemental_hit.jpg', 0, 'ElementalHit', 0, 22, 1, '[4343,4278,4090,18212]', '[1917,70,24,18127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(38, 'immortal_call_old', 'Immortal Call', 'Discharges Endurance Charges, making the character invulnerable to physical damage for a short time, proportional to how many endurance charges were expended.', 18, 'Art/2DArt/SkillIcons/immortalcall.dds', '[4]', '[1,4,8,14,31,27,63,89]', '[]', 'Even with the added toughness granted from Endurance Charges, a combatant sometimes finds themselves facing impossible odds. This rare event makes flight a good option and sometimes it even merits the power of the Immortal Call. The legendary war cry channels all current Endurance into an invisible shield that shelters the player from all physical harm for a brief duration. Consuming more charges will extend the duration of the Immortal shield, giving plenty of time for escape or victory.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/immortal_call.jpg', 0, 'ImmortalCall', 0, 22, 1, '[4396]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(39, 'immortal_call', 'Immortal Call', 'Take less Physical and Elemental Damage for a short time. Consumes up to 5 Endurance Charges to lengthen the buff and further lessen Physical Damage taken. Shares a cooldown with other Guard skills.', 18, 'Art/2DArt/SkillIcons/immortalcall.dds', '[4]', '[1,4,8,14,31,63,77,89]', '[]', '', '', 1, 'MortalCall', 0, 22, 1, '[4396,9520,10004,22126]', '[217,9521,362,9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(40, 'vaal_immortal_call', 'Vaal Immortal Call', 'Discharges Endurance Charges, making the character unable to die or gain Vaal souls for a short time, proportional to how many endurance charges were expended.', 18, 'Art/2DArt/SkillIcons/immortalcall.dds', '[4]', '[1,4,8,14,37,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[4396,10004]', '[217,361]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(41, 'dual_strike', 'Dual Strike', 'Attacks with both weapons, dealing the damage of both in one strike. Dual wield only. Does not work with wands.', 19, 'Art/2DArt/SkillIcons/icondualswing.dds', '[1,2]', '[0,3,20,23,19,43]', '[6,7,9,10,11,12,32,16,56]', 'Double Strike was not the only attack Fammal mastered during his years in the arenas. He also perfected the technique of the Dual Strike, and used it to decimate countless opponents. Those who follow in his footsteps seek to duplicate the art, and at high levels of skill, a few manage. Dual Strike lashes out at a single target with tremendous force, slicing or smashing it with both weapons simultaneously. When executed by a master swordsman, just one Dual Strike is often enough to end the battle.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/dual_strike.jpg', 0, 'DualStrike', 0, 22, 1, '[4046,4271,4307,5492,12118,12121,12124,12127,12130,5924,18237]', '[24,70,556,5521,12119,12122,12125,12128,12131,18330,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(42, 'dual_strike_alt_x', 'Dual Strike of Ambidexterity', 'Attacks with both weapons, dealing the damage of both in one strike. Requires dual-wielding two different melee weapon types to use.', 19, 'Art/2DArt/SkillIcons/icondualswing.dds', '[1,2]', '[0,3,118,20,23,19,43]', '[6,7,9,10,11,12,32,16,56]', 'Double Strike was not the only attack Fammal mastered during his years in the arenas. He also perfected the technique of the Dual Strike, and used it to decimate countless opponents. Those who follow in his footsteps seek to duplicate the art, and at high levels of skill, a few manage. Dual Strike lashes out at a single target with tremendous force, slicing or smashing it with both weapons simultaneously. When executed by a master swordsman, just one Dual Strike is often enough to end the battle.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/dual_strike.jpg', 0, 'DualStrike', 0, 22, 1, '[4046,4271,4307,5492,12118,12121,12124,12127,12130,5924,18237]', '[24,70,556,5521,12119,12122,12125,12128,12131,18330,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 41, ''),
(43, 'dual_strike_alt_y', '[DNT] DualStrikeAltY', 'Attacks with both weapons, dealing the damage of both in one strike. Dual wield only. Does not work with wands.', 19, 'Art/2DArt/SkillIcons/icondualswing.dds', '[1,2]', '[0,3,20,23,19,43]', '[6,7,9,10,11,12,32,16,56]', 'Double Strike was not the only attack Fammal mastered during his years in the arenas. He also perfected the technique of the Dual Strike, and used it to decimate countless opponents. Those who follow in his footsteps seek to duplicate the art, and at high levels of skill, a few manage. Dual Strike lashes out at a single target with tremendous force, slicing or smashing it with both weapons simultaneously. When executed by a master swordsman, just one Dual Strike is often enough to end the battle.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/dual_strike.jpg', 0, 'DualStrike', 0, 22, 1, '[4046,4271,4307,5492,12118,12121,12124,12127,12130,5924,18237]', '[24,70,556,5521,12119,12122,12125,12128,12131,18330,21645]', '[]', 1, 1, '[18237]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 41, ''),
(44, 'whirling_blades', 'Whirling Blades', 'Dive through enemies, dealing weapon damage. If dual wielding attacks with both weapons, dealing the damage of both in one hit. Only works with Daggers, Claws, and One-Handed Swords.', 20, 'Art/2DArt/SkillIcons/iconbladeflurry.dds', '[1,2,9]', '[0,19,33,78]', '[7,9,10,6,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/blade_flurry.jpg', 0, 'WhirlingBlades', 0, 22, 1, '[4456,4115]', '[70,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(45, 'whirling_blades_alt_x', '[DNT] WhirlingBladesAltX', 'Dive through enemies, dealing weapon damage. If dual wielding attacks with both weapons, dealing the damage of both in one hit. Only works with Daggers, Claws, and One-Handed Swords.', 20, 'Art/2DArt/SkillIcons/iconbladeflurry.dds', '[1,2,9]', '[0,19,33,78]', '[7,9,10,6,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/blade_flurry.jpg', 0, 'WhirlingBlades', 0, 22, 1, '[4456,4115]', '[70,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 44, ''),
(46, 'whirling_blades_alt_y', '[DNT] WhirlingBladesAltY', 'Dive through enemies, dealing weapon damage. If dual wielding attacks with both weapons, dealing the damage of both in one hit. Only works with Daggers, Claws, and One-Handed Swords.', 20, 'Art/2DArt/SkillIcons/iconbladeflurry.dds', '[1,2,9]', '[0,19,33,78]', '[7,9,10,6,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/blade_flurry.jpg', 0, 'WhirlingBlades', 0, 22, 1, '[4456,4115]', '[70,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 44, ''),
(47, 'whirling_blades_cooldown', 'Whirling Blades', 'Dive through enemies, dealing weapon damage. If dual wielding attacks with both weapons, dealing the damage of both in one hit. Only works with Daggers, Claws, and One-Handed Swords.', 20, 'Art/2DArt/SkillIcons/iconbladeflurry.dds', '[1,2,9,23]', '[0,19,33,78,89]', '[7,9,10,6,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/blade_flurry.jpg', 0, 'WhirlingBlades', 0, 22, 1, '[4456,4115]', '[70,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(48, 'frenzy', 'Frenzy', 'Performs an attack with a ranged weapon that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed.', 21, 'Art/2DArt/SkillIcons/iconfrenzy.dds', '[1,2]', '[0,40,57,2,56,14,13,15,31,126]', '[13,8]', 'The bread and butter of any effective combat skill set, Frenzy is used by many and feared by all. With Frenzy active, every successful attack dealt accelerates the next attack, transforming the player into an offensive dervish. Once the Frenzy is at full intensity, it can be maintained indefinitely as long as the player strikes a new target in time. Several skills consume Frenzy charges when they are activated, enabling new ways to decimate foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/frenzy.jpg', 0, 'Frenzy', 0, 22, 1, '[4088,4341,18231]', '[24,1692,8367]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(49, 'frenzy_alt_x', 'Frenzy of Onslaught', 'Perform a strike with a melee weapon that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed.', 21, 'Art/2DArt/SkillIcons/iconfrenzy.dds', '[1,2]', '[0,20,23,19]', '[9,10,15,11,16,12,32,17,14,36,57,7,56,6]', 'The bread and butter of any effective combat skill set, Frenzy is used by many and feared by all. With Frenzy active, every successful attack dealt accelerates the next attack, transforming the player into an offensive dervish. Once the Frenzy is at full intensity, it can be maintained indefinitely as long as the player strikes a new target in time. Several skills consume Frenzy charges when they are activated, enabling new ways to decimate foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/frenzy.jpg', 0, 'Frenzy', 0, 22, 1, '[4088,4341,18231]', '[24,1692,8367]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 48, ''),
(50, 'frenzy_alt_y', '[DNT] FrenzyAltY', 'Performs an attack with a ranged weapon that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed.', 21, 'Art/2DArt/SkillIcons/iconfrenzy.dds', '[1,2]', '[0,40,57,2,56,14,13,15,31,126]', '[13,8]', 'The bread and butter of any effective combat skill set, Frenzy is used by many and feared by all. With Frenzy active, every successful attack dealt accelerates the next attack, transforming the player into an offensive dervish. Once the Frenzy is at full intensity, it can be maintained indefinitely as long as the player strikes a new target in time. Several skills consume Frenzy charges when they are activated, enabling new ways to decimate foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/frenzy.jpg', 0, 'Frenzy', 0, 22, 1, '[4088,4341,18231]', '[24,1692,8367]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 48, ''),
(51, 'monster_frenzy', 'Frenzy', 'Performs an attack that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed.', 21, 'Art/2DArt/SkillIcons/iconfrenzy.dds', '[1,2]', '[0,40,57,2,56,14,13,15,20,23,19,31]', '[]', 'The bread and butter of any effective combat skill set, Frenzy is used by many and feared by all. With Frenzy active, every successful attack dealt accelerates the next attack, transforming the player into an offensive dervish. Once the Frenzy is at full intensity, it can be maintained indefinitely as long as the player strikes a new target in time. Several skills consume Frenzy charges when they are activated, enabling new ways to decimate foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/frenzy.jpg', 0, 'Frenzy', 0, 22, 1, '[4088,4341,18231]', '[24,1692,8367]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(52, 'caustic_arrow', 'Caustic Arrow', 'Fires an arrow which deals chaos damage in an area on impact, and spreads caustic ground. Enemies standing on the caustic ground take chaos damage over time.', 22, 'Art/2DArt/SkillIcons/poisonarrow.dds', '[1,2]', '[0,40,57,2,56,7,8,13,15,14,34,41,31]', '[13]', 'Borrowing a bit of toxic chemistry from the secretive Oriath Necromancers guild, a skilled archer infuses their arrowhead with a wicked venom. Once enchanted, the arrow will explode violently when it impacts a target, showering both foes and the surrounding area with a cloud of choking death. Anything living caught in the cloud will suffocate quickly, suffering heavy chaos damage until they move far away.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/poison_arrow.jpg', 0, 'CausticArrow', 0, 22, 1, '[4103,4305,4264,8510,8509,8574,8576,8578,18232]', '[24,217,436,8473,8508,6215,2020,8579,9969]', '[]', 1, 1, '[]', 8, 7, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(53, 'caustic_arrow_alt_x', 'Caustic Arrow of Poison', 'Fires a poisonous arrow which deals chaos damage in an area on impact.', 22, 'Art/2DArt/SkillIcons/poisonarrow.dds', '[1,2]', '[0,40,57,2,56,7,13,15,14,41,31]', '[13]', 'Borrowing a bit of toxic chemistry from the secretive Oriath Necromancers guild, a skilled archer infuses their arrowhead with a wicked venom. Once enchanted, the arrow will explode violently when it impacts a target, showering both foes and the surrounding area with a cloud of choking death. Anything living caught in the cloud will suffocate quickly, suffering heavy chaos damage until they move far away.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/poison_arrow.jpg', 0, 'CausticArrow', 0, 22, 1, '[4103,4305,4264,8510,8509,8574,8576,8578,18232]', '[24,217,436,8473,8508,6215,2020,8579,9969]', '[]', 1, 1, '[]', 8, 7, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 52, ''),
(54, 'caustic_arrow_alt_y', '[DNT] PoisonArrowAltY', 'Fires an arrow which deals chaos damage in an area on impact, and spreads caustic ground. Enemies standing on the caustic ground take chaos damage over time.', 22, 'Art/2DArt/SkillIcons/poisonarrow.dds', '[1,2]', '[0,40,57,2,56,7,8,13,15,14,34,41,31]', '[13]', 'Borrowing a bit of toxic chemistry from the secretive Oriath Necromancers guild, a skilled archer infuses their arrowhead with a wicked venom. Once enchanted, the arrow will explode violently when it impacts a target, showering both foes and the surrounding area with a cloud of choking death. Anything living caught in the cloud will suffocate quickly, suffering heavy chaos damage until they move far away.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/poison_arrow.jpg', 0, 'CausticArrow', 0, 22, 1, '[4103,4305,4264,8510,8509,8574,8576,8578,18232]', '[24,217,436,8473,8508,6215,2020,8579,9969]', '[]', 1, 1, '[]', 8, 7, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 52, ''),
(55, 'vaal_caustic_arrow', 'Vaal Caustic Arrow', 'Fires a slow-moving serpentine arrow which deals chaos damage while piercing enemies, and leaves a trail of caustic ground. Enemies standing on the caustic ground take chaos damage over time.', 23, 'Art/2DArt/SkillIcons/poisonarrow.dds', '[1,2]', '[0,40,2,56,7,8,13,15,14,34,41,37]', '[13]', '', '', 0, 'VaalCausticArrow', 0, 22, 1, '[4103,4305,4264,8510,8509,8574,8576,8578,18232]', '[24,217,436,8473,8508,6215,2020,8579,9969]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(56, 'backstab', 'Backstab', 'A dagger skill that deals a critical strike and additional damage to an enemy if the attack is made from behind the enemy. Has high mana cost and cooldown', 24, 'Art/2DArt/SkillIcons/backstab.dds', '[1,2]', '[0,20,23,19]', '[7,56]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(57, 'detonate_dead_old_monster', '', '', 25, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[6,20]', '[1,6,7,13,14,15,21,31,28,71]', '[]', 'To a skilled practitioner of the occult, the corpses of slain foes are a tool to bend to their dark purpose. While most seek to animate the very souls of fallen enemies, a crafty handful have discovered an even more potent use. Infusing the enzymes and acids of the target''s body with magical energy, the caster creates a volatile mixture that detonates violently when a final word is spoken. The explosion blasts outwards in every direction, showering nearby enemies with flame and toxic liquid. At higher levels of skill, the detonation will damage and stun foes in a wide area.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/detonate_dead_new.jpg', 1, 'DetonateDead', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(58, 'detonate_dead', 'Detonate Dead', 'Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected.', 26, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[6,20]', '[1,6,7,13,14,15,21,31,28,55,65,69,71]', '[]', 'To a skilled practitioner of the occult, the corpses of slain foes are a tool to bend to their dark purpose. While most seek to animate the very souls of fallen enemies, a crafty handful have discovered an even more potent use. Infusing the enzymes and acids of the target''s body with magical energy, the caster creates a volatile mixture that detonates violently when a final word is spoken. The explosion blasts outwards in every direction, showering nearby enemies with flame and toxic liquid. At higher levels of skill, the detonation will damage and stun foes in a wide area.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/detonate_dead_new.jpg', 0, 'DetonateDead', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DetonateDeadTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(59, 'detonate_dead_alt_x', 'Detonate Dead of Scavenging', 'Targets a corpse, causing it to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. Cannot target corpses that have been created by skills.', 26, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[6,20]', '[1,6,7,13,14,15,21,31,28,55,65,69,71]', '[]', 'To a skilled practitioner of the occult, the corpses of slain foes are a tool to bend to their dark purpose. While most seek to animate the very souls of fallen enemies, a crafty handful have discovered an even more potent use. Infusing the enzymes and acids of the target''s body with magical energy, the caster creates a volatile mixture that detonates violently when a final word is spoken. The explosion blasts outwards in every direction, showering nearby enemies with flame and toxic liquid. At higher levels of skill, the detonation will damage and stun foes in a wide area.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/detonate_dead_new.jpg', 0, 'DetonateDead', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DetonateDeadTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 58, ''),
(60, 'detonate_dead_alt_y', 'Detonate Dead of Chain Reaction', 'Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. This will continue to target other corpses in the area, with a shorter delay between each one, until it runs out of corpses or has destroyed 8 corpses. Cannot be supported by Spell Cascade.', 27, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[6,20]', '[1,6,7,13,14,15,21,31,28,65,69,71]', '[]', 'To a skilled practitioner of the occult, the corpses of slain foes are a tool to bend to their dark purpose. While most seek to animate the very souls of fallen enemies, a crafty handful have discovered an even more potent use. Infusing the enzymes and acids of the target''s body with magical energy, the caster creates a volatile mixture that detonates violently when a final word is spoken. The explosion blasts outwards in every direction, showering nearby enemies with flame and toxic liquid. At higher levels of skill, the detonation will damage and stun foes in a wide area.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/detonate_dead_new.jpg', 0, 'DetonateDead', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DetonateDeadTotemRepeating.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 58, ''),
(61, 'vaal_detonate_dead', 'Vaal Detonate Dead', 'Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. This will continue to target other corpses in the area, with an increasing delay between each one, until it runs out of corpses or has destroyed 22 corpses.', 27, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[1]', '[1,6,7,13,14,15,37,28,71]', '[]', '', '', 1, '', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(62, 'vaal_detonate_dead_old', 'Vaal Detonate Dead', 'Explodes an unused corpse, dealing fire damage to nearby enemies. Nearby corpses will also explode in a chain reaction. The explosions are not affected by modifiers to spell damage.', 25, 'Art/2DArt/SkillIcons/iconcorpseexplosion.dds', '[6,20]', '[1,6,7,13,14,15,37,28,71]', '[]', '', '', 1, '', 0, 22, 1, '[4102,4261]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(63, 'flicker_strike', 'Flicker Strike', 'Teleports the character to a nearby monster and attacks with a melee weapon. If no specific monster is targeted, one is picked at random. Grants a buff that increases movement speed for a duration. The cooldown can be bypassed by expending a Frenzy Charge.', 28, 'Art/2DArt/SkillIcons/iconblinkstrike.dds', '[1,2]', '[0,19,20,23,33,8,89]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'They should have known the rule: never corner a Duelist. He was surrounded by four hulking brutes, each one uglier than the one before. They had come for the fine mail tunic he wore, but he had given them nothing but insults and injury. As the Duelist fought, his speed grew more frenetic, until he was a blur of whirling steel. After a time though, superior numbers took their toll, and the attackers began to find openings. With blood oozing from a dozen wounds, the Duelist gathered himself for one final assault. He waited until just the right moment, right as his foes rushed in for the kill.__BREAK__ __BREAK__ There was a flash, and in the blink of an eye, he suddenly appeared behind the first assailant, plunging his sword to the hilt in the exposed neck. Then he was beheading the second in one quick swipe. Then the third fell with a shriek, his bowels spilling onto the cobblestones. The fourth turned to run, and found himself facing the Duelist, who met his momentum with a stab through the heart. Spent, panting on the ground, the victor wiped his blade clean, and recorded four more kills with Flicker Strike.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/flicker_strike.jpg', 0, 'FlickerStrike', 0, 22, 1, '[4287,4068,4331,18236]', '[3396,24,3548,8135]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(64, 'flicker_strike_alt_x', 'Flicker Strike of Power', 'Teleports the character to a nearby monster and attacks with a melee weapon. If no specific monster is targeted, one is picked at random. Grants a buff that increases movement speed for a duration. The cooldown can be bypassed by expending a Power Charge.', 28, 'Art/2DArt/SkillIcons/iconblinkstrike.dds', '[1,2]', '[0,19,20,23,33,8,89]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'They should have known the rule: never corner a Duelist. He was surrounded by four hulking brutes, each one uglier than the one before. They had come for the fine mail tunic he wore, but he had given them nothing but insults and injury. As the Duelist fought, his speed grew more frenetic, until he was a blur of whirling steel. After a time though, superior numbers took their toll, and the attackers began to find openings. With blood oozing from a dozen wounds, the Duelist gathered himself for one final assault. He waited until just the right moment, right as his foes rushed in for the kill.__BREAK__ __BREAK__ There was a flash, and in the blink of an eye, he suddenly appeared behind the first assailant, plunging his sword to the hilt in the exposed neck. Then he was beheading the second in one quick swipe. Then the third fell with a shriek, his bowels spilling onto the cobblestones. The fourth turned to run, and found himself facing the Duelist, who met his momentum with a stab through the heart. Spent, panting on the ground, the victor wiped his blade clean, and recorded four more kills with Flicker Strike.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/flicker_strike.jpg', 0, 'FlickerStrike', 0, 22, 1, '[4287,4068,4331,18236]', '[3396,24,3548,8135]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 63, ''),
(65, 'flicker_strike_alt_y', '[DNT] FlickerStrikeAltY', 'Teleports the character to a nearby monster and attacks with a melee weapon. If no specific monster is targeted, one is picked at random. Grants a buff that increases movement speed for a duration. The cooldown can be bypassed by expending a Frenzy Charge.', 28, 'Art/2DArt/SkillIcons/iconblinkstrike.dds', '[1,2]', '[0,19,20,23,33,8,89]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', 'They should have known the rule: never corner a Duelist. He was surrounded by four hulking brutes, each one uglier than the one before. They had come for the fine mail tunic he wore, but he had given them nothing but insults and injury. As the Duelist fought, his speed grew more frenetic, until he was a blur of whirling steel. After a time though, superior numbers took their toll, and the attackers began to find openings. With blood oozing from a dozen wounds, the Duelist gathered himself for one final assault. He waited until just the right moment, right as his foes rushed in for the kill.__BREAK__ __BREAK__ There was a flash, and in the blink of an eye, he suddenly appeared behind the first assailant, plunging his sword to the hilt in the exposed neck. Then he was beheading the second in one quick swipe. Then the third fell with a shriek, his bowels spilling onto the cobblestones. The fourth turned to run, and found himself facing the Duelist, who met his momentum with a stab through the heart. Spent, panting on the ground, the victor wiped his blade clean, and recorded four more kills with Flicker Strike.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/flicker_strike.jpg', 0, 'FlickerStrike', 0, 22, 1, '[4287,4068,4331,18236]', '[3396,24,3548,8135]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 63, ''),
(66, 'vaal_flicker_strike', 'Vaal Flicker Strike', 'Repeatedly teleports to enemies and hits them, inflicting a wound but dealing no damage. After the repeating finishes, each enemy is hit by the total damage of their wounds, which are removed.', 28, 'Art/2DArt/SkillIcons/iconblinkstrike.dds', '[1,2]', '[0,19,20,33,37,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4287,4068,4331]', '[3396,24,3548]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(67, 'blood_rage', 'Blood Rage', 'Adds a buff that deals Physical Damage over time, while increasing Attack Speed and Life Leech. Killing an enemy while this buff is active refreshes the buff duration, and can grant a Frenzy Charge.', 29, 'Art/2DArt/SkillIcons/bloodrage.dds', '[4]', '[1,4,8,14,31,63,27,89]', '[]', 'Centuries ago, ravaging bands of Marauders swept across Oriath, and nearly toppled the monarchy in the capital. Before they met the order''s Templars on the battlefield, they chewed the sacred root, and entered the ''Blood Rage''. Under the influence of the Rage, the Marauders knew no fear or pain, and every blow they struck on their enemies rejuvenated their depleted life. The root also drove the Marauders half-crazy with blood lust, causing them to attack with blinding speed as long as there was flesh nearby to hack. The only consequence of the Blood Rage state was a gradual loss of the Marauder''s blood, but the magical invigoration from attacking was usually enough to compensate.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/blood_rage.jpg', 0, 'BloodRage', 0, 22, 1, '[4543,4544]', '[8591,1358]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(68, 'split_arrow', 'Split Arrow', 'Fires multiple arrows at different targets.', 30, 'Art/2DArt/SkillIcons/iconsplitarrow.dds', '[1,2]', '[0,40,57,2,56,14,13,15,31]', '[13]', 'The Ranger paused. She was surrounded. The enemy from the front was merely a diversion, the real threats now flanked her from the left and right. They closed silently in the shadows, believing themselves unseen. Seconds ticked slowly by as she waited, wanting them to be complacent, wanting them to believe her vulnerable. As they drew nearer, her bowstring hand slid gently back, the arrow cocked and waiting. Then, in a blur, her weapon came up, the missile rocketing forth, a streak of hissing death. There was a brief pause, and then if by magic, all three foes fell as one, apparently struck by copies of the same arrow. Lowering her bow, the Ranger smirked, and silently thanked her teacher for the hours spent mastering Split Arrow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/split_arrow.jpg', 0, 'SplitArrow', 0, 22, 1, '[4308,4062,4316,6401,6403,18051]', '[556,24,175,8779,6322,18050]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(69, 'split_arrow_alt_x', 'Split Arrow of Splitting', 'Fires an arrow that splits to hit different targets.', 30, 'Art/2DArt/SkillIcons/iconsplitarrow.dds', '[1,2]', '[0,40,57,2,56,14,13,15,31,59]', '[13]', 'The Ranger paused. She was surrounded. The enemy from the front was merely a diversion, the real threats now flanked her from the left and right. They closed silently in the shadows, believing themselves unseen. Seconds ticked slowly by as she waited, wanting them to be complacent, wanting them to believe her vulnerable. As they drew nearer, her bowstring hand slid gently back, the arrow cocked and waiting. Then, in a blur, her weapon came up, the missile rocketing forth, a streak of hissing death. There was a brief pause, and then if by magic, all three foes fell as one, apparently struck by copies of the same arrow. Lowering her bow, the Ranger smirked, and silently thanked her teacher for the hours spent mastering Split Arrow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/split_arrow.jpg', 0, 'SplitArrow', 0, 22, 1, '[4308,4062,4316,6401,6403,18051]', '[556,24,175,8779,6322,18050]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 68, ''),
(70, 'split_arrow_alt_y', '[DNT] SplitArrowAltY', 'Fires multiple arrows at different targets.', 30, 'Art/2DArt/SkillIcons/iconsplitarrow.dds', '[1,2]', '[0,40,57,2,56,14,13,15,31]', '[13]', 'The Ranger paused. She was surrounded. The enemy from the front was merely a diversion, the real threats now flanked her from the left and right. They closed silently in the shadows, believing themselves unseen. Seconds ticked slowly by as she waited, wanting them to be complacent, wanting them to believe her vulnerable. As they drew nearer, her bowstring hand slid gently back, the arrow cocked and waiting. Then, in a blur, her weapon came up, the missile rocketing forth, a streak of hissing death. There was a brief pause, and then if by magic, all three foes fell as one, apparently struck by copies of the same arrow. Lowering her bow, the Ranger smirked, and silently thanked her teacher for the hours spent mastering Split Arrow.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/split_arrow.jpg', 0, 'SplitArrow', 0, 22, 1, '[4308,4062,4316,6401,6403,18051]', '[556,24,175,8779,6322,18050]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 68, ''),
(71, 'vaal_split_arrow', 'Vaal Split Arrow', '[DNT] Fires multiple arrows which continuously fork as they fly.', 30, 'Art/2DArt/SkillIcons/iconsplitarrow.dds', '[1,2]', '[0,40,2,56,14,13,15,37]', '[13]', '', '', 1, '', 0, 22, 1, '[4308,4062,4316,6401,6403,18051]', '[556,24,175,8779,6322,18050]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(72, 'cold_snap_old', 'Cold Snap', 'Ice crystals protrude from the ground at target location. Monsters in this area take damage and become frozen. The cooldown can be bypassed by expending a Power Charge.', 31, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[1,2,22]', '[1,6,7,13,14,15,21,31,29,55,71]', '[]', 'Damage isn''t everything. Weavers of Magic often find themselves facing a difficult dilemma in combat: fight or flight. When the latter option is decided, nothing does a better job of ensuring safety than Cold Snap. With a snap of the fingers, the caster summons a clump of freezing ice crystals from the ground. These frosty shards stab upward at the targeted location, impaling and freezing anything they strike. Though the damage from Cold Snap is low, it is a powerful when employed against other players in combat.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/cold_snap_new.jpg', 0, 'ColdSnap', 1, 22, 1, '[4288,4107,4265,3501]', '[3396,24,436,3922]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(73, 'vaal_cold_snap_old', 'Vaal Cold Snap', 'A sequence of ice crystals erupts from the ground around the caster, damaging enemies and leaving the ground chilled.', 32, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[4]', '[1,6,7,13,14,15,8,37,29,67,71]', '[]', '', '', 1, '', 1, 22, 1, '[4288,4107,4265]', '[3396,24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(74, 'cold_snap', 'Cold Snap', 'Creates a sudden burst of cold in a targeted area, damaging enemies. Also creates an expanding area which is filled with chilled ground, and deals cold damage over time to enemies. Enemies that die while in the area have a chance to grant Frenzy Charges. The cooldown can be bypassed by expending a Frenzy Charge.', 33, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[1,2,22]', '[1,6,7,13,14,15,21,31,29,55,8,67,71,89,34]', '[]', 'Damage isn''t everything. Weavers of Magic often find themselves facing a difficult dilemma in combat: fight or flight. When the latter option is decided, nothing does a better job of ensuring safety than Cold Snap. With a snap of the fingers, the caster summons a clump of freezing ice crystals from the ground. These frosty shards stab upward at the targeted location, impaling and freezing anything they strike. Though the damage from Cold Snap is low, it is a powerful when employed against other players in combat.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/cold_snap_new.jpg', 1, 'NewColdSnap', 1, 22, 1, '[4288,4107,4265,8134,18540,18561]', '[3396,24,436,8135,11029,13376]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(75, 'cold_snap_alt_x', 'Cold Snap of Power', 'Creates a sudden burst of cold in a targeted area, damaging enemies. The cooldown can be bypassed by expending a Power Charge.', 33, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[1,2,22]', '[1,6,7,13,14,15,21,31,29,55,71,89,34]', '[]', 'Damage isn''t everything. Weavers of Magic often find themselves facing a difficult dilemma in combat: fight or flight. When the latter option is decided, nothing does a better job of ensuring safety than Cold Snap. With a snap of the fingers, the caster summons a clump of freezing ice crystals from the ground. These frosty shards stab upward at the targeted location, impaling and freezing anything they strike. Though the damage from Cold Snap is low, it is a powerful when employed against other players in combat.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/cold_snap_new.jpg', 1, 'NewColdSnap', 1, 22, 1, '[4288,4107,4265,8134,18540,18561]', '[3396,24,436,8135,11029,13376]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 74, ''),
(76, 'cold_snap_alt_y', '[DNT] ColdSnapAltY', 'Creates a sudden burst of cold in a targeted area, damaging enemies. Also creates an expanding area which is filled with chilled ground, and deals cold damage over time to enemies. Enemies that die while in the area have a chance to grant Frenzy Charges. The cooldown can be bypassed by expending a Frenzy Charge.', 33, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[1,2,22]', '[1,6,7,13,14,15,21,31,29,55,8,67,71,89,34]', '[]', 'Damage isn''t everything. Weavers of Magic often find themselves facing a difficult dilemma in combat: fight or flight. When the latter option is decided, nothing does a better job of ensuring safety than Cold Snap. With a snap of the fingers, the caster summons a clump of freezing ice crystals from the ground. These frosty shards stab upward at the targeted location, impaling and freezing anything they strike. Though the damage from Cold Snap is low, it is a powerful when employed against other players in combat.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/cold_snap_new.jpg', 1, 'NewColdSnap', 1, 22, 1, '[4288,4107,4265,8134,18540,18561]', '[3396,24,436,8135,11029,13376]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 74, ''),
(77, 'vaal_cold_snap', 'Vaal Cold Snap', 'Creates a sudden burst of cold around you, damaging enemies. This also creates a chilling area around you which expands and deals cold damage over time to surrounding enemies in addition to chilling them. Enemies that die while in the area grant Frenzy Charges, and you will passively gain Frenzy Charges while there are enemies in the area.', 33, 'Art/2DArt/SkillIcons/iconcoldsnap.dds', '[4]', '[1,6,7,13,14,15,8,37,29,67,71,21,34]', '[]', '', '', 1, 'NewColdSnap', 1, 22, 1, '[4288,4107,4265,8134,18540,18561]', '[3396,24,436,8135,11029,13376]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(78, 'ice_nova', 'Ice Nova', 'A circle of ice expands from the caster.', 34, 'Art/2DArt/SkillIcons/iconfrostnova.dds', '[4]', '[1,6,7,13,14,15,21,31,29,69,71,83]', '[]', 'Reaching deep within, the caster of the mighty Ice Nova assaults surrounding enemies with a shivering blast of pure rime. The shock wave from this nova is often enough to slay outright, and those who survive the blast will be frozen, their very blood chilled solid. With precise use, a master weaver of frost can annihilate his enemies without suffering a scratch.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_nova_new.jpg', 0, 'IceNova', 0, 22, 1, '[4328,4080,4250,8859]', '[457,24,436,8858]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/IceNovaTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(79, 'ice_nova_alt_x', 'Ice Nova of Frostbolts', 'A circle of ice expands from the caster. If the caster targets near their Frostbolt projectiles, it will expand from a number of those projectiles instead. If this skill would repeat when cast this way, it will instead expand again from the same projectiles after a short delay.', 34, 'Art/2DArt/SkillIcons/iconfrostnova.dds', '[1,22]', '[1,6,7,13,14,15,21,31,29,69,71,83]', '[]', 'Reaching deep within, the caster of the mighty Ice Nova assaults surrounding enemies with a shivering blast of pure rime. The shock wave from this nova is often enough to slay outright, and those who survive the blast will be frozen, their very blood chilled solid. With precise use, a master weaver of frost can annihilate his enemies without suffering a scratch.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_nova_new.jpg', 0, 'IceNova', 0, 22, 1, '[4328,4080,4250,8859]', '[457,24,436,8858]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/IceNovaTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 78, ''),
(80, 'ice_nova_alt_y', 'Ice Nova of Deep Freeze', 'A circle of ice expands from the caster.', 34, 'Art/2DArt/SkillIcons/iconfrostnova.dds', '[4]', '[1,6,7,13,14,15,21,31,29,69,71,83]', '[]', 'Reaching deep within, the caster of the mighty Ice Nova assaults surrounding enemies with a shivering blast of pure rime. The shock wave from this nova is often enough to slay outright, and those who survive the blast will be frozen, their very blood chilled solid. With precise use, a master weaver of frost can annihilate his enemies without suffering a scratch.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_nova_new.jpg', 0, 'IceNova', 0, 22, 1, '[4328,4080,4250,8859]', '[457,24,436,8858]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/IceNovaTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 78, ''),
(81, 'vaal_ice_nova', 'Vaal Ice Nova', 'A chilling circle of ice expands from the caster, repeating from every enemy it hits.', 34, 'Art/2DArt/SkillIcons/iconfrostnova.dds', '[1,22]', '[1,6,7,13,14,15,37,29,71,83,21]', '[]', '', '', 1, '', 0, 22, 1, '[4328,4080,4250,8859]', '[457,24,436,8858]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(82, 'ice_nova_triggered', 'Ice Nova', 'A chilling circle of ice expands from the caster. If the caster targets near their Frostbolt projectiles, it will expand from a number of those projectiles instead. If this skill would repeat when cast this way, it will instead expand again from the same projectiles after a short delay.', 34, 'Art/2DArt/SkillIcons/iconfrostnova.dds', '[1,22]', '[1,6,7,13,14,15,21,31,29,69,71,83,36,49,89]', '[]', 'Reaching deep within, the caster of the mighty Ice Nova assaults surrounding enemies with a shivering blast of pure rime. The shock wave from this nova is often enough to slay outright, and those who survive the blast will be frozen, their very blood chilled solid. With precise use, a master weaver of frost can annihilate his enemies without suffering a scratch.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_nova_new.jpg', 0, 'IceNova', 0, 22, 0, '[4328,4080,4250,8859]', '[457,24,436,8858]', '[]', 1, 0, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(83, 'ignite', 'Ignite', 'Sets an enemy on fire from a distance.', 35, 'Art/2DArt/SkillIcons/Ignite.dds', '[2]', '[1,8,13,14,15,31,34,28]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(84, 'fireball', 'Fireball', 'Unleashes a ball of fire towards a target which explodes, damaging nearby foes.', 36, 'Art/2DArt/SkillIcons/iconfireball.dds', '[1,2]', '[2,56,1,6,7,13,14,15,21,31,28,69,71]', '[]', 'Tapping into the chaotic, hungry elemental force of fire, the caster sends a roaring ball of flame hurling at the target. This searing projectile flies unerringly outward, impacting with tremendous force, and burning not only the target, but adjacent foes as well. Skilled wielders of flame can ignite the enemy, causing them to burn for additional damage. A master of the fireball lays waste to all who beset him, reducing his enemies to cinders.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fireball.jpg', 0, 'Fireball', 0, 22, 1, '[4326,4283,4048,11997,11999,18224,18225]', '[613,218,24,2366,8815,18136,3947]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(85, 'fireball_alt_x', '[DNT] FireballAltX', '[DNT] Unleashes two balls of fire towards and away from a target which both explode, damaging nearby foes.', 36, 'Art/2DArt/SkillIcons/iconfireball.dds', '[1,2]', '[2,56,1,6,7,13,14,15,21,31,69,71]', '[]', 'Tapping into the chaotic, hungry elemental force of fire, the caster sends a roaring ball of flame hurling at the target. This searing projectile flies unerringly outward, impacting with tremendous force, and burning not only the target, but adjacent foes as well. Skilled wielders of flame can ignite the enemy, causing them to burn for additional damage. A master of the fireball lays waste to all who beset him, reducing his enemies to cinders.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fireball.jpg', 0, 'Fireball', 0, 22, 1, '[4326,4283,4048,11997,11999,18224,18225]', '[613,218,24,2366,8815,18136,3947]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 84, ''),
(86, 'fireball_alt_y', '[DNT] FireballAltY', 'Unleashes a ball of fire towards a target which explodes, damaging nearby foes.', 36, 'Art/2DArt/SkillIcons/iconfireball.dds', '[1,2]', '[2,56,1,6,7,13,14,15,21,31,28,69,71]', '[]', 'Tapping into the chaotic, hungry elemental force of fire, the caster sends a roaring ball of flame hurling at the target. This searing projectile flies unerringly outward, impacting with tremendous force, and burning not only the target, but adjacent foes as well. Skilled wielders of flame can ignite the enemy, causing them to burn for additional damage. A master of the fireball lays waste to all who beset him, reducing his enemies to cinders.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fireball.jpg', 0, 'Fireball', 0, 22, 1, '[4326,4283,4048,11997,11999,18224,18225]', '[613,218,24,2366,8815,18136,3947]', '[]', 1, 1, '[]', 8, 7, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 84, ''),
(87, 'vaal_fireball', 'Vaal Fireball', 'Launches a series of fireballs in a spiral around the caster.', 36, 'Art/2DArt/SkillIcons/iconfireball.dds', '[1,2]', '[2,56,58,1,6,7,13,14,15,37,28,71,21]', '[]', '', '', 1, '', 0, 22, 1, '[4326,4283,4048,11997,11999,18224,18225]', '[613,218,24,2366,8815,18136,3947]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(88, 'arc', 'Arc', 'An arc of lightning reaches from the caster to a targeted enemy and chains to other enemies, but not immediately back. Each time the arc chains, it will also chain a secondary arc to another enemy that the main arc has not already hit, which cannot chain further.', 37, 'Art/2DArt/SkillIcons/iconarc.dds', '[1,2]', '[1,6,13,14,15,18,21,31,30,69]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/arc.jpg', 0, 'Arc', 0, 22, 1, '[4333,4075,4320,8091,8114,18227,18228]', '[661,24,174,8092,8270,18138,14194]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(89, 'arc_alt_x', 'Arc of Surging', 'An arc of lightning reaches from the caster to a targeted enemy and splits to simultaneously hit several other enemies.', 37, 'Art/2DArt/SkillIcons/iconarc.dds', '[1,2]', '[1,6,13,14,15,21,31,30,69,90]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/arc.jpg', 0, 'Arc', 0, 22, 1, '[4333,4075,4320,8091,8114,18227,18228]', '[661,24,174,8092,8270,18138,14194]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 88, ''),
(90, 'arc_alt_y', 'Arc of Oscillating', 'An arc of lightning reaches from the caster to a targeted enemy and chains to other enemies. Each time the arc chains, it will also chain a secondary arc to another enemy, but this secondary arc cannot chain further.', 37, 'Art/2DArt/SkillIcons/iconarc.dds', '[1,2]', '[1,6,13,14,15,18,21,31,30,69]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/arc.jpg', 0, 'Arc', 0, 22, 1, '[4333,4075,4320,8091,8114,18227,18228]', '[661,24,174,8092,8270,18138,14194]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 88, ''),
(91, 'vaal_arc', 'Vaal Arc', 'A shocking arc of lightning reaches from the caster to a targeted enemy and chains to other enemies. Each time the arc chains from an enemy, it will do so simultaneously to two further enemies, but never to enemies that have already been hit by any of these chains. Also grants a buff making your Arc damage lucky for a short duration.', 37, 'Art/2DArt/SkillIcons/iconarc.dds', '[1,2]', '[1,6,13,14,15,18,37,30,8,21]', '[]', '', '', 1, '', 0, 22, 1, '[4333,4075,4320,8091,8114,18227,18228]', '[661,24,174,8092,8270,18138,14194]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(92, 'raise_zombie', 'Raise Zombie', 'Raises a zombie minion from a corpse, which will follow you and attack enemies with a melee strike.', 38, 'Art/2DArt/SkillIcons/iconraisezombie.dds', '[6,20]', '[1,5,17,13,14,15,21,31,69,76]', '[]', 'Wraeclast is a cursed place, where the dead walk freely. Novice occultists have learned to harness this quality of the land, summoning an undead minion to do their bidding. The incantation is a minor one, so the only required reagent is some fresh kill lying about. Once summoned, the mindless creature will wander about defending its master. Higher levels of skill will summon an entity that moves quicker, hits harder, and absorbs more damage.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_zombie_new.jpg', 0, 'RaiseZombie', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(93, 'raise_zombie_alt_x', 'Raise Zombie of Slamming', 'Raises a zombie minion from a corpse, which will follow you and attack enemies with a melee strike and an area of effect slam.', 38, 'Art/2DArt/SkillIcons/iconraisezombie.dds', '[6,20]', '[1,5,17,13,14,15,21,31,69,76]', '[]', 'Wraeclast is a cursed place, where the dead walk freely. Novice occultists have learned to harness this quality of the land, summoning an undead minion to do their bidding. The incantation is a minor one, so the only required reagent is some fresh kill lying about. Once summoned, the mindless creature will wander about defending its master. Higher levels of skill will summon an entity that moves quicker, hits harder, and absorbs more damage.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_zombie_new.jpg', 0, 'RaiseZombie', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, 92, ''),
(94, 'raise_zombie_alt_y', 'Raise Zombie of Falling', 'Raises necromantic energies into the sky above a targeted location, where they coalesce into a zombie minion. The minion then attacks by falling to the ground, causing an impact that deals damage in an area. The zombie cannot survive the impact.', 38, 'Art/2DArt/SkillIcons/iconraisezombie.dds', '[1,22]', '[1,5,17,13,14,15,21,31,69,76]', '[]', 'Wraeclast is a cursed place, where the dead walk freely. Novice occultists have learned to harness this quality of the land, summoning an undead minion to do their bidding. The incantation is a minor one, so the only required reagent is some fresh kill lying about. Once summoned, the mindless creature will wander about defending its master. Higher levels of skill will summon an entity that moves quicker, hits harder, and absorbs more damage.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_zombie_new.jpg', 0, 'RaiseZombie', 0, 22, 1, '[]', '[]', '[0,19]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, 92, ''),
(95, 'righteous_fire', 'Righteous Fire', 'Engulfs you in magical fire that rapidly burns you and nearby enemies. Your spell damage is substantially increased while under this effect. The effect ends when you have 1 life remaining.', 39, 'Art/2DArt/SkillIcons/righteousfire.dds', '[4]', '[1,4,7,24,34,28,14,31,63,71,84,85,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/righteous_fire.jpg', 0, 'RighteousFire', 0, 22, 1, '[4089,4254,4577]', '[24,436,25]', '[]', 1, 1, '[18319]', 8, NULL, 0, 'Metadata/Monsters/Totems/RighteousFireTotem.ais', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(96, 'righteous_fire_alt_x', 'Righteous Fire of Arcane Devotion', 'Engulfs you in magical fire that rapidly burns you and nearby enemies. Your cast speed is substantially increased while under this effect. The effect ends when you have 1 life remaining. Requires mana.', 39, 'Art/2DArt/SkillIcons/righteousfire.dds', '[4]', '[1,4,7,24,34,28,31,63,71,84,85,89,48]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/righteous_fire.jpg', 0, 'RighteousFire', 0, 22, 1, '[4089,4254,4577]', '[24,436,25]', '[]', 1, 1, '[18319]', 8, NULL, 0, 'Metadata/Monsters/Totems/RighteousFireTotem.ais', '[16,10,11,17,12,13]', 0, 0, 1, 95, ''),
(97, 'righteous_fire_alt_y', '[DNT] RighteousFireAltY', 'Engulfs you in magical fire that rapidly burns you and nearby enemies. Your spell damage is substantially increased while under this effect. The effect ends when you have 1 life remaining.', 39, 'Art/2DArt/SkillIcons/righteousfire.dds', '[4]', '[1,4,7,24,34,28,14,31,63,71,84,85,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/righteous_fire.jpg', 0, 'RighteousFire', 0, 22, 1, '[4089,4254,4577]', '[24,436,25]', '[]', 1, 1, '[18319]', 8, NULL, 0, 'Metadata/Monsters/Totems/RighteousFireTotem.ais', '[16,10,11,17]', 0, 0, 1, 95, ''),
(98, 'vaal_righteous_fire', 'Vaal Righteous Fire', 'Sacrifices a portion of your Life and Energy Shield to engulf you in magical fire that rapidly burns nearby enemies for a duration. Your spell damage is increased while under this effect.', 40, 'Art/2DArt/SkillIcons/righteousfire.dds', '[4]', '[1,4,7,24,34,28,14,37,8,71,63,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[4089,4254,4577]', '[24,436,25]', '[]', 1, 1, '[18319]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(99, 'vaal_righteous_fire_old', 'Vaal Righteous Fire', 'A fiery blast removes your energy shield and all but 1 life, exploding outwards to deal fire damage to nearby enemies based on the life and energy shield lost.', 41, 'Art/2DArt/SkillIcons/righteousfire.dds', '[4]', '[1,7,6,37,28,71]', '[]', '', '', 1, '', 0, 22, 1, '[4089,4254]', '[24,436]', '[]', 1, 1, '[18319]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(100, 'fire_weapon', 'Fire Weapon', 'Infuse the player''s current weapon with additional fire damage for a short time.', 42, 'Art/2DArt/SkillIcons/iconfireball.dds', '[4]', '[1,4,8,14,31,28]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(101, 'damage_infusion', 'Damage Infusion', 'Moves damage from nearby enemies to the target enemy. They are healed for the amount of damage moved.', 43, 'Art/2DArt/SkillIcons/icononfire.dds', '[2]', '[1,7,13,14,15,21,31,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(102, 'discharge', 'Discharge', 'Discharge all the character''s charges to deal elemental damage to all nearby monsters.', 44, 'Art/2DArt/SkillIcons/discharge.dds', '[4]', '[1,6,7,21,31,28,29,30,69,71,83,89]', '[]', 'Blasting enemies with waves of frost and lightning isn''t just a talent reserved for pure weavers of magic. With the Discharge skill, any combatant can channel accumulated charges into a swirling tower of seething energy. The composition of the blast varies depending on the type of charges consumed, dealing cold with Frenzy, fire from Endurance, and lightning from Power. Regardless of the charge type, surrounding foes are blown to bits.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/discharge.jpg', 0, 'Discharge', 0, 22, 1, '[3664,3665,12669,12670,12671,13250,18256]', '[24,436,10799,11981,12665,5827,10860]', '[]', 1, 1, '[3666]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(103, 'discharge_alt_x', 'Discharge of Misery', 'Discharge all the character''s charges to deal elemental damage to all nearby monsters.', 44, 'Art/2DArt/SkillIcons/discharge.dds', '[4]', '[1,6,7,21,31,28,29,30,69,71,83]', '[]', 'Blasting enemies with waves of frost and lightning isn''t just a talent reserved for pure weavers of magic. With the Discharge skill, any combatant can channel accumulated charges into a swirling tower of seething energy. The composition of the blast varies depending on the type of charges consumed, dealing cold with Frenzy, fire from Endurance, and lightning from Power. Regardless of the charge type, surrounding foes are blown to bits.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/discharge.jpg', 0, 'Discharge', 0, 22, 1, '[3664,3665,12669,12670,12671,13250,18256]', '[24,436,10799,11981,12665,5827,10860]', '[]', 1, 1, '[3666]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 102, ''),
