(105, 'town_portal', 'Portal', 'Creates a portal to the current area''s town.', 45, 'Art/2DArt/SkillIcons/townportal.dds', '[4]', '[1,13,14,15,31,22]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
