(114, 'cobra_lash', 'Cobra Lash', 'Fires a poisonous projectile based on your weapon that will chain between enemies. Requires a Dagger or Claw.', 51, 'Art/2DArt/SkillIcons/CobraLash.dds', '[1,2]', '[0,40,2,56,6,31,41]', '[7,6,56]', '', '', 1, '', 0, 22, 1, '[10523,10524,10525,18200,18201]', '[24,177,174,18121,1108]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
