(121, 'skeleton_projectile_lightning', '', '', 56, '', '[2,1]', '[1,6,21,2,56,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(122, 'spark', 'Spark', 'Launches unpredictable sparks that move randomly until they hit an enemy or expire.', 57, 'Art/2DArt/SkillIcons/spark.dds', '[1,2]', '[1,2,56,6,8,13,14,15,21,31,30,69]', '[]', 'Lightning is a fickle servant. However, skilled casters have learned to harness this frenetic element to devastating effect. With a single incantation, two pulsing strands of electric energy appear, and begin to move erratically around the battlefield. Whenever one contacts an enemy, it discharges, dealing tremendous damage and frequently causing paralysis.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/spark.jpg', 0, 'Spark', 0, 22, 1, '[4060,4315,4291,5559,6394,6396,6437,18342,18361]', '[24,175,177,174,1816,175,217,18287,18360]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(123, 'spark_alt_x', 'Spark of the Nova', 'Launches unpredictable sparks in all directions that move randomly until they hit an enemy or expire.', 57, 'Art/2DArt/SkillIcons/spark.dds', '[1,2]', '[1,2,56,6,8,13,14,15,21,31,30,69]', '[]', 'Lightning is a fickle servant. However, skilled casters have learned to harness this frenetic element to devastating effect. With a single incantation, two pulsing strands of electric energy appear, and begin to move erratically around the battlefield. Whenever one contacts an enemy, it discharges, dealing tremendous damage and frequently causing paralysis.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/spark.jpg', 0, 'Spark', 0, 22, 1, '[4060,4315,4291,5559,6394,6396,6437,18342,18361]', '[24,175,177,174,1816,175,217,18287,18360]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 122, ''),
(124, 'spark_alt_y', 'Spark of Unpredictability', 'Launches unpredictable sparks with that move randomly with large differences in speed and distance until they hit an enemy or expire.', 57, 'Art/2DArt/SkillIcons/spark.dds', '[1,2]', '[1,2,56,6,8,13,14,15,21,31,30,69]', '[]', 'Lightning is a fickle servant. However, skilled casters have learned to harness this frenetic element to devastating effect. With a single incantation, two pulsing strands of electric energy appear, and begin to move erratically around the battlefield. Whenever one contacts an enemy, it discharges, dealing tremendous damage and frequently causing paralysis.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/spark.jpg', 0, 'Spark', 0, 22, 1, '[4060,4315,4291,5559,6394,6396,6437,18342,18361]', '[24,175,177,174,1816,175,217,18287,18360]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 122, ''),
(125, 'vaal_spark', 'Vaal Spark', 'Continuously launches unpredictable sparks in all directions that move randomly until they hit an enemy or expire.', 57, 'Art/2DArt/SkillIcons/spark.dds', '[1,2]', '[1,2,56,58,6,8,13,14,15,37,30,21]', '[]', '', '', 1, '', 0, 22, 1, '[4060,4315,4291,5559,6394,6396,6437,18342,18361]', '[24,175,177,174,1816,175,217,18287,18360]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(126, 'ice_spear', 'Ice Spear', 'Launches shards of ice in rapid succession. After travelling a short distance they change to a second form, which moves much faster and pierces through enemies.', 58, 'Art/2DArt/SkillIcons/IceSpear.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Harnessing the freezing might of the far North, the caster conjures a lance of razor sharp ice crystal, and launches it at a target. The Ice Spear pierces armour and flesh alike, rocketing towards an enemy and exploding in a blast of deadly rime. The blast will freeze the blood of its target, locking them in place for a substantial duration. Enemies pierced by the spear take significant damage, but will avoid the paralysis of the main explosion.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_spear.jpg', 0, 'IceSpear', 0, 22, 1, '[4081,8852,18249,18250,4337]', '[24,175,1816,1132,1256]', '[]', 1, 1, '[8864]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(127, 'ice_spear_alt_x', 'Ice Spear of Splitting', 'Launches a shard of ice that splits on hitting terrain or enemies. After splitting, the projectiles are in second form, which moves much faster and pierces through enemies.', 58, 'Art/2DArt/SkillIcons/IceSpear.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Harnessing the freezing might of the far North, the caster conjures a lance of razor sharp ice crystal, and launches it at a target. The Ice Spear pierces armour and flesh alike, rocketing towards an enemy and exploding in a blast of deadly rime. The blast will freeze the blood of its target, locking them in place for a substantial duration. Enemies pierced by the spear take significant damage, but will avoid the paralysis of the main explosion.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_spear.jpg', 0, 'IceSpear', 0, 22, 1, '[4081,8852,18249,18250,4337]', '[24,175,1816,1132,1256]', '[]', 1, 1, '[8864]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 126, ''),
(128, 'ice_spear_alt_y', '[DNT] IceSpearAltY', 'Launches shards of ice in rapid succession. After travelling a short distance they change to a second form, which moves much faster and pierces through enemies.', 58, 'Art/2DArt/SkillIcons/IceSpear.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Harnessing the freezing might of the far North, the caster conjures a lance of razor sharp ice crystal, and launches it at a target. The Ice Spear pierces armour and flesh alike, rocketing towards an enemy and exploding in a blast of deadly rime. The blast will freeze the blood of its target, locking them in place for a substantial duration. Enemies pierced by the spear take significant damage, but will avoid the paralysis of the main explosion.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/ice_spear.jpg', 0, 'IceSpear', 0, 22, 1, '[4081,8852,18249,18250,4337]', '[24,175,1816,1132,1256]', '[]', 1, 1, '[8864]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 126, ''),
(129, 'raise_spectre', 'Raise Spectre', 'Raises a spectral version of a defeated foe as a minion to fight for you in battle.', 59, 'Art/2DArt/SkillIcons/iconraisespecter.dds', '[6,20]', '[1,5,17,13,14,15,21,31,69,76]', '[]', 'True masters of the dark arts learn to use their enemy''s greatest strengths against them, binding the souls of the fallen to their bidding. With a dark incantation, the caster''s words imbue a slain being with dark energy, animating it with sinister strength and purpose. The raised entity possesses all the abilities it had while living, augmented further by the skill of its new master. With practice, many raised specters can be controlled at once, creating an army of undead to lay waste to everything in its path.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_spectre.jpg', 0, 'RaiseSpectre', 0, 22, 1, '[7413]', '[6339]', '[0,19,20,23,1,6,7,2,18,8,25,32,35,34,47,40,56,62]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(130, 'raise_spectre_alt_x', 'Raise Spectre of Transience', 'Raises a spectral version of a defeated foe as a temporary minion to fight for you in battle for a duration.', 59, 'Art/2DArt/SkillIcons/iconraisespecter.dds', '[6,20]', '[1,5,17,13,14,15,21,31,69,76,8]', '[]', 'True masters of the dark arts learn to use their enemy''s greatest strengths against them, binding the souls of the fallen to their bidding. With a dark incantation, the caster''s words imbue a slain being with dark energy, animating it with sinister strength and purpose. The raised entity possesses all the abilities it had while living, augmented further by the skill of its new master. With practice, many raised specters can be controlled at once, creating an army of undead to lay waste to everything in its path.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_spectre.jpg', 0, 'RaiseSpectre', 0, 22, 1, '[7413]', '[6339]', '[0,19,20,23,1,6,7,2,18,8,25,32,35,34,47,40,56,62]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 129, ''),
(131, 'raise_spectre_alt_y', '[DNT] RaiseSpectreAltY', 'Raises a spectral version of a defeated foe as a minion to fight for you in battle.', 59, 'Art/2DArt/SkillIcons/iconraisespecter.dds', '[6,20]', '[1,5,17,13,14,15,21,31,69,76]', '[]', 'True masters of the dark arts learn to use their enemy''s greatest strengths against them, binding the souls of the fallen to their bidding. With a dark incantation, the caster''s words imbue a slain being with dark energy, animating it with sinister strength and purpose. The raised entity possesses all the abilities it had while living, augmented further by the skill of its new master. With practice, many raised specters can be controlled at once, creating an army of undead to lay waste to everything in its path.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/raise_spectre.jpg', 0, 'RaiseSpectre', 0, 22, 1, '[7413]', '[6339]', '[0,19,20,23,1,6,7,2,18,8,25,32,35,34,47,40,56,62]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 129, ''),
(132, 'infernal_blow_old', 'Infernal Blow', '[UNUSED] Hits enemies, converting some of your physical damage to fire damage. If an enemy dies soon after being hit, they will explode, dealing fire damage to nearby enemies. The damage from this explosion cannot be reflected. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 60, 'Art/2DArt/SkillIcons/iconinnerfire.dds', '[1,2]', '[0,7,20,23,19,28]', '[9,10,15,11,16,12,32,17,14,36,57]', 'Tracing a series of fiery runes on the length of their weapon, the user prepares to unleash the Infernal Blow. Once imbued with fiery energy, the weapon discharges the moment it strikes any enemy. Infernal Blow burns anything struck with searing Hellfire, incinerating bone, flesh and armour. Perhaps the deadliest property of the enchantment lies in what follows a fatal hit. Any foe slain by Infernal Blow will explode in a violent conflagration, showering anything nearby with flame, igniting and killing with abandon.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/infernal_blow.jpg', 0, 'InfernalBlow', 0, 22, 1, '[4053,4324,4241,7921,18222,18223]', '[24,449,436,7922,13018,18135]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,4]', 0, 0, 1, NULL, ''),
(133, 'infernal_blow', 'Infernal Blow', 'Attacks with your weapon, applying a charged debuff to enemies hit by your strike, and an uncharged debuff to any other enemies hit. Upon reaching 6 charges, expiring, or the enemy''s death, the charged debuff is removed to damage that and other surrounding enemies. Enemies with either debuff explode when they die, damaging other surrounding enemies. Damage from this explosion cannot be reflected. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 61, 'Art/2DArt/SkillIcons/iconinnerfire.dds', '[1,2]', '[0,7,20,23,19,28,8]', '[9,10,15,11,16,12,32,17,14,36,57]', 'Tracing a series of fiery runes on the length of their weapon, the user prepares to unleash the Infernal Blow. Once imbued with fiery energy, the weapon discharges the moment it strikes any enemy. Infernal Blow burns anything struck with searing Hellfire, incinerating bone, flesh and armour. Perhaps the deadliest property of the enchantment lies in what follows a fatal hit. Any foe slain by Infernal Blow will explode in a violent conflagration, showering anything nearby with flame, igniting and killing with abandon.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/infernal_blow.jpg', 1, 'InfernalBlowNew', 0, 22, 1, '[4053,4324,4241,7921,18222,18223]', '[24,449,436,7922,13018,18135]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,4]', 0, 0, 1, NULL, ''),
(134, 'infernal_blow_alt_x', 'Infernal Blow of Immolation', 'Attacks with your weapon, applying a charged debuff to you the first time you hit an enemy with this skill. Upon reaching 6 charges, or charges expiring, the charged debuff is removed to damage nearby enemies. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 61, 'Art/2DArt/SkillIcons/iconinnerfire.dds', '[1,2]', '[0,7,20,23,19,28,8]', '[9,10,15,11,16,12,32,17,14,36,57]', 'Tracing a series of fiery runes on the length of their weapon, the user prepares to unleash the Infernal Blow. Once imbued with fiery energy, the weapon discharges the moment it strikes any enemy. Infernal Blow burns anything struck with searing Hellfire, incinerating bone, flesh and armour. Perhaps the deadliest property of the enchantment lies in what follows a fatal hit. Any foe slain by Infernal Blow will explode in a violent conflagration, showering anything nearby with flame, igniting and killing with abandon.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/infernal_blow.jpg', 1, 'InfernalBlowNew', 0, 22, 1, '[4053,4324,4241,7921,18222,18223]', '[24,449,436,7922,13018,18135]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,4]', 0, 0, 1, 133, ''),
(135, 'infernal_blow_alt_y', '[DNT] InfernalBlowAltY', 'Attacks with your weapon, applying a charged debuff to enemies hit by your strike, and an uncharged debuff to any other enemies hit. Upon reaching 6 charges, expiring, or the enemy''s death, the charged debuff is removed to damage that and other surrounding enemies. Enemies with either debuff explode when they die, damaging other surrounding enemies. Damage from this explosion cannot be reflected. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 61, 'Art/2DArt/SkillIcons/iconinnerfire.dds', '[1,2]', '[0,7,20,23,19,28,8]', '[9,10,15,11,16,12,32,17,14,36,57]', 'Tracing a series of fiery runes on the length of their weapon, the user prepares to unleash the Infernal Blow. Once imbued with fiery energy, the weapon discharges the moment it strikes any enemy. Infernal Blow burns anything struck with searing Hellfire, incinerating bone, flesh and armour. Perhaps the deadliest property of the enchantment lies in what follows a fatal hit. Any foe slain by Infernal Blow will explode in a violent conflagration, showering anything nearby with flame, igniting and killing with abandon.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/infernal_blow.jpg', 1, 'InfernalBlowNew', 0, 22, 1, '[4053,4324,4241,7921,18222,18223]', '[24,449,436,7922,13018,18135]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,4]', 0, 0, 1, 133, ''),
(136, 'glacial_hammer', 'Glacial Hammer', 'Hits enemies, converting some of your physical damage to cold damage. If a non-unique enemy is frozen and is on less than one third life, they will shatter when hit by Glacial Hammer. If striking three times in a row, the third strike will freeze enemies more easily. Requires a Mace, Sceptre or Staff.', 62, 'Art/2DArt/SkillIcons/icehammer.dds', '[1,2]', '[0,20,23,19,29,43]', '[12,32,17,14,57]', 'Where Infernal Blow burns hot, Glacial Hammer freezes to the bone. The skill infuses a Mace or Staff with the essence of pure ice, making a weapon so cold it can barely be handled. A successful hit from Glacial Hammer deals grievous damage, and if the target is already frozen and near death, it will shatter into thousands of shards. The more skilled one becomes at inscribing the runes for Glacial Hammer, the greater the frostbite becomes, eventually leaving most foes frozen solid.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/glacial_hammer.jpg', 0, 'GlacialHammer', 0, 22, 1, '[4327,4050,4345,3488,5510,5508,18213,3488]', '[457,24,450,3923,1106,5515,18128,21644]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(137, 'glacial_hammer_alt_x', 'Glacial Hammer of Shattering', 'Hits enemies, converting some of your physical damage to cold damage. If striking three times in a row, the third strike will be a critical strike. Requires a Mace, Sceptre or Staff.', 62, 'Art/2DArt/SkillIcons/icehammer.dds', '[1,2]', '[0,20,23,19,29,43]', '[12,32,17,14,57]', 'Where Infernal Blow burns hot, Glacial Hammer freezes to the bone. The skill infuses a Mace or Staff with the essence of pure ice, making a weapon so cold it can barely be handled. A successful hit from Glacial Hammer deals grievous damage, and if the target is already frozen and near death, it will shatter into thousands of shards. The more skilled one becomes at inscribing the runes for Glacial Hammer, the greater the frostbite becomes, eventually leaving most foes frozen solid.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/glacial_hammer.jpg', 0, 'GlacialHammer', 0, 22, 1, '[4327,4050,4345,3488,5510,5508,18213,3488]', '[457,24,450,3923,1106,5515,18128,21644]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 136, ''),
(138, 'glacial_hammer_alt_y', '[DNT] GlacialHammerAltY', 'Hits enemies, converting some of your physical damage to cold damage. If a non-unique enemy is frozen and is on less than one third life, they will shatter when hit by Glacial Hammer. If striking three times in a row, the third strike will freeze enemies more easily. Requires a Mace, Sceptre or Staff.', 62, 'Art/2DArt/SkillIcons/icehammer.dds', '[1,2]', '[0,20,23,19,29,43]', '[12,32,17,14,57]', 'Where Infernal Blow burns hot, Glacial Hammer freezes to the bone. The skill infuses a Mace or Staff with the essence of pure ice, making a weapon so cold it can barely be handled. A successful hit from Glacial Hammer deals grievous damage, and if the target is already frozen and near death, it will shatter into thousands of shards. The more skilled one becomes at inscribing the runes for Glacial Hammer, the greater the frostbite becomes, eventually leaving most foes frozen solid.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/glacial_hammer.jpg', 0, 'GlacialHammer', 0, 22, 1, '[4327,4050,4345,3488,5510,5508,18213,3488]', '[457,24,450,3923,1106,5515,18128,21644]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 136, ''),
(139, 'vaal_glacial_hammer', 'Vaal Glacial Hammer', 'Hits enemies, converting some of your physical damage to cold damage. It traps enemies with you in a circle of ice so that they can''t escape. Requires a Mace, Sceptre or Staff.', 63, 'Art/2DArt/SkillIcons/icehammer.dds', '[1,2]', '[0,20,19,8,7,37,29,121]', '[12,32,17,14,57]', '', '', 1, '', 0, 22, 1, '[4327,3488,5510,5508,18213]', '[457,3923,485,5515,18128]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(140, 'wall_of_force', 'Wall of Force', 'Creates a wall of force which allies and enemies can pass through, but allied projectiles which can collide with enemies will also collide with this wall, and can chain from it to other targets. Projectiles can only collide with a single Wall of Force, and no more than once.', 1308, 'Art/2DArt/SkillIcons/WallofForce.dds', '[1,2]', '[1,8,13,14,15,31,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 3, 0, '', '[]', 0, 0, 1, NULL, ''),
(141, 'frost_wall', 'Frost Wall', 'Creates a wall of ice which holds back enemies. Targets under the wall are damaged and pushed back.', 64, 'Art/2DArt/SkillIcons/IceWall.dds', '[1,2]', '[1,6,8,13,14,15,21,31,29,55,89]', '[]', 'The Bandits drew closer and they were gaining confidence. The first few volleys of Fireballs had been more than enough to drive them away, killing several in the process. They retreated to the underbrush, where they regrouped and planned. Now they advanced again, shields up, safe in their great numbers. The Witch surveyed her opponents, wand resting lightly in hand, waiting for the right moment.__BREAK__ __BREAK__ It came soon enough, for the Bandits raised their weapons aloft, and came on with a cry. Their blood lust overcame their caution, and the Witch made her move. She flicked her wand quickly, and at once a great wall of solid ice sprang up in the Bandit''s path. They crashed into it full force, and before they could recover, three other towering walls rose around them, locking them in an icy prison. Smiling, the Witch conjured a roaring pillar of fire in the center of the freezing prison, and delighted in the shrieks of her trapped enemies roasting alive.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/frost_wall.jpg', 0, 'FrostWall', 0, 22, 1, '[4425,4111,4400]', '[3396,24,217]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(142, 'frost_wall_alt_x', 'Frost Wall of Encroachment', 'Creates a wall of ice which holds back enemies. Targets under the wall are damaged and pushed back, with more damage dealt the more frost walls are currently active.', 64, 'Art/2DArt/SkillIcons/IceWall.dds', '[1,2]', '[1,6,8,13,14,15,21,31,29,55,89]', '[]', 'The Bandits drew closer and they were gaining confidence. The first few volleys of Fireballs had been more than enough to drive them away, killing several in the process. They retreated to the underbrush, where they regrouped and planned. Now they advanced again, shields up, safe in their great numbers. The Witch surveyed her opponents, wand resting lightly in hand, waiting for the right moment.__BREAK__ __BREAK__ It came soon enough, for the Bandits raised their weapons aloft, and came on with a cry. Their blood lust overcame their caution, and the Witch made her move. She flicked her wand quickly, and at once a great wall of solid ice sprang up in the Bandit''s path. They crashed into it full force, and before they could recover, three other towering walls rose around them, locking them in an icy prison. Smiling, the Witch conjured a roaring pillar of fire in the center of the freezing prison, and delighted in the shrieks of her trapped enemies roasting alive.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/frost_wall.jpg', 0, 'FrostWall', 0, 22, 1, '[4425,4111,4400]', '[3396,24,217]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 141, ''),
(143, 'frost_wall_alt_y', '[DNT] FrostWallAltY', 'Creates a wall of ice which holds back enemies. Targets under the wall are damaged and pushed back.', 64, 'Art/2DArt/SkillIcons/IceWall.dds', '[1,2]', '[1,6,8,13,14,15,21,31,29,55,89]', '[]', 'The Bandits drew closer and they were gaining confidence. The first few volleys of Fireballs had been more than enough to drive them away, killing several in the process. They retreated to the underbrush, where they regrouped and planned. Now they advanced again, shields up, safe in their great numbers. The Witch surveyed her opponents, wand resting lightly in hand, waiting for the right moment.__BREAK__ __BREAK__ It came soon enough, for the Bandits raised their weapons aloft, and came on with a cry. Their blood lust overcame their caution, and the Witch made her move. She flicked her wand quickly, and at once a great wall of solid ice sprang up in the Bandit''s path. They crashed into it full force, and before they could recover, three other towering walls rose around them, locking them in an icy prison. Smiling, the Witch conjured a roaring pillar of fire in the center of the freezing prison, and delighted in the shrieks of her trapped enemies roasting alive.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/frost_wall.jpg', 0, 'FrostWall', 0, 22, 1, '[4425,4111,4400]', '[3396,24,217]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 141, ''),
(144, 'frost_wall_behind_target', '', '', 64, '', '[9]', '[1,6,8,13,14,15,21,31,29]', '[]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(145, 'freezing_pulse', 'Freezing Pulse', 'An icy projectile which has a chance to freeze enemies it passes through. The projectile fades quickly, reducing damage and freezing chance until it dissipates.', 65, 'Art/2DArt/SkillIcons/FreezingPulse.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Sometimes a spellcaster just needs crowd control. When beset by a hostile throng, masters of ice magic frequently employ the deadly Freezing Pulse. The spell pierces easily through the thickest hide and the toughest armour, spinning and freezing in an icy whirl until it impacts a distant target. The Pulse is at peak strength when it''s cast, so it has the greatest effect on enemies that are right up next to the caster. Of course, these are also the enemies presenting the most threat, and they are left frozen solid or slain outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/freezing_pulse.jpg', 0, 'FreezingPulse', 0, 22, 1, '[4282,4049,4290,5481,5483,18202,18204]', '[218,24,177,175,13545,6120,18122]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/FreezingPulseTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(146, 'freezing_pulse_alt_x', '[DNT] FreezingPulseAltX', 'An icy projectile which has a chance to freeze enemies it passes through. The projectile fades quickly, reducing damage and freezing chance until it dissipates.', 65, 'Art/2DArt/SkillIcons/FreezingPulse.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Sometimes a spellcaster just needs crowd control. When beset by a hostile throng, masters of ice magic frequently employ the deadly Freezing Pulse. The spell pierces easily through the thickest hide and the toughest armour, spinning and freezing in an icy whirl until it impacts a distant target. The Pulse is at peak strength when it''s cast, so it has the greatest effect on enemies that are right up next to the caster. Of course, these are also the enemies presenting the most threat, and they are left frozen solid or slain outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/freezing_pulse.jpg', 0, 'FreezingPulse', 0, 22, 1, '[4282,4049,4290,5481,5483,18202,18204]', '[218,24,177,175,13545,6120,18122]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/FreezingPulseTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 145, ''),
(147, 'freezing_pulse_alt_y', '[DNT] FreezingPulseAltY', 'An icy projectile which has a chance to freeze enemies it passes through. The projectile fades quickly, reducing damage and freezing chance until it dissipates.', 65, 'Art/2DArt/SkillIcons/FreezingPulse.dds', '[1,2]', '[1,2,56,6,13,14,15,21,31,29,69]', '[]', 'Sometimes a spellcaster just needs crowd control. When beset by a hostile throng, masters of ice magic frequently employ the deadly Freezing Pulse. The spell pierces easily through the thickest hide and the toughest armour, spinning and freezing in an icy whirl until it impacts a distant target. The Pulse is at peak strength when it''s cast, so it has the greatest effect on enemies that are right up next to the caster. Of course, these are also the enemies presenting the most threat, and they are left frozen solid or slain outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/freezing_pulse.jpg', 0, 'FreezingPulse', 0, 22, 1, '[4282,4049,4290,5481,5483,18202,18204]', '[218,24,177,175,13545,6120,18122]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/FreezingPulseTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 145, ''),
(148, 'shock_nova_monster', 'Shock Nova', 'Casts a shocking ring of lightning which deals damage to monsters it touches. Monsters in the centre of the ring receive no damage.', 66, 'Art/2DArt/SkillIcons/ShockNova.dds', '[2]', '[1,6,7,13,14,15,21,31,30,69,71,83]', '[]', 'Harnessing the power of raw thunder, the caster opens a rift around them that draws a ring of crackling lightning around their body. The deadly voltage will harm anything it touches, but the gap near the caster in the centre of the ring is unaffected, so the skill is best used when surrounded by many distant foes.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/shock_nova.jpg', 0, 'ShockNova', 0, 22, 1, '[4099,4267,18208,18211]', '[24,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(149, 'viper_strike', 'Viper Strike', 'Hits enemies, converting some of your physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, will strike with both weapons. Requires a claw, dagger or sword.', 67, 'Art/2DArt/SkillIcons/ViperStrike.dds', '[1,2]', '[0,8,23,19,20,41]', '[6,7,9,10,15,56]', 'The thieves guilds of Oriath teach a wicked skill to all initiates - the feared Viper Strike. Employing the skill, a claw, dagger or sword user coats their weapon with deadly venom, a concoction so virulent it permanently marks any weapon it contacts. Once the toxin is applied, the weapon will poison any it strikes, burning deep into their veins, causing wracking, crippling pain. Additional hits will increase the concentration of the toxin, stacking it up to lethal levels quickly. Few have survived an assault of Viper Strike and those who have never forget the agony.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/viper_strike.jpg', 0, 'ViperStrike', 0, 22, 1, '[4309,4067,4298,3430,18234]', '[556,24,217,6308,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(150, 'viper_strike_alt_x', 'Viper Strike of the Mamba', 'Hits enemies, converting some of your physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, deals the damage of both weapons in one strike. Requires a claw, dagger or sword.', 67, 'Art/2DArt/SkillIcons/ViperStrike.dds', '[1,2]', '[0,8,23,19,20,41]', '[6,7,9,10,15,56]', 'The thieves guilds of Oriath teach a wicked skill to all initiates - the feared Viper Strike. Employing the skill, a claw, dagger or sword user coats their weapon with deadly venom, a concoction so virulent it permanently marks any weapon it contacts. Once the toxin is applied, the weapon will poison any it strikes, burning deep into their veins, causing wracking, crippling pain. Additional hits will increase the concentration of the toxin, stacking it up to lethal levels quickly. Few have survived an assault of Viper Strike and those who have never forget the agony.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/viper_strike.jpg', 0, 'ViperStrike', 0, 22, 1, '[4309,4067,4298,3430,18234]', '[556,24,217,6308,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 149, ''),
(151, 'viper_strike_alt_y', '[DNT] ViperStrikeAltY', 'Hits enemies, converting some of your physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, will strike with both weapons. Requires a claw, dagger or sword.', 67, 'Art/2DArt/SkillIcons/ViperStrike.dds', '[1,2]', '[0,8,23,19,20,41]', '[6,7,9,10,15,56]', 'The thieves guilds of Oriath teach a wicked skill to all initiates - the feared Viper Strike. Employing the skill, a claw, dagger or sword user coats their weapon with deadly venom, a concoction so virulent it permanently marks any weapon it contacts. Once the toxin is applied, the weapon will poison any it strikes, burning deep into their veins, causing wracking, crippling pain. Additional hits will increase the concentration of the toxin, stacking it up to lethal levels quickly. Few have survived an assault of Viper Strike and those who have never forget the agony.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/viper_strike.jpg', 0, 'ViperStrike', 0, 22, 1, '[4309,4067,4298,3430,18234]', '[556,24,217,6308,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 149, ''),
(152, 'phase_run_old', 'Phase Run', 'Gain a buff that makes you move faster, become harder to detect, and no longer have your movement impeded by enemies. Your next attack also deals extra damage. Performing any skill removes this buff but grants a new buff that increases the damage of your attacks for a short time. Consumes Frenzy Charges to increase duration.', 68, 'Art/2DArt/SkillIcons/iconphaserun.dds', '[4]', '[1,4,8,31,27,78,89]', '[]', 'In battle, the best offense is sometimes the best defence. Those who live to survive for a later battle recognize that there is no shame in flight, when flight is the only option. When haste is needed, there is no better tool than Phase Run. With a cry, the skill imbues the caster with incredible speed, allowing them to sprint past hapless enemies to safety. The enchantment also causes their form to blur, making them less likely to receive attack. If the phased runner chooses to melee an enemy, they will lose their speed burst but deliver a devastating blow to their target.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/phase_run.jpg', 1, 'PhaseRun', 0, 22, 1, '[4569]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(153, 'explosive_arrow_old', 'Explosive Arrow', 'Fires an arrow which acts as a short duration fuse. Applying additional arrows to an enemy extends the duration. When the target dies or the fuses expire, the arrows explode, dealing fire AoE damage to nearby enemies. The AoE radius is proportional to the number of arrows upon death.', 69, 'Art/2DArt/SkillIcons/fusearrow.dds', '[1,2]', '[0,40,57,2,56,6,7,8,14,13,15,28,31]', '[13]', 'Though the Rangers of Oriath wield mighty long bows, they occasionally meet enemies that are too tough for mere arrows alone. Facing such a threat, trained archers have developed mastery of the dreaded Explosive Arrow. When the missile strikes, it bores deep into its target, releasing a volatile, deadly magical poison.__BREAK__ __BREAK__ This poison quickly boils the blood surrounding the embedded arrowhead, and within a few moments, a gout of fire erupts from the wound. This caustic spray will damage any adjacent foes. Some skilled marksmen have even developed the ability to fire multiple Explosive Arrows into the same point on a target''s body. Doing this not only extends the time before the blood detonation, but it massively increases the violence of the blast.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/explosive_arrow.jpg', 0, 'ExplosiveArrow', 0, 22, 1, '[4094,4257,4609,10895,18197]', '[24,436,70,217,18120]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35,4]', 0, 0, 1, NULL, ''),
(154, 'explosive_arrow', 'Explosive Arrow', 'Fires an arrow which will stick into an enemy or wall, and then explode, dealing area damage around it, either after a duration or when the maximum number of arrows stuck to that target is reached. If an enemy has multiple Explosive Arrows stuck in them, the first one to explode will consume the others, adding their damage to its explosion.', 70, 'Art/2DArt/SkillIcons/fusearrow.dds', '[1,2]', '[0,40,57,2,56,6,7,8,14,13,15,28,31]', '[13]', 'Though the Rangers of Oriath wield mighty long bows, they occasionally meet enemies that are too tough for mere arrows alone. Facing such a threat, trained archers have developed mastery of the dreaded Explosive Arrow. When the missile strikes, it bores deep into its target, releasing a volatile, deadly magical poison.__BREAK__ __BREAK__ This poison quickly boils the blood surrounding the embedded arrowhead, and within a few moments, a gout of fire erupts from the wound. This caustic spray will damage any adjacent foes. Some skilled marksmen have even developed the ability to fire multiple Explosive Arrows into the same point on a target''s body. Doing this not only extends the time before the blood detonation, but it massively increases the violence of the blast.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/explosive_arrow.jpg', 0, 'ExplosiveArrow', 0, 22, 1, '[4094,4257,4609,10895,18197]', '[24,436,70,217,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(155, 'explosive_arrow_alt_x', '[DNT] ExplosiveArrowAltX', 'Fires an arrow which will stick into an enemy or wall, and then explode, dealing area damage around it, either after a duration or when the maximum number of arrows stuck to that target is reached. If an enemy has multiple Explosive Arrows stuck in them, the first one to explode will consume the others, adding their damage to its explosion.', 70, 'Art/2DArt/SkillIcons/fusearrow.dds', '[1,2]', '[0,40,57,2,56,6,7,8,14,13,15,28,31]', '[13]', 'Though the Rangers of Oriath wield mighty long bows, they occasionally meet enemies that are too tough for mere arrows alone. Facing such a threat, trained archers have developed mastery of the dreaded Explosive Arrow. When the missile strikes, it bores deep into its target, releasing a volatile, deadly magical poison.__BREAK__ __BREAK__ This poison quickly boils the blood surrounding the embedded arrowhead, and within a few moments, a gout of fire erupts from the wound. This caustic spray will damage any adjacent foes. Some skilled marksmen have even developed the ability to fire multiple Explosive Arrows into the same point on a target''s body. Doing this not only extends the time before the blood detonation, but it massively increases the violence of the blast.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/explosive_arrow.jpg', 0, 'ExplosiveArrow', 0, 22, 1, '[4094,4257,4609,10895,18197]', '[24,436,70,217,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 154, ''),
