(167, 'temporal_chains', 'Temporal Chains', 'Curses all enemies in an area, lowering their action speed and making other effects on them expire more slowly.', 79, 'Art/2DArt/SkillIcons/temporalchains.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,84,85,96]', '[]', 'This useful curse warps a small area of space and actually causes time to pass slower within its confines. Any beings who pass through the affected zone will become snared in the warp, slowing their actions to a crawl.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/temporal_chains.jpg', 0, 'TemporalChains', 1, 22, 1, '[4368,4404,8760,15264]', '[1393,217,11722,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(168, 'elemental_weakness', 'Elemental Weakness', 'Curses all targets in an area, lowering their elemental resistances.', 80, 'Art/2DArt/SkillIcons/elementalweakness.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,84,85,96]', '[]', 'A favorite of Witches and other masters of magic, the Elemental Weakness curse strips away resistances to cold, fire and lightning. Once afflicted by the curse, an enemy will suffer grievous harm from any elemental attack, even if they have natural resistances.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/elemental_weakness.jpg', 0, 'ElementalWeakness', 1, 22, 1, '[4411,4371,15267]', '[217,1393,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(169, 'warlords_mark', 'Warlord''s Mark', 'Curses a single enemy, giving a chance to double the duration of stuns on them. Attacking the cursed enemy will leech life and mana, stunning them will grant rage, and killing it will grant an endurance charge. You can only have one Mark at a time.', 81, 'Art/2DArt/SkillIcons/WarLordsMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97]', '[]', 'A favored curse of the Oriathan Marauders during their reaving campaigns, Warlord''s Mark is known for swinging the tide of   battle. The curse afflicts all foes in the targeted area with a crippling malady, allowing the caster to drain their very   life essence with each successful attack. A foe slain while afflicted with Warlord''s Mark will return extra essence to the   player''s flasks and might even grant them an Endurance Charge.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/warlords_mark.jpg', 0, 'WarlordsMark', 1, 22, 1, '[4377,4405]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(170, 'warlords_mark_triggered', 'Warlord''s Mark', 'Curses a single enemy, giving a chance to double the duration of stuns on them. Attacking the cursed enemy will leech life and mana, stunning them will grant rage, and killing it will grant an endurance charge. You can only have one Mark at a time.', 81, 'Art/2DArt/SkillIcons/WarLordsMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97,89]', '[]', 'A favored curse of the Oriathan Marauders during their reaving campaigns, Warlord''s Mark is known for swinging the tide of   battle. The curse afflicts all foes in the targeted area with a crippling malady, allowing the caster to drain their very   life essence with each successful attack. A foe slain while afflicted with Warlord''s Mark will return extra essence to the   player''s flasks and might even grant them an Endurance Charge.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/warlords_mark.jpg', 0, 'WarlordsMark', 1, 22, 1, '[4377,4405]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(171, 'punishment_old', '', '', 82, 'Art/2DArt/SkillIcons/punishment.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,27,84,85,96]', '[]', 'A trick often employed by masters of minion control, the feared Punishment curse has brought down entire armies. The malady causes afflicted targets to suffer a substantial amount of the damage they deal from their own attacks, so the harder they hit, the faster they die. The secret is in making sure that incoming blows land on the dry bones and withered flesh of enemies rather than on the caster of the Curse.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/punishment.jpg', 0, 'Punishment', 1, 22, 1, '[4375,4407,15266]', '[1393,217,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(172, 'enfeeble', 'Enfeeble', 'Curses all targets in an area, reducing their accuracy and making them deal less damage.', 83, 'Art/2DArt/SkillIcons/enfeeble.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,84,85,96]', '[]', 'Not all curses are offensive. When the situation dictates it, a caster sometimes employs the Curse of Enfeeblement. This powerful spell saps the very strength from all targets in an area, draining them of vigor and causing their attacks to land with far less violence. Arena combatants have been driven nearly insane by this curse, with their weakened assaults unable to even pierce their enemy''s energy shield. Enfeeble definitely shines when employed against fellow players.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/enfeeble.jpg', 0, 'Enfeeble', 1, 22, 1, '[4372,4410,15265]', '[1393,217,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(173, 'assassins_mark', 'Assassin''s Mark', 'Curses a single enemy, making them more vulnerable to Critical Strikes. Killing the cursed enemy will grant life and mana, and a power charge. You can only have one Mark at a time.', 84, 'Art/2DArt/SkillIcons/AssassinsMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97]', '[]', 'Critical Weakness, while not terribly strong on its own, gets incredibly effective in the hands of the right player. A character heavily invested in increased Critical Chance will absolutely decimate their foes when they afflict them with this weakness. While it''s not the most direct of curses, Critical Weakness stands among the best when utilized correctly.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/critical_weakness.jpg', 0, 'AssassinsMark', 1, 22, 1, '[4369,4413]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(174, 'assassins_mark_triggered', 'Assassin''s Mark', 'Curses a single enemy, making them more vulnerable to Critical Strikes. Killing the cursed enemy will grant life and mana, and a power charge. You can only have one Mark at a time.', 84, 'Art/2DArt/SkillIcons/AssassinsMark.dds', '[1,2]', '[1,13,14,15,21,31,68,69,84,85,97,89]', '[]', 'Critical Weakness, while not terribly strong on its own, gets incredibly effective in the hands of the right player. A character heavily invested in increased Critical Chance will absolutely decimate their foes when they afflict them with this weakness. While it''s not the most direct of curses, Critical Weakness stands among the best when utilized correctly.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/critical_weakness.jpg', 0, 'AssassinsMark', 1, 22, 1, '[4369,4413]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(175, 'snipers_mark', 'Sniper''s Mark', 'Curses a single enemy, increasing the damage they take from projectiles, and making projectiles split when hitting them, to hit other targets around them. You can only have one Mark at a time.', 85, 'Art/2DArt/SkillIcons/projectileweakness.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97]', '[]', 'This wicked curse alters the very flesh of those afflicted, turning their armour and hide to mere paper. Any projectiles striking a cursed target have a high chance of piercing it, boring straight through to hit additional enemies standing behind. Foes under the Projectile Weakness curse will find themselves frustrated trying to reach the archer, since every volley has a good chance of causing a knockback. A Ranger trained in the curse of Projectile Weakness will be counted amongst the most feared combatants on the battlefield.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/projectile_weakness.jpg', 0, 'SnipersMark', 1, 22, 1, '[4367,4403]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(176, 'vulnerability', 'Vulnerability', 'Curse all targets in an area, causing them to take increased physical damage. Attacks against the cursed enemies have a chance to inflict bleeding.', 86, 'Art/2DArt/SkillIcons/vulnerability.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,27,84,85,96]', '[]', 'Though they generally feared sorcery, even the Marauders came to learn the value of the powerful Vulnerability Curse. Before charging into battle, a caster on the front lines would speak the curse, throwing it far and wide on their assembled enemies. The Marauders would come on with a roar, a tidal wave of rage and steel crashing against their foes. The Vulnerability curse could hardly be seen, but its effects were dire. Blows from the Marauders hit far harder, sundering helm and shield like tin. Those not killed immediately would be stunned inert, unable to defend themselves from the onslaught. Even masters of magic were vulnerable, for the curse corrupted the force of their protective shields.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/vulnerability.jpg', 0, 'Vulnerability', 1, 22, 1, '[4376,4406,7048,15259]', '[1393,217,11722,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(177, 'inca_minion_projectile', '', '', 87, '', '[1,2]', '[1,6,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(178, 'lightning_warp', 'Lightning Warp', 'Waits for a duration before teleporting to a targeted destination, with the duration based on the distance and your movement speed. When the teleport occurs, lightning damage is dealt to the area around both where the player was and where they teleported to. Casting again will queue up multiple teleportations to occur in sequence.', 88, 'Art/2DArt/SkillIcons/teleportball.dds', '[1,3,2,20]', '[1,6,7,8,13,14,15,31,33,30,71,78,21,69]', '[]', 'They had the Witch pinned up against the cliffs, soaking in the waterfall, yet the Bandit leader somehow sensed a trap. Wary, he muttered a command that only half his men move forward to finish things. Those appointed advanced slowly, blades drawn, cautious. They encircled the Witch for one brief moment, now only an arm''s length away. Then, in a flash of light, the frail woman vanished, and in her place crackled a ring of deadly lightning!__BREAK__ __BREAK__ The surrounding enemies fell as one, burning, twitching, thrashing in the freezing water. The remaining bandits paused for a second, scarcely believing their eyes, and then the Witch reappeared among them. With her arrival came another shocking blast, and the remaining bandits fell at her feet, scorched and dead. On Wraeclast, even teleportation is a weapon.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/blink_orb.jpg', 0, 'LightningWarp', 0, 22, 1, '[4285,4071,4303]', '[218,24,217]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(179, 'lightning_warp_alt_x', '[DNT] LightningWarpAltX', 'Waits for a duration before teleporting to a targeted destination, with the duration based on the distance and your movement speed. When the teleport occurs, lightning damage is dealt to the area around both where the player was and where they teleported to. Casting again will queue up multiple teleportations to occur in sequence.', 88, 'Art/2DArt/SkillIcons/teleportball.dds', '[1,3,2,20]', '[1,6,7,8,13,14,15,31,33,30,71,78,21,69]', '[]', 'They had the Witch pinned up against the cliffs, soaking in the waterfall, yet the Bandit leader somehow sensed a trap. Wary, he muttered a command that only half his men move forward to finish things. Those appointed advanced slowly, blades drawn, cautious. They encircled the Witch for one brief moment, now only an arm''s length away. Then, in a flash of light, the frail woman vanished, and in her place crackled a ring of deadly lightning!__BREAK__ __BREAK__ The surrounding enemies fell as one, burning, twitching, thrashing in the freezing water. The remaining bandits paused for a second, scarcely believing their eyes, and then the Witch reappeared among them. With her arrival came another shocking blast, and the remaining bandits fell at her feet, scorched and dead. On Wraeclast, even teleportation is a weapon.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/blink_orb.jpg', 0, 'LightningWarp', 0, 22, 1, '[4285,4071,4303]', '[218,24,217]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 178, ''),
(180, 'lightning_warp_alt_y', '[DNT] LightningWarpAltY', 'Waits for a duration before teleporting to a targeted destination, with the duration based on the distance and your movement speed. When the teleport occurs, lightning damage is dealt to the area around both where the player was and where they teleported to. Casting again will queue up multiple teleportations to occur in sequence.', 88, 'Art/2DArt/SkillIcons/teleportball.dds', '[1,3,2,20]', '[1,6,7,8,13,14,15,31,33,30,71,78,21,69]', '[]', 'They had the Witch pinned up against the cliffs, soaking in the waterfall, yet the Bandit leader somehow sensed a trap. Wary, he muttered a command that only half his men move forward to finish things. Those appointed advanced slowly, blades drawn, cautious. They encircled the Witch for one brief moment, now only an arm''s length away. Then, in a flash of light, the frail woman vanished, and in her place crackled a ring of deadly lightning!__BREAK__ __BREAK__ The surrounding enemies fell as one, burning, twitching, thrashing in the freezing water. The remaining bandits paused for a second, scarcely believing their eyes, and then the Witch reappeared among them. With her arrival came another shocking blast, and the remaining bandits fell at her feet, scorched and dead. On Wraeclast, even teleportation is a weapon.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/blink_orb.jpg', 0, 'LightningWarp', 0, 22, 1, '[4285,4071,4303]', '[218,24,217]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 178, ''),
(181, 'vaal_lightning_warp', 'Vaal Lightning Warp', 'Casts a delayed teleport for nearby enemies to a target destination. When the teleport occurs, lightning damage is dealt to the enemies both before and after they teleport.', 89, 'Art/2DArt/SkillIcons/teleportball.dds', '[1]', '[1,6,7,8,13,14,15,37,30,71]', '[]', '', '', 1, '', 0, 22, 1, '[4285,4071,4303]', '[218,24,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(182, 'gladiator_boss_vaal_lightning_warp', 'Vaal Lightning Warp', 'Casts a delayed teleport for nearby enemies to a target destination. When the teleport occurs, lightning damage is dealt to the enemies both before and after they teleport.', 89, 'Art/2DArt/SkillIcons/teleportball.dds', '[3]', '[1,6,7,8,13,14,15,37,30,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(183, 'summon_skeletons', 'Summon Skeletons', 'Summon Skeleton Warrior minions at the targeted location. They use a melee attack and die after a duration. If made aggressive, Skeleton Warriors will also dash towards nearby enemies.', 90, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[1,22]', '[1,5,8,17,13,14,15,21,31,69,76,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/summon_skeletons.jpg', 0, 'SummonSkeletons', 0, 22, 1, '[1141,6413]', '[8952,6412]', '[0,19,20,23,56]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(184, 'summon_skeletons_alt_x', 'Summon Skeletons of Archers', 'Summon Skeleton Archer minions at the targeted location. They fire arrows and die after a duration.', 90, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[1,22]', '[1,5,8,17,13,14,15,21,31,69,76,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/summon_skeletons.jpg', 0, 'SummonSkeletons', 0, 22, 1, '[1141,6413]', '[8952,6412]', '[0,40,2,56]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, 183, ''),
(185, 'summon_skeletons_alt_y', 'Summon Skeletons of Mages', 'Summon Skeleton Mage minions of random elemental types at the targeted location. They cast projectile spells based on their element, and die after a duration.', 90, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[1,22]', '[1,5,8,17,13,14,15,21,31,69,76,89,101]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/summon_skeletons.jpg', 0, 'SummonSkeletons', 0, 22, 1, '[1141,6413]', '[8952,6412]', '[6,1,2,56,101,28,29,30]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, 183, ''),
(186, 'vaal_summon_skeletons', 'Vaal Summon Skeletons', 'Summons an army of skeletal soldiers, archers and mages, led by a powerful general.', 91, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[1,22]', '[1,5,8,17,13,14,15,37,76,21]', '[]', '', '', 1, '', 0, 22, 1, '[1141]', '[8952]', '[0,19,20,2,40,56,23,1,7,54]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(187, 'summon_skeletons_on_self', '', '.', 90, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[10]', '[1,5,8,17,13,14,15,21,31,76]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/summon_skeletons.jpg', 1, 'SummonSkeletons', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(188, 'vaal_summon_skeletons_on_self', '', '', 91, 'Art/2DArt/SkillIcons/iconraiseskeleton.dds', '[10]', '[1,5,8,17,13,14,15,37,76]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[0,19,20,2,40,23,1,7]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(189, 'heavy_strike', 'Heavy Strike', 'Attacks enemies with a forceful blow. Requires a Mace, Sceptre, Axe, Sword or Staff.', 92, 'Art/2DArt/SkillIcons/heavystrike.dds', '[1,2]', '[0,20,23,19]', '[11,12,32,14,15,16,17,9,10,57]', 'When facing the hungry throngs on Wraeclast, offense truly is the best form of defence. Skilled melee combatants have mastered the technique of the Heavy Strike, a devastating blow they unleash with an Axe, Mace or any two-handed weapon. Heavy Strike lands with terrifying force, knocking foes back and often stunning them, if not killing them outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/heavy_strike.jpg', 0, 'HeavyStrike', 0, 22, 1, '[4272,4052,3492,18096]', '[70,24,5925,18095]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(190, 'heavy_strike_alt_x', '[DNT] Heavy Strike of Clobbering', '[DNT] Attacks enemies with both weapons at once, attempting to stun them. Requires dual wielding Maces, Sceptres, Axes, or Swords', 92, 'Art/2DArt/SkillIcons/heavystrike.dds', '[1,2]', '[0,20,23,19,3]', '[11,12,32,9,10]', 'When facing the hungry throngs on Wraeclast, offense truly is the best form of defence. Skilled melee combatants have mastered the technique of the Heavy Strike, a devastating blow they unleash with an Axe, Mace or any two-handed weapon. Heavy Strike lands with terrifying force, knocking foes back and often stunning them, if not killing them outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/heavy_strike.jpg', 0, 'HeavyStrike', 0, 22, 1, '[4272,4052,3492,18096]', '[70,24,5925,18095]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 189, ''),
(191, 'heavy_strike_alt_y', 'Heavy Strike of Trarthus', 'Attacks enemies with a forceful blow. Requires a Staff.', 92, 'Art/2DArt/SkillIcons/heavystrike.dds', '[1,2]', '[0,20,23,19]', '[14,57]', 'When facing the hungry throngs on Wraeclast, offense truly is the best form of defence. Skilled melee combatants have mastered the technique of the Heavy Strike, a devastating blow they unleash with an Axe, Mace or any two-handed weapon. Heavy Strike lands with terrifying force, knocking foes back and often stunning them, if not killing them outright.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/heavy_strike.jpg', 0, 'HeavyStrike', 0, 22, 1, '[4272,4052,3492,18096]', '[70,24,5925,18095]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 189, ''),
(192, 'vaal_heavy_strike', 'Vaal Heavy Strike', 'Attacks enemies with a forceful blow, sending them flying backwards. Requires a Mace, Sceptre, Axe, Sword or Two-Handed Weapon.', 93, 'Art/2DArt/SkillIcons/heavystrike.dds', '[1,2]', '[0,20,19,37,121]', '[11,12,32,14,15,16,17,9,10,57]', '', '', 1, '', 0, 22, 1, '[4272,4052,3492,18096]', '[70,24,5925,18095]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(193, 'dominating_blow', 'Dominating Blow', 'Attacks enemies with a melee strike, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the enemy''s corpse will be consumed and a Sentinel of Dominance with the same rarity, prefix and suffix modifiers will be summoned for a longer secondary duration.', 94, 'Art/2DArt/SkillIcons/conversionstrike.dds', '[1,2]', '[0,5,8,17,20,23,19,76,128]', '[9,10,15,11,16,12,32,17,14,7,6,36,57,56]', 'In their campaign to become the dominant order on Oriath, the Templars often faced impossible odds. This led them to master the technique known as the Dominating Blow.__BREAK__ __BREAK__ Dominating Blow does nothing exceptional when it strikes, little more than some damage. However, it also binds the soul of the victim to the will of the caster for a short duration. If the target dies with its soul bound, it will immediately reanimate, ready to fight alongside its new master for a time. With Dominating Blow on their side, warriors of The Order were able to overcome incredibly lopsided numbers in battle, often turning half of an army against itself.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/conversion_strike.jpg', 0, 'DominatingBlow', 0, 22, 1, '[4296,8221,8222,4558,18235]', '[8952,21298,21299,13546,12160]', '[0,19,20,23,7]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(194, 'dominating_blow_alt_x', 'Dominating Blow of Inspiring', 'Attacks enemies with a melee strike, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the enemy''s corpse will be consumed and a Sentinel of Dominance with the same rarity, prefix and suffix modifiers will be summoned for a longer secondary duration.', 94, 'Art/2DArt/SkillIcons/conversionstrike.dds', '[1,2]', '[0,5,8,17,20,23,19,76,128]', '[9,10,15,11,16,12,32,17,14,7,6,36,57,56]', 'In their campaign to become the dominant order on Oriath, the Templars often faced impossible odds. This led them to master the technique known as the Dominating Blow.__BREAK__ __BREAK__ Dominating Blow does nothing exceptional when it strikes, little more than some damage. However, it also binds the soul of the victim to the will of the caster for a short duration. If the target dies with its soul bound, it will immediately reanimate, ready to fight alongside its new master for a time. With Dominating Blow on their side, warriors of The Order were able to overcome incredibly lopsided numbers in battle, often turning half of an army against itself.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/conversion_strike.jpg', 0, 'DominatingBlow', 0, 22, 1, '[4296,8221,8222,4558,18235]', '[8952,21298,21299,13546,12160]', '[0,19,20,23,7]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 193, ''),
(195, 'dominating_blow_alt_y', '[DNT] DominatingBlowAltY', 'Attacks enemies with a melee strike, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the enemy''s corpse will be consumed and a Sentinel of Dominance with the same rarity, prefix and suffix modifiers will be summoned for a longer secondary duration.', 94, 'Art/2DArt/SkillIcons/conversionstrike.dds', '[1,2]', '[0,5,8,17,20,23,19,76,128]', '[9,10,15,11,16,12,32,17,14,7,6,36,57,56]', 'In their campaign to become the dominant order on Oriath, the Templars often faced impossible odds. This led them to master the technique known as the Dominating Blow.__BREAK__ __BREAK__ Dominating Blow does nothing exceptional when it strikes, little more than some damage. However, it also binds the soul of the victim to the will of the caster for a short duration. If the target dies with its soul bound, it will immediately reanimate, ready to fight alongside its new master for a time. With Dominating Blow on their side, warriors of The Order were able to overcome incredibly lopsided numbers in battle, often turning half of an army against itself.', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/conversion_strike.jpg', 0, 'DominatingBlow', 0, 22, 1, '[4296,8221,8222,4558,18235]', '[8952,21298,21299,13546,12160]', '[0,19,20,23,7]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 193, ''),
(196, 'vaal_dominating_blow', 'Vaal Domination', 'This spell causes one of your existing Sentinels of Dominance to Ascend, becoming more powerful, gaining new attacks, and overriding its duration, while maintaining its monster modifiers and other bonuses, including from support gems. If you cannot have more Ascended Sentinels of Dominance, an existing one will be refreshed instead.', 95, 'Art/2DArt/SkillIcons/conversionstrike.dds', '[1,4]', '[1,5,8,37,128]', '[]', '', '', 1, '', 0, 22, 1, '[4296,8221,8222,4558,18235]', '[8952,21298,21299,13546,12160]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(197, 'alira_rain_of_arrows', '', '', 96, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,14,13,15,31]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 0, 'RainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(198, 'oak_rain_of_arrows', '', '', 97, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,14,13,15,31]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 0, 'RainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(199, 'rain_of_arrows_old', 'Rain of Arrows', 'Fires a large number of arrows into the air, to land at the target after a short delay.', 98, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,14,13,15,31,88]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 0, 'RainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, 1, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(200, 'vaal_rain_of_arrows_old', 'Vaal Rain of Arrows', 'Fires a large number of arrows into the air, to land at the target after a short delay. Enemies hit by the arrows are pinned in place, unable to move for a time.', 98, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,7,10,14,13,15,8,37,88]', '[13]', '', '', 1, '', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(201, 'rain_of_arrows', 'Rain of Arrows', 'Fires multiple arrows into the air, to land in sequence after a delay, starting at the targeted location and spreading outwards in all directions. Each arrow deals damage in an area around it. Half of the arrows will land directly on targets if there are targets in their range.', 99, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,61,14,13,15,31,88]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 1, 'ExpandingRainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(202, 'rain_of_arrows_alt_x', 'Rain of Arrows of Artillery', 'Fires multiple arrows into the air, to land in sequence after a delay, starting in front of you and proceeding in a line in the direction of the target. Each arrow deals damage in an area around it.', 99, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,61,14,13,15,31,88]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 1, 'ExpandingRainOfArrows', 0, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 201, ''),
(203, 'rain_of_arrows_alt_y', 'Rain of Arrows of Saturation', 'Fires multiple arrows into the air, to slowly land in sequence after a delay, starting at the targeted location and spreading outwards in all directions. Each arrow deals damage in an area around it. Half of the arrows will land directly on targets if there are targets in their range.', 99, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,61,14,13,15,31,88]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 1, 'ExpandingRainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 201, ''),
(204, 'rain_of_arrows_triggered', 'Rain of Arrows', 'Fires multiple arrows into the air, to land in sequence after a delay, starting at the targeted location and spreading outwards in all directions. Each arrow deals damage in an area around it. Half of the arrows will land directly on targets if there are targets in their range.', 99, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,57,7,10,61,14,13,15,31,88,36,49,89]', '[13]', 'Before they''re given their first Long Bow, aspiring archers on Oriath are taught the art of the Arrow Rain. When the student is ready to be tested, he is taken out to the marshes, and commanded to fire a salvo at a flock of geese. The aspirant must bring down at least a dozen birds with one barrage, or it''s back for another year of training and discipline. __BREAK__ __BREAK__ Naturally, the Rain of Arrows technique is often used to devastating effect on the field of battle. A skilled archer fires a single enchanted missile aloft, and when it descends, it multiplies to carpet an entire area in a lethal shower. Be wary if you ever behold an enemy archer pointing their bow skyward.', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/rain_of_arrows.jpg', 1, 'ExpandingRainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(205, 'vaal_rain_of_arrows', 'Vaal Rain of Arrows', 'Fires multiple arrows into the air, to land in multiple sequences after a delay, each starting at the targeted location and spreading outwards in all directions. Each arrow deals damage in an area around it. Half of the arrows will land directly on targets if there are targets in their range.', 99, 'Art/2DArt/SkillIcons/rainofarrows.dds', '[1,2]', '[0,40,7,10,61,14,13,15,37,88]', '[13]', '', '', 1, 'VaalExpandingRainOfArrows', 1, 22, 1, '[4274,4065,4247,8130,18545]', '[70,24,436,8131,6155]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(206, 'firestorm', 'Firestorm', 'Flaming bolts rain down over the targeted area. They explode when landing, dealing damage to nearby enemies.', 100, 'Art/2DArt/SkillIcons/FirestormV2.dds', '[1,2,22]', '[1,6,7,8,13,14,15,21,31,28,55,69,71]', '[]', 'Perhaps the most feared area effect skill in the Witch''s arsenal, the mighty Firestorm skill is legendary for its power and cruelty. The incantation tears a rift in the heavens that showers a wide swath of ground in a rain of searing flames. These bolts pound down without mercy, exploding violently to cause even more harm.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fire_storm.jpg', 0, 'Firestorm', 1, 22, 1, '[4299,4078]', '[217,24]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(207, 'firestorm_alt_x', 'Firestorm of Meteors', 'A large flaming bolt falls towards the targeted area. The bolt explodes when landing, dealing damage to nearby enemies.', 100, 'Art/2DArt/SkillIcons/FirestormV2.dds', '[1,2,22]', '[1,6,7,13,14,15,21,31,28,55,69,71]', '[]', 'Perhaps the most feared area effect skill in the Witch''s arsenal, the mighty Firestorm skill is legendary for its power and cruelty. The incantation tears a rift in the heavens that showers a wide swath of ground in a rain of searing flames. These bolts pound down without mercy, exploding violently to cause even more harm.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fire_storm.jpg', 0, 'Firestorm', 1, 22, 1, '[4299,4078]', '[217,24]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 206, ''),
(208, 'firestorm_alt_y', 'Firestorm of Pelting', 'Flaming bolts rain down over the targeted area. They explode when landing, dealing damage to nearby enemies.', 100, 'Art/2DArt/SkillIcons/FirestormV2.dds', '[1,2,22]', '[1,6,7,8,13,14,15,21,31,28,55,69,71]', '[]', 'Perhaps the most feared area effect skill in the Witch''s arsenal, the mighty Firestorm skill is legendary for its power and cruelty. The incantation tears a rift in the heavens that showers a wide swath of ground in a rain of searing flames. These bolts pound down without mercy, exploding violently to cause even more harm.', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/fire_storm.jpg', 0, 'Firestorm', 1, 22, 1, '[4299,4078]', '[217,24]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 206, ''),
(209, 'fire_storm_ignore_los', '', '', 100, '', '[1,2,8]', '[1,6,7,8,13,14,15,21,31,28,71]', '[]', '', '', 1, '', 1, 22, 1, '[4299,4078]', '[217,24]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(210, 'vaal_fire_storm', 'Vaal Firestorm', 'A fixed number of flaming bolts rain down in a spiral, culminating in the central one impacting the targeted location. They explode when landing, dealing damage to nearby enemies and leaving burning ground, which deals fire damage over time.', 100, 'Art/2DArt/SkillIcons/FirestormV2.dds', '[1,2,22]', '[1,6,13,14,15,7,8,28,71,37,21,34]', '[]', '', '', 1, '', 1, 22, 1, '[4299,4078]', '[217,24]', '[]', 1, 1, '[18328]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(211, 'icestorm', 'Icestorm', 'Icy bolts rain down over the targeted area. They explode when landing, dealing damage to nearby enemies and chilling them, as well as causing patches of chilled ground. Skill damage is based on Intelligence.', 100, 'Art/2DArt/BuffIcons/icestorm.dds', '[1,2,22]', '[1,6,7,8,13,14,15,21,31,29,55,67,69,71]', '[]', '', '', 1, 'IcestormUniqueStaff12', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 1, 0, 1, NULL, ''),
(212, 'lightning_strike', 'Lightning Strike', 'Infuses your melee weapon with electrical energies as you swing. In addition to converting some of your physical damage to lightning damage, the stored energy is released from the weapon as projectiles as you strike, flying out to hit farther-away enemies. The projectiles cannot miss if the melee attack hit a target.', 101, 'Art/2DArt/SkillIcons/lightningslash.dds', '[1,2]', '[0,40,2,20,23,19,30,81]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/lightning_strike.jpg', 0, 'LightningStrike', 0, 22, 1, '[4054,4313,6379,6380,18207,18210]', '[24,175,6374,6360,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,27,3,35,15,14,28,12,26,17,16,11,10,29,18,19,13]', 0, 0, 1, NULL, ''),
(213, 'lightning_strike_alt_x', 'Lightning Strike of Arcing', 'Infuses your melee weapon with electrical energies as you swing. In addition to converting some of your physical damage to lightning damage, the stored energy is released from the weapon as a projectile as you strike, flying out to hit farther-away enemies and chain between them. The projectile cannot miss if the melee attack hit a target.', 101, 'Art/2DArt/SkillIcons/lightningslash.dds', '[1,2]', '[0,40,2,20,23,19,30,81,18]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/lightning_strike.jpg', 0, 'LightningStrike', 0, 22, 1, '[4054,4313,6379,6380,18207,18210]', '[24,175,6374,6360,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,27,3,35,15,14,28,12,26,17,16,11,10,29,18,19,13]', 0, 0, 1, 212, ''),
(214, 'lightning_strike_alt_y', '[DNT] LightningStrikeAltY', 'Infuses your melee weapon with electrical energies as you swing. In addition to converting some of your physical damage to lightning damage, the stored energy is released from the weapon as projectiles as you strike, flying out to hit farther-away enemies. The projectiles cannot miss if the melee attack hit a target.', 101, 'Art/2DArt/SkillIcons/lightningslash.dds', '[1,2]', '[0,40,2,20,23,19,30,81]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/lightning_strike.jpg', 0, 'LightningStrike', 0, 22, 1, '[4054,4313,6379,6380,18207,18210]', '[24,175,6374,6360,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,27,3,35,15,14,28,12,26,17,16,11,10,29,18,19,13]', 0, 0, 1, 212, ''),
(215, 'vaal_lightning_strike', 'Vaal Lightning Strike', 'Infuses your melee weapon with electrical energies as you swing. In addition to converting some of your physical damage to lightning damage, the stored energy becomes an orb attached to the enemy you hit, or the ground if you don''t hit an enemy. The orb will periodically fire projectiles at other nearby enemies for a duration, which will also damage the enemy the orb is attached to.', 102, 'Art/2DArt/SkillIcons/lightningslash.dds', '[1,2]', '[0,20,19,8,37,30,2,40,81,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4054,4313,6379,6380,18207,18210]', '[24,175,6374,6360,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(216, 'vaal_lightning_strike_old', 'Vaal Lightning Strike', 'Infuses your melee weapon with electrical energies as you swing. In addition to converting some of your physical damage to lightning damage, the stored energy is forced into the enemy as you strike, electrically charging them for a duration, during which lightning will arc between them and other nearby enemies, dealing damage. This occurs even if the attack is dodged.', 103, 'Art/2DArt/SkillIcons/lightningslash.dds', '[1,2]', '[0,20,19,8,37,30,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4054,4313,6379,6380,18207,18210]', '[24,175,6374,6360,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(217, 'tempest_shield', 'Tempest Shield', 'Enchants your shield with the power of storms, which lashes out to deal arcing lightning damage to attackers when you block them.', 104, 'Art/2DArt/SkillIcons/lightningshield.dds', '[4]', '[1,6,9,22,30,18,4,11,89,14,63,84,85]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/tempest_shield.jpg', 0, 'TempestShield', 0, 22, 1, '[4121,4464,16116]', '[24,174,4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(218, 'molten_shell_monster', 'Molten Shell', 'Summons fiery elemental shields providing additional armour for a short duration. If cumulative physical damage prevented by your blocking or armour reaches a threshold, the shields explode outwards, dealing fire damage to surrounding enemies.', 105, 'Art/2DArt/SkillIcons/moltenshield.dds', '[4]', '[1,6,7,8,14,26,31,28,63,71,27,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/molten_shell.jpg', 0, 'MoltenShell', 0, 22, 1, '[4112,4575]', '[24,4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(219, 'molten_shell', 'Molten Shell', 'Applies a buff that adds to your armour, and can take some of the damage from hits for you before being depleted. When the buff expires or is depleted, the skill deals reflected damage to enemies around you based on the total damage that was taken from the buff. Shares a cooldown with other Guard skills.', 105, 'Art/2DArt/SkillIcons/moltenshield.dds', '[4]', '[1,7,8,14,26,28,63,71,27,31,77,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/molten_shell.jpg', 0, 'MoltenShell', 0, 22, 1, '[10014,4575,9667,22126]', '[217,4602,9521,9521]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/MoltenShellTotem.ais', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(220, 'vaal_molten_shell', 'Vaal Molten Shell', 'Applies a buff that raises your armour, and takes some of the damage from hits for you before being depleted. Each second, the skill deals reflected damage to surrounding enemies based on the damage taken by the buff in that second. When the buff is removed, the skill deals reflected damage to enemies around you based on the total damage that was taken by the buff. You cannot have the buff at the same time as any other Guard skill.', 105, 'Art/2DArt/SkillIcons/moltenshield.dds', '[4]', '[1,7,8,14,26,28,63,71,27,37,85,84,89,77]', '[]', '', '', 1, '', 0, 22, 1, '[10014,4575,22126]', '[217,4602,9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(221, 'monster_vaal_molten_shell', 'Vaal Molten Shell', '', 105, '', '[4]', '[1,6,7,8,14,26,37,28,31,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[4112,4575]', '[24,4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(222, 'power_siphon', 'Power Siphon', 'Fires your wand to fire a single projectile each at a number of nearby enemies, granting you a power charge if an enemy is killed by, or soon after, the hit.', 106, 'Art/2DArt/SkillIcons/soulsyphon.dds', '[1,2]', '[0,40,2,56,14,13,15,126]', '[8]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/power_shot.jpg', 0, 'PowerSiphon', 0, 22, 1, '[4280,4083,8098,18244,18245,4338]', '[70,24,175,108,3889,3922]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(223, 'power_siphon_alt_x', 'Power Siphon of the Archmage', 'Fires your wand to fire a single projectile each at a number of nearby enemies, granting you a power charge if an enemy is killed by, or soon after, the hit.', 106, 'Art/2DArt/SkillIcons/soulsyphon.dds', '[1,2]', '[0,40,2,56,14,13,15,30]', '[8]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/power_shot.jpg', 0, 'PowerSiphon', 0, 22, 1, '[4280,4083,8098,18244,18245,4338]', '[70,24,175,108,3889,3922]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 222, ''),
(224, 'power_siphon_alt_y', '[DNT] PowerSiphonAltY', 'Fires your wand to fire a single projectile each at a number of nearby enemies, granting you a power charge if an enemy is killed by, or soon after, the hit.', 106, 'Art/2DArt/SkillIcons/soulsyphon.dds', '[1,2]', '[0,40,2,56,14,13,15,126]', '[8]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/power_shot.jpg', 0, 'PowerSiphon', 0, 22, 1, '[4280,4083,8098,18244,18245,4338]', '[70,24,175,108,3889,3922]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 222, ''),
(225, 'vaal_power_siphon', 'Vaal Power Siphon', 'Fires your wand simultaneously at all nearby enemies, culling those close to death and granting you a power charge for each. Cannot be supported by Volley.', 106, 'Art/2DArt/SkillIcons/soulsyphon.dds', '[1,2]', '[0,40,2,14,13,15,37,81,126]', '[8]', '', '', 1, '', 0, 22, 1, '[4280,4083,8098,18244,18245,4338]', '[70,24,175,108,3889,3922]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
