(229, 'puncture', 'Puncture', 'Punctures enemies with your Bow, causing a bleeding debuff, which will be affected by modifiers to skill duration.', 110, 'Art/2DArt/SkillIcons/puncture.dds', '[1,2]', '[0,40,57,2,56,8,13,15,14,31,27]', '[13]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/puncture.jpg', 0, 'Puncture', 0, 22, 1, '[4072,4297,4332,18233]', '[24,217,5519,11127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(230, 'puncture_alt_x', 'Puncture of Shanking', 'Punctures enemies, causing a bleeding debuff, which will be affected by modifiers to skill duration. Puncture works with daggers, claws or swords.', 110, 'Art/2DArt/SkillIcons/puncture.dds', '[1,2]', '[0,20,23,19,8,27]', '[6,7,9,10,15,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/puncture.jpg', 0, 'Puncture', 0, 22, 1, '[4072,4297,4332,18233]', '[24,217,5519,11127]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 229, ''),
(231, 'puncture_alt_y', '[DNT] PunctureAltY', 'Punctures enemies with your Bow, causing a bleeding debuff, which will be affected by modifiers to skill duration.', 110, 'Art/2DArt/SkillIcons/puncture.dds', '[1,2]', '[0,40,57,2,56,8,13,15,14,31,27]', '[13]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/puncture.jpg', 0, 'Puncture', 0, 22, 1, '[4072,4297,4332,18233]', '[24,217,5519,11127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 229, ''),
(232, 'monster_puncture', 'Puncture', 'Punctures enemies, causing a bleeding debuff, which will be affected by modifiers to skill duration. Puncture works with bows, daggers, claws or swords.', 110, 'Art/2DArt/SkillIcons/puncture.dds', '[1,2]', '[0,40,57,2,56,8,13,15,14,20,23,19,31,27]', '[13,6,7,9,10,15,56]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/puncture.jpg', 0, 'Puncture', 0, 22, 1, '[4072,4297,4332,18233]', '[24,217,5519,11127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(233, 'lightning_arrow', 'Lightning Arrow', 'Fires a charged arrow which damages enemies by causing them to be struck by a bolt of lightning, which also damages a number of surrounding enemies.', 111, 'Art/2DArt/SkillIcons/lightningarrow.dds', '[1,2]', '[0,40,57,7,2,56,14,13,15,30,31]', '[13]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/lightning_arrow.jpg', 0, 'LightningArrow', 0, 22, 1, '[4070,4249,18206,18209]', '[24,436,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(234, 'lightning_arrow_alt_x', 'Lightning Arrow of Electrocution', 'Fires a charged arrow which damages enemies by causing them to be struck by a bolt of lightning. It sticks into the final target, causing them to be struck and damaged multiple times.', 111, 'Art/2DArt/SkillIcons/lightningarrow.dds', '[1,2]', '[0,40,57,2,56,14,13,15,30,31]', '[13]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/lightning_arrow.jpg', 0, 'LightningArrow', 0, 22, 1, '[4070,4249,18206,18209]', '[24,436,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 233, ''),
