(267, 'conversion_trap', 'Conversion Trap', 'Throws a trap that, when triggered by an enemy, converts that enemy to your side for a short duration. Does not affect unique monsters or players.', 137, 'Art/2DArt/SkillIcons/conversiontrap.dds', '[2]', '[1,8,15,32,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/trap_convert.jpg', 0, 'ConversionTrap', 0, 22, 1, '[4435]', '[3396]', '[]', 1, 1, '[]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(268, 'bear_trap', 'Bear Trap', 'Throws a trap that damages and immobilises a single enemy for a duration based on how much damage was dealt. After the immobilise expires, a debuff remains on the enemy for a duration, lowering their movement speed by an amount which lessens over time. The affected enemy will take increased damage from traps and mines until the debuff expires. Modifiers to spell damage do not affect this skill''s damage.', 138, 'Art/2DArt/SkillIcons/beartrap.dds', '[2]', '[1,8,15,32,6,27,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/trap_beartrap.jpg', 0, 'BearTrap', 0, 22, 1, '[4424,4110,7889]', '[3396,24,7888]', '[]', 1, 1, '[18318]', 8, 2, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(269, 'bear_trap_alt_x', 'Bear Trap of Skewers', 'Throws a trap that damages and impales a single enemy, and immobilises them for a duration based on how much damage was dealt. Modifiers to spell damage do not affect this skill''s damage.', 138, 'Art/2DArt/SkillIcons/beartrap.dds', '[2]', '[1,8,15,32,6,27,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/trap_beartrap.jpg', 0, 'BearTrap', 0, 22, 1, '[4424,4110,7889]', '[3396,24,7888]', '[]', 1, 1, '[18318]', 8, 2, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, 268, ''),
(270, 'bear_trap_alt_y', '[DNT] BearTrapAltY', 'Throws a trap that damages and immobilises a single enemy for a duration based on how much damage was dealt. After the immobilise expires, a debuff remains on the enemy for a duration, lowering their movement speed by an amount which lessens over time. The affected enemy will take increased damage from traps and mines until the debuff expires. Modifiers to spell damage do not affect this skill''s damage.', 138, 'Art/2DArt/SkillIcons/beartrap.dds', '[2]', '[1,8,15,32,6,27,89]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/trap_beartrap.jpg', 0, 'BearTrap', 0, 22, 1, '[4424,4110,7889]', '[3396,24,7888]', '[]', 1, 1, '[18318]', 8, 2, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, 268, ''),
