(547, 'blink_arrow', 'Blink Arrow', 'Fires an arrow at the target destination. When the arrow lands, you are teleported to it and a clone is summoned at your old location. The clone is a minion that uses your bow and quiver.', 321, 'Art/2DArt/SkillIcons/BlinkShot.dds', '[1,2,20,23]', '[10,0,5,40,17,8,14,13,15,33,31,76,78,89,88]', '[13]', '', '', 1, '', 0, 22, 1, '[7615,4429,4123,4455,18058]', '[3396,3396,13199,13544,18057]', '[0,2,40,56]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(548, 'blink_arrow_alt_x', 'Blink Arrow of Bombarding Clones', 'Fires an arrow at the target destination. When the arrow lands, you are teleported to it and a clone is summoned at your old location. The clone is a minion that uses your bow and quiver to fire arrows into the air to land around a target.', 321, 'Art/2DArt/SkillIcons/BlinkShot.dds', '[1,2,20,23]', '[10,0,5,40,17,8,14,13,15,33,31,76,78,89,88]', '[13]', '', '', 1, '', 0, 22, 1, '[7615,4429,4123,4455,18058]', '[3396,3396,13199,13544,18057]', '[0,40,88,7,10]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 547, ''),
(549, 'blink_arrow_alt_y', 'Blink Arrow of Prismatic Clones', 'Fires an arrow at the target destination. When the arrow lands, you are teleported to it and a clone is summoned at your old location. The clone is a minion that uses your bow and quiver to fire random elemental arrows which convert all physical damage to the chosen element and deal no damage of other damage types.', 321, 'Art/2DArt/SkillIcons/BlinkShot.dds', '[1,2,20,23]', '[10,0,5,40,17,8,14,13,15,33,31,76,78,89,88,101]', '[13]', '', '', 1, '', 0, 22, 1, '[7615,4429,4123,4455,18058]', '[3396,3396,13199,13544,18057]', '[0,2,40,56,28,29,30,101]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 547, ''),
