(564, 'static_strike_old', 'Static Strike', 'Strike your enemies with a melee weapon, building up static energy on you. This energy damages enemies around you when it expires, dealing damage that cannot be evaded or dodged. ', 330, 'Art/2DArt/SkillIcons/StaticStrikeSkillIcon.dds', '[1,2]', '[0,20,23,19,7,8,30]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4085,4300,4251]', '[24,217,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(565, 'static_strike', 'Static Strike', 'Attack with a melee weapon, gaining static energy for a duration if you hit an enemy. While you have static energy, you''ll frequently hit a number of nearby enemies with beams, dealing attack damage.', 331, 'Art/2DArt/SkillIcons/StaticStrikeSkillIcon.dds', '[1,2]', '[0,20,23,19,7,8,30,18]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4085,4300,4251,8232,18336,22423]', '[24,217,436,8231,18279,4605]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(566, 'static_strike_alt_x', 'Static Strike of Gathering Lightning', 'Attack with a melee weapon, gaining a Gathering Lightning buff for a duration if you hit an enemy. While you have Gathering Lightning, attacks with this skill will cause chaining beams of lightning, which chain additional times the more Gathering Lightning you have.', 331, 'Art/2DArt/SkillIcons/StaticStrikeSkillIcon.dds', '[1,2]', '[0,20,23,19,8,30,18,4]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4085,4300,4251,8232,18336,22423]', '[24,217,436,8231,18279,4605]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 565, ''),
