(577, 'summon_chaos_golem', 'Summon Chaos Golem', 'Summons a Chaos Golem that grants you damage over time and chaos resistance. The Chaos Golem can cast a damage over time Chaos aura and a cascade of Chaos spikes in addition to its melee attack.', 338, 'Art/2DArt/SkillIcons/ChaosElementalSummon.dds', '[1]', '[31,41,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,8,1,6,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
