(579, 'summon_chaos_golem_alt_y', 'Summon Chaos Golem of the Maelström', 'Summons a Chaos Golem. The Chaos Golem can cast a powerful damage over time Chaos aura that Withers enemies in addition to its melee attack.', 338, 'Art/2DArt/SkillIcons/ChaosElementalSummon.dds', '[1]', '[31,41,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,8,1,6,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 577, ''),
(580, 'summon_ice_golem', 'Summon Ice Golem', 'Summons an Ice Golem that grants you increased Critical Strike Chance and Accuracy. The Ice Golem can use an icy barrage spell and a chilling spinning attack in addition to its melee attack.', 339, 'Art/2DArt/SkillIcons/IceElementalSummon.dds', '[1]', '[31,29,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,2,56,1,6,33,23,67]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(581, 'summon_ice_golem_alt_x', 'Summon Ice Golem of Hordes', 'Summons an Ice Golem. The Ice Golem can use an icy barrage spell and a chilling spinning attack in addition to its melee attack.', 339, 'Art/2DArt/SkillIcons/IceElementalSummon.dds', '[1]', '[31,29,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,2,56,1,6,33,23,67]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 580, ''),
(582, 'summon_ice_golem_alt_y', 'Summon Ice Golem of Shattering', 'Summons an Ice Golem. The Ice Golem can use an icy barrage spell and a chilling spinning attack in addition to its melee attack. If reduced to low life it will trigger a spell that destroys itself to deal area damage and fire icy projectiles in a circle.', 339, 'Art/2DArt/SkillIcons/IceElementalSummon.dds', '[1]', '[31,29,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,2,56,1,6,33,23,67]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 580, ''),
(583, 'summon_flame_golem', 'Summon Flame Golem', 'Summons a Flame Golem that grants you increased Damage and Area of Effect. The Flame Golem can cast a fire spray, a wave of fire damage, and an explosive arcing projectile.', 340, 'Art/2DArt/SkillIcons/FireElementalSummon.dds', '[1]', '[31,28,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[6,7,2,56,1]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
