(591, 'ice_crash', 'Ice Crash', 'Slam the ground, damaging enemies in an area around the impact in three stages of increasing size. Enemies take slightly less damage on the second and third stage, and can only be hit by one stage. Works with Swords, Maces, Sceptres, Axes, Staves and Unarmed.', 344, 'Art/2DArt/SkillIcons/IceCrash.dds', '[1,2]', '[0,7,19,29,23,91,14]', '[9,10,11,12,32,14,15,16,17,36,57]', '', '', 1, '', 0, 22, 1, '[4097,4346,4262,18213]', '[24,450,436,18128]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(592, 'ice_crash_triggered', 'Ice Crash', 'Slam the ground, damaging enemies in an area around the impact in three stages of increasing size. Enemies take slightly less damage on the second and third stage, and can only be hit by one stage. Works with Swords, Maces, Sceptres, Axes, Staves and Unarmed.', 344, 'Art/2DArt/SkillIcons/IceCrash.dds', '[1,2]', '[0,7,19,29,23,91,14,31]', '[9,10,11,12,32,14,15,16,17,36,57]', '', '', 1, '', 0, 22, 1, '[4097,4346,4262,18213]', '[24,450,436,18128]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(593, 'ice_crash_alt_x', 'Ice Crash of Cadence', 'Slam the ground, damaging enemies in an area. Slams with main hand weapon deal more damage. Slams with off hand weapon have larger area of effect. Requires dual-wielding Swords, Maces, Sceptres, or Axes to use.', 344, 'Art/2DArt/SkillIcons/IceCrash.dds', '[1,2]', '[0,7,19,29,3,23,91,14]', '[9,10,11,12,32,14,15,16,17,36,57]', '', '', 1, '', 0, 22, 1, '[4097,4346,4262,18213]', '[24,450,436,18128]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 591, ''),
