(600, 'shock_nova', 'Shock Nova', 'Casts a ring of Lightning around you, followed by a larger Lightning nova. Each effect hits enemies caught in their area with Lightning Damage.', 350, 'Art/2DArt/SkillIcons/ShockNova.dds', '[4]', '[1,6,7,13,14,15,21,31,30,69,71,83]', '[]', '', '', 1, 'NewShockNova', 0, 22, 1, '[4099,4267,18208,18211]', '[24,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/ShockNovaTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(601, 'shock_nova_alt_x', 'Shock Nova of Procession', 'Casts a ring of Lightning around you, followed by a larger Lightning nova. Each effect hits enemies caught in their area with Lightning Damage. This then repeats, with each repeat offset from the previous in the direction you target.', 350, 'Art/2DArt/SkillIcons/ShockNova.dds', '[1,2]', '[1,6,7,13,14,15,21,31,30,69,71,83]', '[]', '', '', 1, 'NewShockNova', 0, 22, 1, '[4099,4267,18208,18211]', '[24,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/ShockNovaTotemAlt.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 600, ''),
