(603, 'flame_dash', 'Flame Dash', 'Teleport to a location, damaging enemies and leaving a trail of burning ground. Shares a cooldown with other Blink skills.', 351, 'Art/2DArt/SkillIcons/FlameDash.dds', '[2,1,20,23]', '[1,33,6,34,8,14,31,28,13,15,78,79,89]', '[]', '', '', 1, 'FlameDash', 0, 22, 1, '[4427,4116]', '[3396,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(604, 'flame_dash_alt_x', 'Flame Dash of Incinerating', 'Teleport to a location, damaging enemies and leaving an intense trail of burning ground. Shares a cooldown with other Blink skills.', 351, 'Art/2DArt/SkillIcons/FlameDash.dds', '[2,1,20,23]', '[1,33,6,34,8,14,31,28,13,15,78,79,89]', '[]', '', '', 1, 'FlameDash', 0, 22, 1, '[4427,4116]', '[3396,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 603, ''),
(605, 'flame_dash_alt_y', 'Flame Dash of Return', 'Teleport to a location, damaging enemies and leaving a trail of burning ground, then repeat the teleport in the other direction. Cannot be triggered, or used by a totem, trap or mine. Cannot be supported by Unleash.', 351, 'Art/2DArt/SkillIcons/FlameDash.dds', '[2,1,20,23]', '[1,33,6,34,8,28,21]', '[]', '', '', 1, 'FlameDash', 0, 22, 1, '[4427,4116]', '[3396,24]', '[]', 1, 1, '[]', 8, 0, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 603, ''),
