(642, 'punishment', 'Punishment', 'Curses all targets in an area, causing them to be debilitated when they hit enemies and increasing damage they take while on low life.', 378, 'Art/2DArt/SkillIcons/punishment.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,84,85,96]', '[]', '', '', 1, 'NewPunishment', 1, 22, 1, '[4375,4407,15266]', '[1393,217,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(643, 'arctic_armour', 'Arctic Armour', 'Conjures an icy barrier that chills enemies when they hit you. You drop chilled ground while moving, and take less Fire and Physical damage while stationary.', 379, 'Art/2DArt/SkillIcons/Iceshield.dds', '[4]', '[1,4,14,8,11,22,29,16,63,66,67,71,84,85,89]', '[]', '', '', 1, 'NewArcticArmour', 0, 22, 1, '[4380,4457,15201,15231,15257]', '[14196,4602,14925,15106,14217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(644, 'vaal_arctic_armour', 'Vaal Arctic Armour', 'Immediately encases you in ice, protecting you for a duration or until you take damage from a number of hits, and also grants a buff once the cast time has finished. You cannot move or perform non-instant actions while in the ice. When the ice breaks, the buff is also removed.', 380, 'Art/2DArt/SkillIcons/Iceshield.dds', '[4]', '[1,4,8,29,37]', '[]', '', '', 1, 'VaalArcticArmour', 0, 22, 1, '[4457]', '[4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
