(648, 'wild_strike', 'Wild Strike', 'Your melee weapon strikes enemies, converting physical damage to a random element. Then, depending on the element chosen, it releases a fiery explosion, an arcing bolt of lightning, or an icy wave. It will avoid choosing the same element twice in a row.', 383, 'Art/2DArt/SkillIcons/ElementalStrike.dds', '[1,2]', '[0,20,23,19,30,29,28,2,7,18,40,81,101]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4101,4360,4260,18212]', '[24,10687,436,18127]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(649, 'wild_strike_alt_x', 'Wild Strike of Extremes', 'Your melee weapon strikes enemies, converting physical damage to a random element. Then, depending on the element chosen, it releases a fiery explosion, an arcing bolt of lightning, or an icy wave. It will avoid choosing the same element twice in a row.', 383, 'Art/2DArt/SkillIcons/ElementalStrike.dds', '[1,2]', '[0,20,23,19,30,29,28,2,7,18,40,81,101]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4101,4360,4260,18212]', '[24,10687,436,18127]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 648, ''),
