(652, 'ice_trap', 'Ice Trap', 'Throws a trap that creates a series of icy runic explosions when triggered, dealing cold damage to all enemies caught in the blasts.', 385, 'Art/2DArt/SkillIcons/IceTrapRune.dds', '[1,2,20]', '[1,6,15,7,32,29,71]', '[]', '', '', 1, 'IceTrap', 1, 22, 1, '[4436,4447,4135,7979,18216,18217,18218]', '[3396,436,24,596,18131,16750,3886]', '[]', 1, 1, '[]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
