(672, 'phase_run', 'Phase Run', 'Gain a buff that makes you faster, harder to detect, and grants Phasing, letting you pass through enemies. Performing any skill replaces this buff with one that boosts melee physical damage of skills you use yourself (it will not apply to your melee skills used by totems). Consumes Frenzy Charges to increase duration.', 402, 'Art/2DArt/SkillIcons/iconphaserun.dds', '[4]', '[1,4,8,31,33,63,27,78,89]', '[]', '', '', 1, '', 0, 22, 1, '[4569]', '[217]', '[]', 1, 1, '[]', 8, 0, 0, '', '[]', 0, 0, 1, NULL, ''),
