(674, 'blast_rain', 'Blast Rain', 'Fires arrows up in the air, to rain down in an area. Each arrow deals area damage around where it lands, and they will all overlap on the targeted location.', 404, 'Art/2DArt/SkillIcons/BlastRain.dds', '[1,2,20]', '[0,40,28,57,7,10,61,14,13,15,31,88]', '[13]', '', '', 1, '', 1, 22, 1, '[4130,4442,4563,11091,18203,18205]', '[24,436,176,11090,6120,18122]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(675, 'blast_rain_alt_x', 'Blast Rain of Trarthus', 'Fires a single arrow up in the air, to rain down at a targeted location. The arrow deals area damage around where it lands, as well as releasing a wave of fire which will apply a burning debuff to enemies. The impact of the arrow will also inflict this debuff.', 404, 'Art/2DArt/SkillIcons/BlastRain.dds', '[1,2,20]', '[0,40,28,57,7,10,61,14,13,15,31,88,34,24,8]', '[13]', '', '', 1, '', 0, 22, 1, '[4130,4442,4563,11091,18203,18205]', '[24,436,176,11090,6120,18122]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 674, ''),
