(678, 'galvanic_arrow', 'Galvanic Arrow', 'Fire a trio of electrical arrows that quickly dissipate, vanishing shortly after being loosed. The arrows are fired with such force that they create a burst of lightning, damaging enemies in a cone in front of you.', 405, 'Art/2DArt/SkillIcons/ShrapnelShot.dds', '[1,2]', '[0,2,56,7,14,13,15,30,40,57,31]', '[13]', '', '', 1, '', 0, 22, 1, '[4129,4461,4441,10832,5527,18229]', '[24,451,436,177,621,18141]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(679, 'galvanic_arrow_alt_x', 'Galvanic Arrow of Energy', 'Create a burst of lightning from your Bow, firing no arrows but damaging enemies in a cone in front of you.', 405, 'Art/2DArt/SkillIcons/ShrapnelShot.dds', '[1,2]', '[0,7,14,13,15,30,40,57,31]', '[13]', '', '', 1, '', 0, 22, 1, '[4129,4461,4441,10832,5527,18229]', '[24,451,436,177,621,18141]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 678, ''),
(680, 'galvanic_arrow_alt_y', 'Galvanic Arrow of Surging', 'Fire a trio of electrical arrows that quickly dissipate, vanishing shortly after being loosed. If the arrows'' flight is stopped by colliding with a target, they create a burst of lightning, damaging enemies in a cone behind the target', 405, 'Art/2DArt/SkillIcons/ShrapnelShot.dds', '[1,2]', '[0,2,56,7,14,13,15,30,40,57,31]', '[13]', '', '', 1, '', 0, 22, 1, '[4129,4461,4441,10832,5527,18229]', '[24,451,436,177,621,18141]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 678, ''),
