(684, 'bladefall', 'Bladefall', 'Ethereal weapons rain from the sky, dealing damage to enemies in a sequence of volleys. Enemies can be hit multiple times where these overlap.', 409, 'Art/2DArt/SkillIcons/RainOfBlades.dds', '[1,2,22]', '[1,7,13,15,14,6,31,21,55,69,71,27,8]', '[]', '', '', 1, 'Bladefall', 0, 22, 1, '[4462,4134,4446]', '[556,24,436]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(685, 'bladefall_alt_x', 'Bladefall of Volleys', 'Ethereal weapons rain from the sky, dealing damage to enemies in a sequence of volleys, each wider and more damaging than the last. Enemies can be hit multiple times where these overlap.', 409, 'Art/2DArt/SkillIcons/RainOfBlades.dds', '[1,2,22]', '[1,7,13,15,14,6,31,21,55,69,71,27]', '[]', '', '', 1, 'Bladefall', 0, 22, 1, '[4462,4134,4446]', '[556,24,436]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 684, ''),
(686, 'bladefall_alt_y', 'Bladefall of Impaling', 'Ethereal weapons rain from the sky, dealing damage to enemies in a sequence of volleys. Enemies can be hit multiple times where these overlap.', 409, 'Art/2DArt/SkillIcons/RainOfBlades.dds', '[1,2,22]', '[1,7,13,15,14,6,31,21,55,69,71,27]', '[]', '', '', 1, 'Bladefall', 0, 22, 1, '[4462,4134,4446]', '[556,24,436]', '[]', 1, 1, '[18328]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 684, ''),
(687, 'bladefall_alt_z', 'Bladefall of Trarthus', 'Once activated, continuously spends mana to cause volleys of ethereal weapons rain from the sky around you, dealing damage to enemies they impact. Each Blade will target a separate enemy in the volley area if possible. Each enemy can only be hit once by each volley, even if multiple blades land near them. This skill cannot be triggered or used by Totems, Traps, or Mines.', 1285, 'Art/2DArt/SkillIcons/RainOfBlades.dds', '[4]', '[1,7,6,27,89,85,84,63,103,8]', '[]', '', '', 1, 'Bladefall', 0, 22, 1, '[4462,4134,4446]', '[556,24,436]', '[]', 1, 1, '[18328]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 684, ''),
(688, 'labyrinth_boss_rain_of_blades', 'Rain Of Blades', '', 409, 'Art/2DArt/SkillIcons/RainOfBlades.dds', '[16]', '[1,7,13,15,14,6,31,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(689, 'blade_vortex_old', 'Blade Vortex', 'An ethereal blade spins around you for a duration, repeatedly damaging enemies that it passes through.', 410, 'Art/2DArt/SkillIcons/SpinningEtherealBlades.dds', '[4]', '[1,6,7,8,14,21,31,22,69,71,27]', '[]', '', '', 1, 'BladeVortex', 0, 22, 1, '[4133,4419,4445,18538,18539]', '[24,217,436,13173,14166]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(690, 'vaal_blade_vortex', 'Vaal Blade Vortex', 'Creates an independently-moving vortex of ethereal blades which lasts for a duration. The vortex moves toward nearby enemies, repeatedly damaging enemies that it passes through.', 411, 'Art/2DArt/SkillIcons/SpinningEtherealBlades.dds', '[1,2]', '[1,6,7,8,14,22,37,71,27,21]', '[]', '', '', 1, 'VaalBladeVortex', 0, 22, 1, '[4133,4419,4445,8087,18538,18539]', '[24,217,436,8088,13173,14166]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(691, 'frost_bomb', 'Frost Bomb', 'Creates a crystal that pulses with cold for a duration. Each pulse applies a debuff to nearby enemies for a secondary duration which reduces life regeneration rate, and also inflicts Cold Exposure. When the crystal''s duration ends, it explodes, dealing heavy cold damage to enemies around it.', 412, 'Art/2DArt/SkillIcons/FrostBomb.dds', '[1,20,22]', '[1,7,8,29,6,21,14,13,15,31,55,71,89,99]', '[]', '', '', 1, 'FrostBomb', 1, 22, 1, '[4434,4138,4449,8100]', '[3396,24,436,170]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(692, 'frost_bomb_alt_x', 'Frost Bomb of Instability', 'Creates a crystal which lasts for a duration. When the crystal''s duration ends, it explodes, dealing cold damage to enemies around it.', 412, 'Art/2DArt/SkillIcons/FrostBomb.dds', '[1,20,22]', '[1,7,8,29,6,21,14,13,15,31,55,71,69]', '[]', '', '', 1, 'FrostBomb', 1, 22, 1, '[4434,4138,4449,8100]', '[3396,24,436,170]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 691, ''),
