(698, 'manifest_dancing_dervishes', 'Manifest Dancing Dervishes', 'Manifests two Dancing Dervishes to fight by your side. While a Dancing Dervish is manifested, you have Onslaught and cannot use Weapons. Cannot be supported by supports that would create other minions.', 414, 'Art/2DArt/BuffIcons/RhysSword.dds', '[4]', '[1,5,17,31,49,60,76,89,36]', '[]', '', '', 1, 'UniqueAnimateWeapon', 0, 22, 0, '[]', '[]', '[0,19,7,33]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(699, 'orb_of_storms', 'Orb of Storms', 'Creates a stationary electrical orb that strikes enemies in its area of effect with beams of lightning that can then split to hit more enemies. Modifiers to cast speed will increase how frequently it does this. Casting this skill again will replace the previous orb.', 415, 'Art/2DArt/SkillIcons/StormCloud.dds', '[1]', '[1,6,30,7,18,31,13,15,14,71,89,99,21]', '[]', '', '', 1, 'OrbOfStorms', 0, 22, 1, '[4139,4463,4450,8080]', '[24,556,436,218]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(700, 'orb_of_storms_alt_x', 'Orb of Storms of Squalls', 'Creates an electrical orb that will strike enemies in its area of effect with beams of lightning when placed, as well as when you use a lightning skill while within its area. These beams of lightning can then split to hit more enemies. When striking enemies, this orb will teleport to a random enemy struck. Casting this skill again will replace the previous orb.', 415, 'Art/2DArt/SkillIcons/StormCloud.dds', '[1]', '[1,6,30,7,18,31,13,15,14,71,89,99,21]', '[]', '', '', 1, 'OrbOfStorms', 0, 22, 1, '[4139,4463,4450,8080]', '[24,556,436,218]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 699, ''),
