(734, 'earthquake', 'Earthquake', 'Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a duration. Cracks created before the first one has erupted will not generate their own aftershocks. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 427, 'Art/2DArt/SkillIcons/QuakeSlam.dds', '[1,2]', '[0,7,19,23,8,91,31,14]', '[11,12,32,14,16,17,36,57]', '', '', 1, 'Earthquake', 0, 22, 1, '[4136,4420,4448,12402,18198]', '[24,217,436,12401,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(735, 'earthquake_alt_x', 'Earthquake of Amplification', 'Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a duration. Cracks created before the first one has erupted will not generate their own aftershocks. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 427, 'Art/2DArt/SkillIcons/QuakeSlam.dds', '[1,2]', '[0,7,19,23,8,91,31,14]', '[11,12,32,14,16,17,36,57]', '', '', 1, 'Earthquake', 0, 22, 1, '[4136,4420,4448,12402,18198]', '[24,217,436,12401,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 734, ''),
(736, 'earthquake_alt_y', '[DNT] EarthquakeAltY', 'Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a duration. Cracks created before the first one has erupted will not generate their own aftershocks. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 427, 'Art/2DArt/SkillIcons/QuakeSlam.dds', '[1,2]', '[0,7,19,23,8,91,31,14]', '[11,12,32,14,16,17,36,57]', '', '', 1, 'Earthquake', 0, 22, 1, '[4136,4420,4448,12402,18198]', '[24,217,436,12401,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 734, ''),
