(741, 'contagion', 'Contagion', 'Unleashes a vile contagion on enemies, dealing chaos damage over time. If an enemy dies while affected by Contagion, the debuff spreads to other enemies.', 431, 'Art/2DArt/SkillIcons/Contagion.dds', '[1,2,22]', '[1,7,8,13,14,34,41,21,31,15,48,55,69,71]', '[]', '', '', 1, 'Contagion', 1, 22, 1, '[4132,4416,4443]', '[24,217,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(742, 'contagion_alt_x', 'Contagion of Subsiding', 'Unleashes a vile contagion on enemies, dealing chaos damage over time. If an enemy dies while affected by Contagion, the debuff spreads to other enemies, but each time it spreads, it only deals three quarters as much damage as before.', 431, 'Art/2DArt/SkillIcons/Contagion.dds', '[1,2,22]', '[1,7,8,13,14,34,41,21,31,15,48,55,69,71]', '[]', '', '', 1, 'Contagion', 1, 22, 1, '[4132,4416,4443]', '[24,217,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 741, ''),
(743, 'contagion_alt_y', 'Contagion of Transference', 'Unleashes a vile contagion on enemies, dealing chaos damage over time. If an enemy is hit while affected by Contagion, the debuff spreads to other enemies.', 431, 'Art/2DArt/SkillIcons/Contagion.dds', '[1,2,22]', '[1,7,8,13,14,34,41,21,31,15,48,55,69,71]', '[]', '', '', 1, 'Contagion', 1, 22, 1, '[4132,4416,4443]', '[24,217,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 741, ''),
(744, 'wither_old', 'Wither', 'Casts a debilitating effect on enemies in an area, Hindering their movement and applying a stacking Withered debuff that increases the Chaos Damage they take. This effect can stack up to 15 times.', 432, 'Art/2DArt/SkillIcons/Wither.dds', '[1,2]', '[1,7,8,14,41,71]', '[]', '', '', 1, 'Wither', 0, 22, 1, '[4418,4444]', '[217,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(745, 'wither', 'Wither', 'Casts a debilitating debuff on enemies in an area, hindering their movement and also inflicts the Withered debuff, which increases the Chaos Damage they take and can stack up to 15 times.', 433, 'Art/2DArt/SkillIcons/Wither.dds', '[1,18,17]', '[1,7,8,14,41,47,71]', '[]', '', '', 1, 'Wither', 0, 22, 1, '[4418,4444]', '[217,436]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/WitherTotem.ais', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(746, 'essence_drain', 'Essence Drain', 'Fires a projectile that applies a damage over time debuff when it hits. You are healed for a portion of the debuff damage. The debuff is spread by Contagion.', 434, 'Art/2DArt/SkillIcons/Siphon.dds', '[1,2]', '[1,2,56,8,14,21,34,41,6,31,69,7,71,13,15]', '[]', '', '', 1, 'EssenceDrain', 0, 22, 1, '[4131,4417,18541,18542]', '[24,217,177,175]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(747, 'essence_drain_alt_x', 'Essence Drain of Desperation', 'Fires a projectile that applies a damage over time debuff when it hits. You lose Life and Energy Shield equal to a portion of the debuff damage. The debuff is spread by Contagion.', 434, 'Art/2DArt/SkillIcons/Siphon.dds', '[1,2]', '[1,2,56,8,14,21,34,41,6,31,69,7,71,13,15]', '[]', '', '', 1, 'EssenceDrain', 0, 22, 1, '[4131,4417,18541,18542]', '[24,217,177,175]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 746, ''),
