(1095, 'charged_dash_old', 'Charged Dash', 'Channel to project a mirage forward in the direction you''re facing, based on your movement speed. Release to teleport to the mirage dealing area of effect damage multiple times along the way. Travelling further applies a bonus to the damage as well as dealing damage in larger areas. Faster attack speed and lower movement speed will both cause damage to be dealt more frequently along the path.', 705, 'Art/2DArt/SkillIcons/ChargedDash.dds', '[1]', '[33,7,6,47,0,19,30]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[6587,8084,18105,18106,18744]', '[24,8083,18107,18108,18745]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1096, 'charged_dash', 'Charged Dash', 'Channel to project an illusion which you steer. You gain stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path, based on your attack speed. Stop channelling to teleport to the illusion, dealing a final wave of damage. Requires a Melee Weapon.', 706, 'Art/2DArt/SkillIcons/ChargedDash.dds', '[1]', '[33,7,6,47,0,19,30]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[6587,8084,18105,18106,18744]', '[24,8083,18107,18108,18745]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1097, 'charged_dash_alt_x', 'Charged Dash of Projection', 'Channel to project an illusion which you steer. You gain stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path, based on your attack speed. Stop channelling to release the illusion, dealing a final wave of damage. Requires a Melee Weapon.', 706, 'Art/2DArt/SkillIcons/ChargedDash.dds', '[1]', '[7,6,47,0,19,30]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[6587,8084,18105,18106,18744]', '[24,8083,18107,18108,18745]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1096, ''),
(1098, 'charged_dash_alt_y', '[DNT] ChargedDashAltY', 'Channel to project an illusion which you steer. You gain stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path, based on your attack speed. Stop channelling to teleport to the illusion, dealing a final wave of damage. Requires a Melee Weapon.', 706, 'Art/2DArt/SkillIcons/ChargedDash.dds', '[1]', '[33,7,6,47,0,19,30]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[6587,8084,18105,18106,18744]', '[24,8083,18107,18108,18745]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1096, ''),
