(1140, 'summon_beastial_ursa', 'Summon Bestial Ursa', 'Summons a Bestial Ursa. In addition to its melee attack, the Bestial Ursa uses a powerful Ground Slam and Rallying Cry. Enemies will not engage this minion directly, and they are immune to damage.', 739, 'Art/2DArt/SkillIcons/SummonBeastUrsa.dds', '[1]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[0,19,20,6,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
