(1157, 'summon_harbinger_of_the_arcane', 'Summon Harbinger of the Arcane', 'Summons an immortal Harbinger minion. The minion will occasionally cast Arcane Surge on you, granting increased Cast Speed and Mana Regeneration.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1158, 'summon_harbinger_of_time', 'Summon Harbinger of Time', 'Summons an immortal Harbinger minion. The minion will occasionally create an aura on you that increases the Action Speed of you, and all allies and enemies near you.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1159, 'summon_harbinger_of_focus', 'Summon Harbinger of Focus', 'Summons an immortal Harbinger minion. While you are channelling, the minion will occasionally cast a buff on you that reduces the Damage you take, and makes you avoid all Stuns and Elemental Ailments.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1160, 'summon_harbinger_of_directons', 'Summon Harbinger of Directions', 'Summons an immortal Harbinger minion. The minion will cast a random buff on you that grants one or all of the following: 1 additional Projectile, +1 Chain, Pierce 1 additional Target, or Projectiles Fork.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1161, 'summon_harbinger_of_storms', 'Summon Harbinger of Storms', 'Summons an immortal Harbinger minion. The minion will occasionally apply a Chill or Shock to an enemy that chains to other nearby enemies.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[66]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1162, 'summon_harbinger_of_brutality', 'Summon Harbinger of Brutality', 'Summons an immortal Harbinger minion. When you are near a rare or unique enemy, the minion will occasionally grant you a buff giving significantly increased Damage, Attack Speed, and Movement Speed, and reducing the Damage you take.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1163, 'summon_harbinger_of_the_arcane_uber', 'Summon Greater Harbinger of the Arcane', 'Summons an immortal Harbinger minion. The minion has two buff spells it will cast on you: Arcane Surge, granting increased Cast Speed and Mana Regeneration, and a buff that grants Chance to Shock and Lightning Penetration.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1164, 'summon_harbinger_of_time_uber', 'Summon Greater Harbinger of Time', 'Summons an immortal Harbinger minion. The minion will occasionally create an aura on you that increases the Action Speed of you and all allies near you.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1165, 'summon_harbinger_of_focus_uber', 'Summon Greater Harbinger of Focus', 'Summons an immortal Harbinger minion. While you are channelling, the minion will occasionally cast a buff on you that reduces the Damage you take, makes you avoid all Stuns and Elemental Ailments, and prevents Curses affecting you.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1166, 'summon_harbinger_of_directons_uber', 'Summon Greater Harbinger of Directions', 'Summons an immortal Harbinger minion. The minion will cast a random buff on you that grants one or all of the following: Fire 2 additional Projectiles, Chain 2 additional times, Projectiles Pierce 2 additional targets, or Projectiles Fork then Fork an additional time.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1167, 'summon_harbinger_of_storms_uber', 'Summon Greater Harbinger of Storms', 'Summons an immortal Harbinger minion. The minion will occasionally apply a Chill or Shock with increased effect to an enemy that chains to other nearby enemies.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[66]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1168, 'summon_harbinger_of_brutality_uber', 'Summon Greater Harbinger of Brutality', 'Summons an immortal Harbinger minion. When you are near a rare or unique enemy, the minion will occasionally grant you a buff giving significantly increased Damage, Attack Speed, and Movement Speed, reducing the Damage you take, and causing Bleeding Enemies that you Kill to Explode, dealing 10% of their maximum Life as Physical Damage.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1169, 'summon_harbinger_of_the_arcane_ascendancy', 'Summon Visiting Harbinger of the Arcane', 'Summons an immortal Harbinger minion. The minion has two buff spells it will cast on you: Arcane Surge, granting increased Cast Speed and Mana Regeneration, and a buff that grants Chance to Shock and Lightning Penetration.', 755, 'Art/2DArt/SkillIcons/SummonHarbinger.dds', '[4,1,2]', '[31,15,5,17,116,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
