(1189, 'volatile_dead_alt_x', 'Volatile Dead of Confinement', 'Corpses near the targeted location explode, dealing damage in a small area and creating an orb which detonates after a duration, dealing spell damage in a larger area. The explosion of the corpse is not affected by modifiers to spell damage, and cannot be reflected.', 772, 'Art/2DArt/SkillIcons/Volitiledead.dds', '[6]', '[1,6,7,13,14,15,21,31,28,55,69,71,8]', '[]', '', '', 1, '', 0, 22, 1, '[7373,7377,18338]', '[24,218,18281]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/VolatileDeadTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1188, ''),
