(1201, 'cremation', 'Cremation', 'A targeted corpse explodes, dealing area damage and turning into a volcanic geyser, which will repeatedly unleash projectiles sequentially over the surrounding area for a duration. The explosion of the corpse is not affected by modifiers to spell damage, and cannot be reflected.', 782, 'Art/2DArt/SkillIcons/CorpseEruption.dds', '[6]', '[1,7,28,8,2,21,13,14,15,31,6,55,2,69,71,99]', '[]', '', '', 1, '', 0, 22, 1, '[7372,7376,18338]', '[24,218,18281]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/CremationTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(1202, 'cremation_alt_x', 'Cremation of Exhuming', 'A targeted corpse explodes, dealing area damage and turning into a volcanic geyser, which will repeatedly unleash projectiles sequentially over the surrounding area and detonate nearby corpses for a duration. Corpse explosions are not affected by modifiers to spell damage, and cannot be reflected.', 782, 'Art/2DArt/SkillIcons/CorpseEruption.dds', '[6]', '[1,7,28,8,2,21,13,14,15,31,6,55,2,69,71,99]', '[]', '', '', 1, '', 0, 22, 1, '[7372,7376,18338]', '[24,218,18281]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/CremationTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1201, ''),
