(1209, 'bodyswap', 'Bodyswap', 'Violently destroys your body and recreates it at the location of a targeted enemy or corpse, dealing spell damage in an area at both locations. If there is no specific target, it will prioritise corpses over enemies. If targeting a corpse, the corpse will also explode, dealing damage around it that is not affected by modifiers to spell damage, and cannot be reflected. This spell cannot be repeated.', 786, 'Art/2DArt/SkillIcons/CorpseWarp.dds', '[6,2]', '[33,1,6,7,14,15,13,31,28,71,78]', '[]', '', '', 1, '', 0, 22, 1, '[7374,7378]', '[24,218]', '[]', 1, 1, '[]', 8, 0, 0, 'Metadata/Monsters/Totems/BodyswapTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(1210, 'bodyswap_alt_x', 'Bodyswap of Sacrifice', 'Violently destroys your body and recreates it at the location of a targeted enemy or damageable minion, dealing spell damage in an area at both locations. If there is no specific target, it will prioritise minions over enemies. If targeting a minion, the minion will also be destroyed in an explosion which deals damage around it that is not affected by modifiers to spell damage, and cannot be reflected. This spell cannot be repeated.', 786, 'Art/2DArt/SkillIcons/CorpseWarp.dds', '[1,3,2]', '[33,1,6,7,14,15,13,31,28,71,78,5]', '[]', '', '', 1, '', 0, 22, 1, '[7374,7378]', '[24,218]', '[]', 1, 1, '[]', 8, 0, 0, 'Metadata/Monsters/Totems/BodyswapOfSacraficeTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1209, ''),
(1211, 'bodyswap_alt_y', '[DNT] CorpseWarpAltY', 'Violently destroys your body and recreates it at the location of a targeted enemy or corpse, dealing spell damage in an area at both locations. If there is no specific target, it will prioritise corpses over enemies. If targeting a corpse, the corpse will also explode, dealing damage around it that is not affected by modifiers to spell damage, and cannot be reflected. This spell cannot be repeated.', 786, 'Art/2DArt/SkillIcons/CorpseWarp.dds', '[6,2]', '[33,1,6,7,14,15,13,31,28,71,78]', '[]', '', '', 1, '', 0, 22, 1, '[7374,7378]', '[24,218]', '[]', 1, 1, '[]', 8, 0, 0, 'Metadata/Monsters/Totems/BodyswapTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1209, ''),
