(1221, 'aegis_fire', 'Fire Aegis', 'Calls forth a protective aegis which takes fire damage from hits for you until depleted. The aegis will be restored to its full value after a short delay if you stop taking fire damage from hits, or if depleted.', 795, 'Art/2DArt/BuffIcons/FireAegis.dds', '[4]', '[1,31,36,49,98]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1222, 'aegis_cold', 'Cold Aegis', 'Calls forth a protective aegis which takes cold damage from hits for you until depleted. The aegis will be restored to its full value after a short delay if you stop taking cold damage from hits, or if depleted.', 795, 'Art/2DArt/BuffIcons/ColdAegis.dds', '[4]', '[1,31,36,49,98]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1223, 'aegis_elemental', 'Elemental Aegis', 'Calls forth a protective aegis which takes elemental damage from hits for you until depleted. The aegis will be restored to its full value after a short delay if you stop taking elemental damage from hits, or if depleted.', 795, 'Art/2DArt/BuffIcons/Elemental.dds', '[4]', '[1,31,36,49,98]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1224, 'aegis_lightning', 'Lightning Aegis', 'Calls forth a protective aegis which takes lightning damage from hits for you until depleted. The aegis will be restored to its full value after a short delay if you stop taking lightning damage from hits, or if depleted.', 795, 'Art/2DArt/BuffIcons/LightningAegis.dds', '[4]', '[1,31,36,49,98]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
