(1227, 'vaal_impurity_of_fire', 'Vaal Impurity of Fire', 'Casts an aura that reduces fire damage taken and provides ignite immunity to you and nearby allies, and makes hits against nearby enemies ignore their fire resistance. ', 797, 'Art/2DArt/SkillIcons/Vaal Skill Icons/Vaalaurafireresist.dds', '[4]', '[1,4,7,14,22,8,37,38,71,28,63,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[11123]', '[1979]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1228, 'vaal_impurity_of_ice', 'Vaal Impurity of Ice', 'Casts an aura that reduces cold damage taken and provides freeze and chill immunity to you and nearby allies, and makes hits against nearby enemies ignore their cold resistance. ', 797, 'Art/2DArt/SkillIcons/Vaal Skill Icons/Vaalauracoldresist.dds', '[4]', '[1,4,7,14,22,8,37,38,71,29,63,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[11124]', '[1979]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1229, 'vaal_impurity_of_lightning', 'Vaal Impurity of Lightning', 'Casts an aura that reduces lightning damage taken and provides shock immunity to you and nearby allies, and makes hits against nearby enemies ignore their lightning resistance. ', 797, 'Art/2DArt/SkillIcons/Vaal Skill Icons/Vaalauralightningresist.dds', '[4]', '[1,4,7,14,22,8,37,38,71,30,63,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[11125]', '[1979]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
