(1232, 'tectonic_slam', 'Tectonic Slam', 'Slam the ground, unleashing a fiery fissure in front of you, dealing area damage and randomly releasing a number of smaller fissures branching off from it. Consume an Endurance Charge every third time you slam the ground with this skill. Requires a Mace, Sceptre, Sword, Axe, Staff, or Unarmed.', 800, 'Art/2DArt/SkillIcons/TectonicSlam.dds', '[1,2,10]', '[0,7,23,19,28,91,14]', '[12,32,14,17,11,16,9,10,15,36,57]', '', '', 1, '', 0, 22, 1, '[7832,7833,18222,18223]', '[24,436,13018,18135]', '[]', 1, 1, '[12336]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1233, 'tectonic_slam_alt_x', 'Tectonic Slam of Cataclysm', 'Slam the ground, consuming all Endurance Charges and unleashing a fiery fissure in front of you, dealing area damage and randomly releasing a number of smaller fissures branching off from it. Requires a Mace, Sceptre, Sword, Axe, Staff, or Unarmed.', 800, 'Art/2DArt/SkillIcons/TectonicSlam.dds', '[1,2,10]', '[0,7,23,19,28,91,14]', '[12,32,14,17,11,16,9,10,15,36,57]', '', '', 1, '', 0, 22, 1, '[7832,7833,18222,18223]', '[24,436,13018,18135]', '[]', 1, 1, '[12336]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1232, ''),
