(1257, 'shade_form', 'Shade Form', 'Makes you immune to physical damage, and harder for enemies to detect, for a duration.', 821, 'Art/2DArt/BuffIcons/AbyssShadowForm.dds', '[4]', '[1,8,4,31,36,49,27,89]', '[]', '', '', 1, '', 0, 22, 1, '[15688]', '[9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1258, 'summon_petrification_statue', 'Petrification Statue', 'Creates a Petrification Statue in front of you, which will slow enemies with its gaze, until they become fully petrified.', 822, 'Art/2DArt/SkillIcons/SummonPetrificationStatue.dds', '[1,2]', '[1,8,31,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
