(1261, 'void_shot', 'Void Shot', 'Fires an arrow which decelerates to the target location, the arrow will then become unstable and explode dealing weapon damage in an area, converting half of the physical damage to cold damage.', 825, 'Art/2DArt/SkillIcons/VoidShotSkill.dds', '[2,1]', '[0,2,6,7,31,36,49,29,56]', '[13]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1262, 'tentacle_smash', 'Tentacle Whip', 'This attack causes three otherworldly tentacles to strike the ground around you, each dealing your attack damage in an area.', 826, 'Art/2DArt/SkillIcons/TentacleSlam.dds', '[2,1]', '[0,6,7,31,36,49]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1263, 'glimpse_of_eternity', 'Glimpse of Eternity', 'Creates an Eternity Sphere at your location, which reduces the Action Speed of enemies within it. The amount of Action Speed reduction applied by the sphere decreases to zero over its duration.', 827, 'Art/2DArt/SkillIcons/TimeAnomaly.dds', '[4]', '[1,7,31,36,49,8,71,83,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1264, 'volatile_anomaly', 'Volatile Anomaly', 'Creates an orb which moves towards nearby enemies, exploding after a duration or when it gets close enough. The explosion deals cold spell damage in an area, and leaves behind a Vortex on the ground for a secondary duration which continues to deal cold damage over time and chill enemies caught in it.', 828, 'Art/2DArt/SkillIcons/SummonAnomaly.dds', '[1]', '[1,31,36,49,8,7,6,29,67,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
