(1276, 'intimidating_cry', 'Intimidating Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants movement speed.', 840, 'Art/2DArt/SkillIcons/WarCryIntimidating.dds', '[4]', '[7,4,8,62,89,27]', '[]', '', '', 1, 'IntimidatingCry', 0, 22, 1, '[9796,5623,12465,12467]', '[9795,4602,3396,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1277, 'intimidating_cry_triggered', 'Intimidating Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants movement speed.', 840, 'Art/2DArt/SkillIcons/WarCryIntimidating.dds', '[4]', '[7,4,8,49,62,89,27,36,31]', '[]', '', '', 1, 'CatsStealthTriggeredIntimidatingCry', 0, 22, 1, '[9796,5623,12465,12467]', '[9795,4602,3396,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
