(1349, 'consecrated_path', 'Consecrated Path', 'Slams the ground at a targeted location. If an enemy is near where you target, you''ll teleport to it from a short distance away, slam, and create an area of consecrated ground. Can''t be supported by Multistrike, and requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 895, 'Art/2DArt/SkillIcons/HolyPath.dds', '[1,22,20]', '[19,0,7,33,31,6,8,28,91,14]', '[9,10,15,11,16,12,32,17,14,36,57]', '', '', 1, '', 0, 22, 1, '[8515,8516,18242,18243]', '[24,436,12228,1493]', '[]', 1, 1, '[8490]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1350, 'consecrated_path_alt_x', 'Consecrated Path of Endurance', 'Slams the ground at a targeted location. If an enemy is near where you target, you''ll teleport to it from a short distance away, slam, and create an area of consecrated ground. The cooldown can be bypassed by expending an Endurance Charge. Can''t be supported by Multistrike, and requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 895, 'Art/2DArt/SkillIcons/HolyPath.dds', '[1,22,20]', '[19,0,7,33,31,6,8,28,91,14,89]', '[9,10,15,11,16,12,32,17,14,36,57]', '', '', 1, '', 0, 22, 1, '[8515,8516,18242,18243]', '[24,436,12228,1493]', '[]', 1, 1, '[8490]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1349, ''),
