(1352, 'smite', 'Smite', 'Performs a melee attack, and causes lightning to strike a nearby enemy, dealing damage in an area. Each target can only be hit once by this skill. Hitting an enemy grants an aura for a duration. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 896, 'Art/2DArt/SkillIcons/Smite.dds', '[1,2]', '[19,0,7,8,23,6,20,38,4,30]', '[9,10,15,11,16,12,32,17,14,36,57]', '', '', 1, '', 0, 22, 1, '[8514,18336]', '[24,18279]', '[]', 1, 1, '[17679]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1353, 'smite_alt_x', 'Smite of Divine Judgement', 'Performs a melee attack, and causes lightning to strike nearby enemies, dealing damage in an area. Each target can only be hit once by this skill. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed.', 896, 'Art/2DArt/SkillIcons/Smite.dds', '[1,2]', '[19,0,7,23,6,20,30]', '[9,10,15,11,16,12,32,17,14,36,57]', '', '', 1, '', 0, 22, 1, '[8514,18336]', '[24,18279]', '[]', 1, 1, '[17679]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1352, ''),
