(1359, 'dynamite', 'Throw Dynamite', 'Throws a stick of Dynamite to the target location which explodes after a short delay. Deals damage to enemies within the radius based on their Rarity. Can be used to destroy Fractured Walls.', 899, 'Art/2DArt/SkillIcons/DynamiteSkill.dds', '[1,8,22]', '[2,56,6,7,13,14,15,21,31,63,84,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1360, 'scourge_arrow', 'Scourge Arrow', 'Channel to infuse an arrow with chaos, gaining stages while it is held. Release to fire it, leaving spore pods in its wake. Each spore pod blooms, firing thorn arrows, which travel for a short time before dissipating. Modifiers that cause additional projectiles to be fired will only apply to the initial arrows, and the spore pods will be divided between those arrows.', 900, 'Art/2DArt/SkillIcons/VirulentArrowSkillIcon.dds', '[18,11,22]', '[0,40,57,2,56,14,6,47,41]', '[13]', '', '', 1, '', 0, 22, 1, '[8519,18232]', '[24,9969]', '[]', 1, 1, '[8513]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1361, 'scourge_arrow_alt_x', 'Scourge Arrow of Menace', 'Fire an arrow that leaves a spore pod in its wake. The spore pod blooms, firing thorn arrows, which travel for a short time before dissipating. Modifiers that cause additional projectiles to be fired will only apply to the initial arrows, each of which leaves its own spore pod.', 900, 'Art/2DArt/SkillIcons/VirulentArrowSkillIcon.dds', '[18,11,22]', '[0,40,57,2,56,14,6,41,13,15,31]', '[13]', '', '', 1, '', 0, 22, 1, '[8519,18232]', '[24,9969]', '[]', 1, 1, '[8513]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1360, ''),
(1362, 'scourge_arrow_alt_y', '[DNT] ScourgeArrowAltY', 'Channel to infuse an arrow with chaos, gaining stages while it is held. Release to fire it, leaving spore pods in its wake. Each spore pod blooms, firing thorn arrows, which travel for a short time before dissipating. Modifiers that cause additional projectiles to be fired will only apply to the initial arrows, and the spore pods will be divided between those arrows.', 900, 'Art/2DArt/SkillIcons/VirulentArrowSkillIcon.dds', '[18,11,22]', '[0,40,57,2,56,14,6,47,41]', '[13]', '', '', 1, '', 0, 22, 1, '[8519,18232]', '[24,9969]', '[]', 1, 1, '[8513]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1360, ''),
