(1365, 'toxic_rain', 'Toxic Rain', 'Fire arrows into the air that rain down around the targeted area, dealing damage to enemies they hit and creating spore pods where they land. Each spore pod deals chaos damage over time to nearby enemies and slows their movement speed. The pods last for a duration before bursting, dealing area damage.', 903, 'Art/2DArt/SkillIcons/RainOfSpores.dds', '[1,2]', '[0,40,57,7,10,14,13,15,6,41,8,34,61,41,31,88]', '[13]', '', '', 1, '', 1, 22, 1, '[8520,8521,8522,18545,18546]', '[24,175,452,6155,1108]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1366, 'toxic_rain_alt_x', 'Toxic Rain of Sporeburst', 'Fire arrows into the air that rain down around the targeted area, dealing damage to enemies they hit and creating spore pods where they land. Each spore pod slows the movement speed of nearby enemies. The pods last for a duration before bursting, dealing area damage.', 903, 'Art/2DArt/SkillIcons/RainOfSpores.dds', '[1,2]', '[0,40,57,7,10,14,13,15,6,41,8,61,31,88]', '[13]', '', '', 1, '', 1, 22, 1, '[8520,8521,8522,18545,18546]', '[24,175,452,6155,1108]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1365, ''),
(1367, 'toxic_rain_alt_y', 'Toxic Rain of Withering', 'Fire arrows into the air that rain down around the targeted area, dealing damage to enemies they hit and creating spore pods where they land. Each spore pod deals chaos damage over time to nearby enemies and withers them, causing them to take increased chaos damage. The pods last for a duration before bursting, dealing area damage.', 903, 'Art/2DArt/SkillIcons/RainOfSpores.dds', '[1,2]', '[0,40,57,7,10,14,13,15,6,41,8,34,61,41,31,88]', '[13]', '', '', 1, '', 1, 22, 1, '[8520,8521,8522,18545,18546]', '[24,175,452,6155,1108]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1365, ''),
(1368, 'toxic_rain_triggered', 'Toxic Rain', 'Fire arrows into the air that rain down around the targeted area, dealing damage to enemies they hit and creating spore pods where they land. Each spore pod deals chaos damage over time to nearby enemies and slows their movement speed. The pods last for a duration before bursting, dealing area damage.', 903, 'Art/2DArt/SkillIcons/RainOfSpores.dds', '[1,2]', '[0,40,57,7,10,14,13,15,6,41,8,34,61,41,31,88,36,49,89]', '[13]', '', '', 1, '', 1, 22, 1, '[8520,8521,8522,18545,18546]', '[24,175,452,6155,1108]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1369, 'summon_holy_relic', 'Summon Holy Relic', 'Summon a Holy Relic that stays near you. When you hit an enemy with an attack, the Holy Relic triggers a nova spell with a short cooldown, that deals physical damage to enemies and grants life regeneration to allies in an area around it. This life regeneration is higher when applied to minions.', 904, 'Art/2DArt/SkillIcons/HolyRelicSkillIcon.dds', '[1,2]', '[31,15,5,17,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[6,1,7,36,8,27,83]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1370, 'summon_holy_relic_alt_x', 'Summon Holy Relic of Conviction', 'Summon a Holy Relic that stays near you. When you hit an enemy with an attack, the Holy Relic triggers a spell with a short cooldown, that deals physical damage to enemies in an area around a nearby enemy.', 904, 'Art/2DArt/SkillIcons/HolyRelicSkillIcon.dds', '[1,2]', '[31,15,5,17,21,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[6,1,7,36,27]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 1369, ''),
