(1411, 'storm_brand', 'Storm Brand', 'Creates a magical brand which can attach to a nearby enemy. It periodically activates while attached, firing beams which deal damage to nearby enemies and those around them. The brand will detach if the enemy dies.', 928, 'Art/2DArt/SkillIcons/ConduitSigil.dds', '[1,2]', '[1,6,7,30,18,8,14,13,15,31,21,64,71]', '[]', '', '', 1, '', 0, 22, 1, '[8833,8829,8845,18335]', '[8831,8828,24,18278]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
