(1416, 'war_banner', 'War Banner', 'You must gain Valour from melee combat to use this skill, which will consume all Valour to place a banner with an aura. The aura will be larger and more powerful the more Valour was consumed. The banner lasts for a duration, but will end early if you leave the aura, or use the skill again while it''s active.', 931, 'Art/2DArt/SkillIcons/WarBanner.dds', '[1]', '[4,7,1,8,38,63,71,70,27,87,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[8842,8874,15228]', '[14217,1979,14925]', '[]', 1, 1, '[20791]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(1417, 'dread_banner', 'Dread Banner', 'You must gain Valour from melee combat to use this skill, which will consume all Valour to place a banner with an aura. The aura will be larger and more powerful the more Valour was consumed. The banner lasts for a duration, but will end early if you leave the aura, or use the skill again while it''s active.', 932, 'Art/2DArt/SkillIcons/DreadBanner.dds', '[1]', '[4,7,1,8,38,63,71,70,87,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[8842,8873,15227]', '[14217,1979,14925]', '[]', 1, 1, '[20791]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
