(1420, 'shattering_steel', 'Shattering Steel', 'Swing an Axe or Sword, firing projectiles which shatter on impact or soon after being launched, dealing area damage in front of where they shatter.', 935, 'Art/2DArt/SkillIcons/ShatteringSteel.dds', '[1,2]', '[0,2,6,10,40,7,27,56]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[8810,8848,8849,13193]', '[8811,24,175,13187]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1421, 'shattering_steel_alt_x', 'Shattering Steel of Ammunition', 'Swing an Axe or Sword, consuming Steel Shards to gain a Steel Ward that protects you for a duration, and fire projectiles which shatter on impact or soon after being launched, dealing area damage in front of where they shatter. Steel Shards are gained with the Call of Steel Skill.', 935, 'Art/2DArt/SkillIcons/ShatteringSteel.dds', '[1,2]', '[0,2,6,10,40,7,27,56,95,8]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[8810,8848,8849,13193]', '[8811,24,175,13187]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1420, ''),
