(1451, 'purifying_flame', 'Purifying Flame', 'A wave of divine fire deals damage in a line, then creates Consecrated Ground and deals damage in an area around the targeted location. A larger shockwave then expands outwards, damaging enemies standing on Consecrated Ground that were not already hit.', 961, 'Art/2DArt/SkillIcons/PurifyingFlame.dds', '[2,1,22]', '[1,7,6,8,13,14,15,31,21,28,69,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9262,9246,18242,18243]', '[8965,24,12228,1493]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
