(1457, 'soulrend', 'Soulrend', 'Fires a projectile that turns towards enemies in front of it, damaging and piercing through those it hits, and leeching some of that damage as energy shield. As the projectile travels, it repeatedly applies a short but powerful chaos damage over time debuff to each enemy in an area around it.', 965, 'Art/2DArt/SkillIcons/Soulrend.dds', '[2,1]', '[1,7,8,2,34,6,41,21,31,13,15,14,69,71,56]', '[]', '', '', 1, '', 0, 22, 1, '[9240,9241,18541,18542]', '[24,175,177,175]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1458, 'soulrend_alt_x', 'Soulrend of Reaping', 'Fires a projectile that deals chaos damage to enemies it hits and leeches some of that damage as energy shield.', 965, 'Art/2DArt/SkillIcons/Soulrend.dds', '[2,1]', '[1,2,6,41,21,31,13,15,14,69,56]', '[]', '', '', 1, '', 0, 22, 1, '[9240,9241,18541,18542]', '[24,175,177,175]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1457, ''),
(1459, 'soulrend_alt_y', 'Soulrend of the Spiral', 'Fires a series of projectiles in a spiral that turn towards enemies in front of them, damaging and piercing through those they hit, and leeching some of that damage as energy shield. As the projectiles travel, they repeatedly apply a short but powerful chaos damage over time debuff to each enemy in an area around them.', 965, 'Art/2DArt/SkillIcons/Soulrend.dds', '[2,1]', '[1,7,8,2,34,6,41,21,31,13,15,14,69,71,56,58]', '[]', '', '', 1, '', 0, 22, 1, '[9240,9241,18541,18542]', '[24,175,177,175]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1457, ''),
(1460, 'bane', 'Bane', 'Applies a debuff to enemies in an area, which deals chaos damage over Time. Linked hex curses are also applied to those enemies. The debuff deals more damage and lasts longer for each hex applied this way.  This skill cannot be used by Totems, Traps, or Mines.', 966, 'Art/2DArt/SkillIcons/DarkRitual.dds', '[2,1,22]', '[1,7,8,34,41,21,55,31,48,69,71,96]', '[]', '', '', 1, '', 0, 22, 1, '[9243,9244]', '[24,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1461, 'bane_alt_x', 'Bane of Condemnation', 'Applies a debuff to enemies in a small area, which deals chaos damage over Time. Linked hex curses are also applied to those enemies. The debuff deals more damage and lasts longer for each hex applied this way.  This skill cannot be used by Totems, Traps, or Mines.', 966, 'Art/2DArt/SkillIcons/DarkRitual.dds', '[2,1,22]', '[1,7,8,34,41,21,55,31,48,69,71,96]', '[]', '', '', 1, '', 0, 22, 1, '[9243,9244]', '[24,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 1460, ''),
(1462, 'bane_alt_y', '[DNT] DarkRitualAltY', 'Applies a debuff to enemies in an area, which deals chaos damage over Time. Linked hex curses are also applied to those enemies. The debuff deals more damage and lasts longer for each hex applied this way.  This skill cannot be used by Totems, Traps, or Mines.', 966, 'Art/2DArt/SkillIcons/DarkRitual.dds', '[2,1,22]', '[1,7,8,34,41,21,55,31,48,69,71,96]', '[]', '', '', 1, '', 0, 22, 1, '[9243,9244]', '[24,436]', '[]', 1, 1, '[18313]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 1460, ''),
(1463, 'wave_of_conviction', 'Wave of Conviction', 'An expanding wave of energy surges forward, damaging enemies in a cone-shaped area over a duration. Each enemy hit is inflicted with Exposure matching the element of which they took the highest damage. Only one Wave of Conviction can be active at a time', 967, 'Art/2DArt/SkillIcons/Purge.dds', '[2,1]', '[1,7,6,8,13,14,15,31,28,30,69,21,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9252,9253,9254]', '[24,217,9396]', '[]', 1, 1, '[18327]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1464, 'wave_of_conviction_alt_x', '[DNT] PurgeAltX', 'An expanding wave of energy surges forward, damaging enemies in a cone-shaped area over a duration. Each enemy hit is inflicted with Exposure matching the element of which they took the highest damage. Only one Wave of Conviction can be active at a time', 967, 'Art/2DArt/SkillIcons/Purge.dds', '[2,1]', '[1,7,6,8,13,14,15,31,28,30,69,21,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9252,9253,9254]', '[24,217,9396]', '[]', 1, 1, '[18327]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1463, ''),
(1465, 'wave_of_conviction_alt_y', 'Wave of Conviction of Trarthus', 'An expanding wave of energy surges outwards from you, damaging enemies in a ring-shaped area over a duration. The ring then returns, damaging enemies again on the way back. Only one Wave of Conviction can be active at a time', 967, 'Art/2DArt/SkillIcons/Purge.dds', '[2,1]', '[1,7,6,8,13,14,15,31,69,21,71,27,28,83]', '[]', '', '', 1, '', 0, 22, 1, '[9252,9253,9254]', '[24,217,9396]', '[]', 1, 1, '[18327]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1463, ''),
(1466, 'zealotry', 'Zealotry', 'Casts an aura that grants bonuses to damage and critical strike chance of spells to you and your allies, and gives a chance to create Consecrated Ground against stronger enemies.', 968, 'Art/2DArt/SkillIcons/SpellDamageAura.dds', '[4]', '[1,7,4,11,22,14,38,63,71,80,84,85,89]', '[]', '', '', 1, 'Spell Damage Aura', 0, 22, 1, '[9182,9181,9183,15226,15256]', '[14196,1979,14217,14925,15106]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1467, 'storm_burst_new', 'Storm Burst', 'Unleash orbs of energy while you channel that repeatedly jump towards the targeted location until their duration expires, dealing damage in a small area after each jump. When you stop channelling, all remaining orbs explode, dealing higher damage in a larger area.', 969, 'Art/2DArt/SkillIcons/StormBurst.dds', '[18,17,23]', '[1,6,14,30,47,7,8,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[6471,6472,6588,18093]', '[221,436,24,18092]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1468, 'storm_burst_new_alt_x', 'Storm Burst of Repulsion', 'Unleash orbs of energy while you channel that repeatedly jump away from the targeted location until their duration expires, dealing damage in a small area after each jump. When you stop channelling, all remaining orbs explode, dealing higher damage in a larger area.', 969, 'Art/2DArt/SkillIcons/StormBurst.dds', '[18,17,23]', '[1,6,14,30,47,7,8,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[6471,6472,6588,18093]', '[221,436,24,18092]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1467, ''),
(1469, 'storm_burst_new_alt_y', '[DNT] StormBurstAltY', 'Unleash orbs of energy while you channel that repeatedly jump towards the targeted location until their duration expires, dealing damage in a small area after each jump. When you stop channelling, all remaining orbs explode, dealing higher damage in a larger area.', 969, 'Art/2DArt/SkillIcons/StormBurst.dds', '[18,17,23]', '[1,6,14,30,47,7,8,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[6471,6472,6588,18093]', '[221,436,24,18092]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1467, ''),
(1470, 'divine_ire', 'Divine Ire', 'Channelling draws in energy around you to repeatedly build up stages, damaging a number of nearby enemies when you do so. Release to unleash this energy in a burst around you and a beam in front of you. Modifiers to area of effect do not affect the beam. Maximum of 10 Stages.', 970, 'Art/2DArt/SkillIcons/DivineTempest.dds', '[18,17,23]', '[1,7,6,47,30,14,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9250,18093]', '[24,18092]', '[]', 1, 1, '[9251]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1471, 'divine_ire_alt_x', 'Divine Ire of Holy Lightning', 'Channelling draws in energy around you to repeatedly build up stages, damaging a number of nearby enemies when you do so. Release to unleash this energy in a powerful burst around you. Maximum of 10 Stages.', 970, 'Art/2DArt/SkillIcons/DivineTempest.dds', '[18,17,23]', '[1,7,6,47,30,14,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9250,18093]', '[24,18092]', '[]', 1, 1, '[9251]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1470, ''),
(1472, 'divine_ire_alt_y', 'Divine Ire of Disintegration', 'Channelling draws in energy around you to repeatedly build up stages. Release to unleash this energy in a beam in front of you. Modifiers to area of effect do not affect this skill. Maximum of 10 Stages.', 970, 'Art/2DArt/SkillIcons/DivineTempest.dds', '[18,17,23]', '[1,7,6,47,30,14,71,27]', '[]', '', '', 1, '', 0, 22, 1, '[9250,18093]', '[24,18092]', '[]', 1, 1, '[9251]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1470, ''),
