(1480, 'holy_flame_totem', 'Holy Flame Totem', 'Summons a totem that channels to fire a stream of flame at nearby enemies, and creates an area of consecrated ground around the totem.', 978, 'Art/2DArt/SkillIcons/flametotem.dds', '[1,2,20]', '[1,2,56,6,13,15,25,28,47,27,7]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/flametotem.jpg', 0, 'HolyFlameTotem', 0, 17, 1, '[4321,4294,4108,9263]', '[175,177,24,8965]', '[]', 1, 1, '[18325]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
