(1489, 'steelskin', 'Steelskin', 'Applies a buff which can take some of the damage from hits for you before being depleted. Shares a cooldown with other Guard skills.', 985, 'Art/2DArt/BuffIcons/QuickGuard.dds', '[4]', '[1,4,63,8,31,77,89]', '[]', '', '', 1, '', 0, 22, 1, '[10027,22126,9672]', '[1037,9521,9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1490, 'dash', 'Dash', 'Performs a series of quick teleports towards a targeted location. If using the "Attack in Place" option, the direction is reversed. Shares a cooldown with other Blink skills.', 986, 'Art/2DArt/SkillIcons/QuickDash.dds', '[1]', '[1,33,78,79,89,104]', '[]', '', '', 1, '', 0, 22, 1, '[10043,10028]', '[10041,11854]', '[]', 1, 1, '[]', 8, 4, 0, '', '[]', 0, 0, 1, NULL, ''),
(1491, 'quick_block', '[UNUSED] Quick Block  (NOT CURRENTLY USED)', '[UNUSED] Not used', 987, 'Art/2DArt/SkillIcons/auraspeed.dds', '[1]', '[0,4,8,6,63,7,19,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1492, 'misty_reflection', 'Misty Reflection', 'Dash backwards, leaving a short-lived mist copy of yourself that Taunts nearby Enemies for a short duration. The copy can be damaged by Enemies, and copies that are killed by an Enemy will apply a debuff in an area that makes affected targets take 30% increased Damage and deal 30% less Damage for 4 seconds.', 1317, 'Art/2DArt/SkillIcons/MistyRefelction.dds', '[1]', '[1,33,78,79,89,104,5,8,7,4]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1493, 'replicate', '[UNUSED] Replicate  (NOT CURRENTLY USED)', '[UNUSED] Summon replications of your character that follow you. When you use a supported skill, the replications also use their copy of the skill. Additional Projectiles are distributed evenly among replications.', 988, 'Art/2DArt/SkillIcons/passives/Survivalist.dds', '[4]', '[5,1,8,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[0,19,20,23,6,7,2,18,8,34,40,56]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1494, 'bladestorm', 'Bladestorm', 'Perform a spinning attack, damaging enemies around you and creating a bladestorm matching your stance. The bladestorm repeatedly damages enemies, based on your weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. Requires a Sword or Axe. You are in Blood Stance by default.', 989, 'Art/2DArt/SkillIcons/BloodBladeStorm.dds', '[2,1]', '[0,19,7,8,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[10030,13108]', '[24,13542]', '[]', 1, 1, '[9458,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1495, 'bladestorm_alt_x', 'Bladestorm of Uncertainty', 'Perform a spinning attack, damaging enemies around you and creating a random bladestorm. The bladestorm repeatedly damages enemies, based on your weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. Requires a Sword or Axe.', 989, 'Art/2DArt/SkillIcons/BloodBladeStorm.dds', '[2,1]', '[0,19,7,8,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[10030,13108]', '[24,13542]', '[]', 1, 1, '[9458,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1494, ''),
(1496, 'bladestorm_alt_y', '[DNT] BladestormAltY', 'Perform a spinning attack, damaging enemies around you and creating a bladestorm matching your stance. The bladestorm repeatedly damages enemies, based on your weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. Requires a Sword or Axe. You are in Blood Stance by default.', 989, 'Art/2DArt/SkillIcons/BloodBladeStorm.dds', '[2,1]', '[0,19,7,8,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[10030,13108]', '[24,13542]', '[]', 1, 1, '[9458,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1494, ''),
(1497, 'blood_and_sand', 'Blood and Sand', 'Casts a buff that grants different bonuses to melee skills depending on your stance. Using the skill again alternates between Blood Stance and Sand Stance.', 990, 'Art/2DArt/BuffIcons/SandStance.dds', '[4]', '[1,4,63,11,63,84,85,89,92]', '[]', '', '', 1, '', 0, 22, 1, '[10031,15202,15232]', '[4602,14925,15106]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1498, 'berserk', 'Berserk', 'Consumes Rage at an accelerating rate to increase the effects of Rage.', 991, 'Art/2DArt/BuffIcons/Beserk.dds', '[4]', '[1,4,31,63,85,89]', '[]', '', '', 1, 'Berserk', 0, 22, 1, '[9714,10045]', '[9521,4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1499, 'perforate', 'Perforate', 'Smash the ground to bring forth multiple spears to damage enemies. When in Blood Stance, multiple spikes burst from the ground in sequence, able to hit enemies multiple times. In Sand Stance, the spikes are thrust outwards. Requires a Sword or Axe. You are in Blood Stance by default.', 992, 'Art/2DArt/SkillIcons/Bloodspears.dds', '[2,1]', '[0,7,6,19,23,91,14]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[10032,10033,18079]', '[436,24,18078]', '[]', 1, 1, '[9489]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, '');
