(293, 'ice_shot', 'Ice Shot', 'Fires an arrow that converts some physical damage to cold on its target and converts all physical damage to cold in a cone behind that target.', 152, 'Art/2DArt/SkillIcons/iceshot.dds', '[1,2]', '[0,40,2,56,7,29,31,57,14,13,15]', '[13]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/iceshot.jpg', 0, 'IceShot', 0, 22, 1, '[4064,4304,4246,5486,6409,6424,10900,18206,18209]', '[24,217,436,5621,6374,6360,10899,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
