(298, 'creeping_frost', 'Creeping Frost', 'Fire an icy projectile that bursts on impact or when reaching the targeted area, dealing area damage and creating a chilling area that deals cold damage over time. This area will creep across the ground towards nearby enemies until its duration expires.', 154, 'Art/2DArt/SkillIcons/arcticbreath.dds', '[1,2]', '[1,2,56,6,13,14,15,8,7,21,31,29,67,69,71,34]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/arcticbreath.jpg', 0, 'CreepingFrost', 0, 22, 1, '[4093,4302,4255,8900,18540,18561]', '[24,217,436,8901,11029,13376]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(299, 'creeping_frost_alt_x', 'Creeping Frost of Floes', 'Fire a single icy projectile that bursts on impact or when reaching the targeted area, dealing area damage and creating a chilling area that deals cold damage over time. This area will creep rapidly across the ground towards nearby enemies until its duration expires.', 154, 'Art/2DArt/SkillIcons/arcticbreath.dds', '[1,2]', '[1,2,56,6,13,14,15,8,7,21,31,29,67,69,71,34]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/arcticbreath.jpg', 0, 'CreepingFrost', 0, 22, 1, '[4093,4302,4255,8900,18540,18561]', '[24,217,436,8901,11029,13376]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 298, ''),
