(301, 'arctic_armour_old', 'Arctic Armour', 'Summons an icy shield that protects against physical and fire damage. It drains your mana while active and at a faster rate while you are moving. When you have no mana left, the skill turns off. While active, it leaves a trail of ground ice which lasts for a short duration.', 155, 'Art/2DArt/SkillIcons/Iceshield.dds', '[4]', '[1,4,14,8,11,22,31,29,67,71]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/ice-shield.jpg', 0, 'ArcticArmour', 0, 22, 1, '[4457]', '[4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
