(320, 'incinerate_old', 'Incinerate', 'Launches a torrent of fire from your hand. The longer you repeatedly cast the spell from the same location, the larger and more damaging the flames become.', 170, 'Art/2DArt/SkillIcons/flamethrower.dds', '[1,2]', '[1,2,56,6,14,28]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/incinerate.jpg', 1, 'Incinerate', 0, 22, 1, '[4082,4295]', '[24,177]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(321, 'incinerate_channel', 'Incinerate', 'Continuously launches a torrent of fire from your hand. The longer you channel this spell, the larger and more damaging the flames become.', 171, 'Art/2DArt/SkillIcons/flamethrower.dds', '[1,11,22]', '[1,2,56,6,14,28,47]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/intelligence/incinerate.jpg', 1, 'Incinerate', 0, 22, 1, '[4082,4295]', '[24,177]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(322, 'incinerate', 'Incinerate', 'Continuously launches a torrent of fire from your hand, repeatedly damaging enemies. As you channel this spell longer, the flames spread wider close to you and spread longer directly in front of you. When you stop channelling you release a wave of fire damage over a wide and long area that will apply a powerful Ignite.', 172, 'Art/2DArt/SkillIcons/flamethrower.dds', '[18,23,17]', '[1,6,14,28,47,7,71,89]', '[]', '', '', 1, 'ExpandingFireCone', 0, 22, 1, '[4082,8056,8055,18251,18734]', '[24,436,7913,2809,6412]', '[]', 1, 1, '[18315]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(323, 'incinerate_alt_x', 'Incinerate of Expanse', 'Continuously launches a torrent of fire from your hand, repeatedly damaging enemies. As you channel this spell longer, the flames spread wider close to you and spread longer directly in front of you. When you stop channelling you release a slow-moving wave of fire damage over a very large area that will apply a powerful Ignite.', 172, 'Art/2DArt/SkillIcons/flamethrower.dds', '[18,23,17]', '[1,6,14,28,47,7,71,89]', '[]', '', '', 1, 'ExpandingFireCone', 0, 22, 1, '[4082,8056,8055,18251,18734]', '[24,436,7913,2809,6412]', '[]', 1, 1, '[18315]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 322, ''),
