(331, 'searing_bond', 'Searing Bond', 'Summons a totem that casts a beam of fire at you and each other totem you control, dealing burning damage to enemies caught in the beam. Enemies near either end of a beam also suffer burning damage.', 177, 'Art/2DArt/SkillIcons/SearingBond.dds', '[4,20]', '[1,34,13,15,22,24,25,31,28,48]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/SearingBond.jpg', 0, 'SearingBond', 1, 9, 1, '[4084,4339,4571,956]', '[24,1348,1878,955]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(332, 'searing_bond_alt_x', 'Searing Bond of Detonation', 'Summons a totem that casts a beam of fire at you and each other totem you control, dealing burning damage to enemies caught in the beam. Enemies near either end of a beam also suffer burning damage. Reaching maximum active totem count will cause all totems from this skill to detonate, applying the same burning damage for a duration. ', 177, 'Art/2DArt/SkillIcons/SearingBond.dds', '[4,20]', '[1,34,13,15,22,24,25,31,28,48,7,71,8]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/strength/SearingBond.jpg', 0, 'SearingBond', 1, 9, 1, '[4084,4339,4571,956]', '[24,1348,1878,955]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 331, ''),
