(356, 'lightning_trap', 'Lightning Trap', 'Throws a trap that launches a ring of projectiles through the enemy that set it off, dealing lightning damage to them and subsequent targets.', 196, 'Art/2DArt/SkillIcons/LightningProjectileTrap.dds', '[2]', '[1,6,2,56,32,15,30]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/LightningTrap.jpg', 0, 'LightningTrap', 1, 22, 1, '[3670,3671,3669,6381,6382,7891,7890,18216,18217,18218]', '[174,3396,24,6374,6360,12604,597,18131,16750,3886]', '[]', 1, 1, '[]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
