(359, 'vaal_lightning_trap', 'Vaal Lightning Trap', 'Throws a trap that launches a ring of projectiles through the enemy that set it off, dealing lightning damage to them and subsequent targets and leaving a trail of shocked ground.', 196, 'Art/2DArt/SkillIcons/LightningProjectileTrap.dds', '[2]', '[1,6,2,56,32,15,8,37,30]', '[]', '', '', 1, 'VaalLightningTrap', 1, 22, 1, '[3670,3669,6381,6382,7891,7890,18216,18217,18218]', '[174,24,6374,6360,12604,597,18131,16750,3886]', '[]', 1, 1, '[]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(360, 'smoke_mine', 'Smoke Mine', 'Throws a mine that will teleport you to it when detonated. It covers both your escape and arrival with a cloud of smoke that blinds enemies, and gives you a temporary buff to movement speed. Shares a cooldown with other Blink skills.', 197, 'Art/2DArt/SkillIcons/SmokeBomb.dds', '[1,2,3]', '[1,7,8,33,35,71,78,11,79,89]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/SmokeBomb.jpg', 0, 'SmokeMine', 1, 22, 1, '[4399,4573]', '[217,179]', '[]', 1, 1, '[]', 1, 0, 0, '', '[]', 0, 0, 1, NULL, ''),
