(363, 'animate_guardian', 'Animate Guardian', 'Animates a melee weapon or armour, attaching it to an invisible Guardian that fights by your side. Animating multiple items attaches them to the same Guardian. You cannot animate unidentified items. Cannot be used by Traps or Mines. If your Guardian dies you cannot summon an Animated Guardian again in that area.', 199, 'Art/2DArt/SkillIcons/animatearmour.dds', '[5,1]', '[1,5,17,14,31,76]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/animatearmor.jpg', 0, 'AnimateGuardian', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(364, 'animate_guardian_alt_x', 'Animate Guardian of Smiting', 'Animates a melee weapon or armour, attaching it to an invisible Guardian that fights by your side using Smite of Divine Judgement, ignoring weapon restrictions. Animating multiple items attaches them to the same Guardian. You cannot animate unidentified items. Cannot be used by Traps or Mines. If your Guardian dies you cannot summon an Animated Guardian again in that area.', 199, 'Art/2DArt/SkillIcons/animatearmour.dds', '[5,1]', '[1,5,17,14,31,76,30]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/animatearmor.jpg', 0, 'AnimateGuardian', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 363, ''),
(365, 'animate_guardian_alt_y', '[DNT] AnimateArmourAltY', 'Animates a melee weapon or armour, attaching it to an invisible Guardian that fights by your side. Animating multiple items attaches them to the same Guardian. You cannot animate unidentified items. Cannot be used by Traps or Mines. If your Guardian dies you cannot summon an Animated Guardian again in that area.', 199, 'Art/2DArt/SkillIcons/animatearmour.dds', '[5,1]', '[1,5,17,14,31,76]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/animatearmor.jpg', 0, 'AnimateGuardian', 0, 22, 1, '[]', '[]', '[0,19,20,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 363, ''),
