(367, 'spectral_throw', 'Spectral Throw', 'Throws a spectral copy of your melee weapon. It flies out and then returns to you, in a spinning attack that damages enemies in its path.', 201, 'Art/2DArt/SkillIcons/ghostlythrow.dds', '[1,2]', '[0,40,2,56]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, 'ThrownWeapon', 0, 22, 1, '[4061,4292,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[18241]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(368, 'spectral_throw_alt_x', 'Spectral Throw of Materialising', 'Throws an intangible spectral copy of your melee weapon. It flies out and then becomes tangible as it returns to you, in a spinning attack that only hits and damages enemies while returning.', 201, 'Art/2DArt/SkillIcons/ghostlythrow.dds', '[1,2]', '[0,40,2,56]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, 'ThrownWeapon', 0, 22, 1, '[4061,4292,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[18241]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 367, ''),
(369, 'spectral_throw_alt_y', 'Spectral Throw of Trarthus', 'Throws a trap which, once triggered, fires many spectral copies of your melee weapon. They fly out in all directions and then return to where the trap triggered, in a spinning attack that damages enemies in their path. If dual wielding, each Trap thrown will randomly use either the main hand or off hand weapon.', 201, 'Art/2DArt/SkillIcons/ghostlythrow.dds', '[1,2]', '[0,40,2,56,32]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, 'ThrownWeapon', 0, 22, 1, '[4061,4292,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[18241]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 367, ''),
(370, 'vaal_spectral_throw', 'Vaal Spectral Throw', 'Throws several spectral copies of your melee weapon. They fly out and then return to you, in a spinning attack that damages enemies in their path.', 201, 'Art/2DArt/SkillIcons/ghostlythrow.dds', '[1,2]', '[0,40,2,56,37]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4061,4292,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[18241]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
