(387, 'storm_call', 'Storm Call', 'Sets a marker at a location. After a short duration, lightning strikes the marker, dealing damage around it and causing lightning strikes at any other markers you''ve cast.', 213, 'Art/2DArt/SkillIcons/stormcall.dds', '[1,22,20]', '[1,6,7,8,13,14,15,31,21,30,55,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/stormcall.jpg', 0, 'StormCall', 0, 22, 1, '[4086,4301,4252,18208,18211]', '[24,217,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(388, 'storm_call_alt_x', 'Storm Call of Trarthus', 'Sets a marker at a location. After a short duration, a bolt strikes the marker, dealing physical damage around it and causing bolts to strike at any other markers you''ve cast. Bolt impacts will leave behind a pool of boiling blood, which deals physical damage over time to enemies within it for a secondary duration.', 213, 'Art/2DArt/SkillIcons/stormcall.dds', '[1,22,20]', '[1,6,7,8,13,14,15,31,21,55,69,71,27,34]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/stormcall.jpg', 0, 'StormCall', 0, 22, 1, '[4086,4301,4252,18208,18211]', '[24,217,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 387, ''),
(389, 'storm_call_alt_y', '[DNT] StormCallAltY', 'Sets a marker at a location. After a short duration, lightning strikes the marker, dealing damage around it and causing lightning strikes at any other markers you''ve cast.', 213, 'Art/2DArt/SkillIcons/stormcall.dds', '[1,22,20]', '[1,6,7,8,13,14,15,31,21,30,55,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/stormcall.jpg', 0, 'StormCall', 0, 22, 1, '[4086,4301,4252,18208,18211]', '[24,217,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 387, ''),
