(392, 'storm_call_attached', 'Storm Call', '', 214, 'Art/2DArt/SkillIcons/stormcall.dds', '[2,3]', '[1,6,7,8,13,14,15,31,21,30,71]', '[]', '', '', 1, '', 0, 22, 1, '[4086,4301,4252,18208,18211]', '[24,217,436,5079,18123]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(393, 'vaal_storm_call', 'Vaal Storm Call', 'Sets a marker at a location. Lightning strikes random enemies around the marker repeatedly over the skill''s duration, dealing damage in an area around the strike. Modifiers to the skill''s duration will also affect the delay between these strikes. When the duration ends, a large bolt of lightning strikes the marker, dealing damage around it.', 215, 'Art/2DArt/SkillIcons/stormcall.dds', '[1,22]', '[1,6,7,8,13,14,15,37,30,71,21]', '[]', '', '', 1, 'VaalStormCall', 0, 22, 1, '[4086,4301,4252,18208,18211]', '[24,217,436,5079,18123]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(394, 'atziri_unique_staff_storm_call', 'Storm of Judgement', 'Creates a number of markers around the targeted location, which will explode after a duration, dealing lightning damage. Cannot be supported by Spell Cascade.', 216, 'Art/2DArt/SkillIcons/StormOfJudgement.dds', '[1]', '[1,6,8,7,71,31,36,49,30,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(395, 'charged_blast', 'Flameblast', 'Channels to build up a large explosion. The longer you channel, the larger the area of effect and damage of the explosion. The explosion occurs after using another skill or after a short period without casting.', 217, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,28,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/flameblastimage.jpg', 1, 'Flameblast', 0, 22, 1, '[4310,4095,4258,18251]', '[556,24,436,2809]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(396, 'flameblast', 'Flameblast', 'Channels to build up a large explosion, which is released when you stop using the skill. The longer you channel, the larger the area of effect and damage of the explosion.', 218, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,28,47,71,89]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/flameblastimage.jpg', 0, 'Flameblast', 0, 22, 1, '[4310,4095,4258,18251,18734]', '[556,24,436,2809,6412]', '[]', 1, 1, '[18314]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(397, 'flameblast_alt_x', 'Flameblast of Celerity', 'Channels to build up an explosion, which is released when you stop using the skill or automatically at maximum stages. The longer you channel, the larger the area of effect and damage of the explosion.', 218, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,28,47,71,89]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/flameblastimage.jpg', 0, 'Flameblast', 0, 22, 1, '[4310,4095,4258,18251,18734]', '[556,24,436,2809,6412]', '[]', 1, 1, '[18314]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 396, ''),
(398, 'flameblast_alt_y', 'Flameblast of Contraction', 'Channels to concentrate an explosion, which is released when you stop using the skill. The longer you channel, the larger the damage of the explosion, but the smaller the area.', 218, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,28,47,71,89]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/flameblastimage.jpg', 0, 'Flameblast', 0, 22, 1, '[4310,4095,4258,18251,18734]', '[556,24,436,2809,6412]', '[]', 1, 1, '[18314]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 396, ''),
(399, 'blood_sacrament', 'Blood Sacrament', 'Channel this skill to reserve more and more of your life, building up power in a marker on the ground under you. Release to deal physical damage in an area based on how much life you reserved. Cannot be cast by Totems.', 218, 'Art/2DArt/SkillIcons/BloodChannel.dds', '[4]', '[1,6,7,47,71,11,27,83,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 1, 0, 1, NULL, ''),
(400, 'vaal_flameblast', 'Vaal Flameblast', 'Targets an area and builds up stages in that area based on cast speed. It explodes every 3 stages, until it reaches a maximum of 15. As it gains more stages, the area gets smaller but the damage gets higher.', 219, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,37,28,71,21]', '[]', '', '', 1, '', 0, 22, 1, '[4310,4095,4258,18251]', '[556,24,436,2809]', '[]', 1, 1, '[18314]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(401, 'vaal_charged_blast', 'Vaal Flameblast', 'Targets an area and builds up a large explosion. The build-up speed is based on cast speed. The explosion occurs after it reaches 10 stacks.', 220, 'Art/2DArt/SkillIcons/ChargedBlast.dds', '[1,2]', '[1,6,7,14,37,28,71,21]', '[]', '', '', 1, '', 0, 22, 1, '[4310,4095,4258,18251]', '[556,24,436,2809]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
