(403, 'atziri_unique_staff_flameblast', 'Flames of Judgement', 'Creates markers at your location and a targeted location, which grow over time based on cast speed, then explode, dealing fire damage. Cannot be supported by Spell Cascade.', 220, 'Art/2DArt/SkillIcons/FlamesOfJudgement.dds', '[1]', '[1,6,8,7,71,31,36,49,28,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
