(407, 'barrage', 'Barrage', 'After a short preparation time, you fire individual projectiles repeatedly with a Bow or Wand. These projectiles have a small randomised spread. This skill cannot be Triggered.', 224, 'Art/2DArt/SkillIcons/barrage.dds', '[1,2]', '[0,40,57,2,56,14,13,15,126]', '[13,8]', '', 'http://webcdn.pathofexile.com/public/chris/barrage.jpg', 0, 'Barrage', 0, 22, 1, '[4277,4076,4317,18231]', '[70,24,175,8367]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
