(411, 'infernal_swarm', 'Wildfire', 'Fire damages and ignites those around a targeted enemy. This effect chains and repeats on other enemy targets.', 226, 'Art/2DArt/SkillIcons/InfernalSwarm.dds', '[1,2]', '[1,6,13,14,15,18,21,31,34,24,7,28,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(412, 'summon_raging_spirit', 'Summon Raging Spirit', 'Summons a short-lived flaming skull that rushes at nearby enemies and attacks them rapidly, converting all its physical damage to fire. Enemies will not directly engage these spirits, and can pass through them.', 227, 'Art/2DArt/SkillIcons/SummonElemental.dds', '[1,2]', '[1,5,8,17,13,14,15,21,31,28,69,76]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/enragedspirit.jpg', 0, 'SummonRagingSpirit', 1, 22, 1, '[3662]', '[8952]', '[0,19,20,23]', 1, 1, '[12073]', 8, 3, 0, '', '[]', 0, 0, 1, NULL, ''),
