(417, 'flame_surge', 'Flame Surge', 'Strikes enemies in front of you with a surge of flame. Burning enemies are dealt more damage. If you hit an ignited enemy, will create burning ground under them. Your damage modifiers don''t apply to this burning ground.', 228, 'Art/2DArt/SkillIcons/flamewhip.dds', '[1,2]', '[1,6,13,14,15,21,31,7,28,69,71,8]', '[]', '', '', 1, 'FlameWhip', 0, 22, 1, '[4311,4079,4336]', '[556,24,3760]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(418, 'flame_surge_alt_x', 'Flame Surge of Combusting', 'Strikes enemies in front of you with a surge of flame. If this ignites an enemy a large area of burning ground will be created under them. Your damage modifiers don''t apply to this burning ground.', 228, 'Art/2DArt/SkillIcons/flamewhip.dds', '[1,2]', '[1,6,13,14,15,21,31,7,28,69,71,8]', '[]', '', '', 1, 'FlameWhip', 0, 22, 1, '[4311,4079,4336]', '[556,24,3760]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 417, ''),
(419, 'flame_surge_alt_y', '[DNT] FlameWhipAltY', 'Strikes enemies in front of you with a surge of flame. Burning enemies are dealt more damage. If you hit an ignited enemy, will create burning ground under them. Your damage modifiers don''t apply to this burning ground.', 228, 'Art/2DArt/SkillIcons/flamewhip.dds', '[1,2]', '[1,6,13,14,15,21,31,7,28,69,71,8]', '[]', '', '', 1, 'FlameWhip', 0, 22, 1, '[4311,4079,4336]', '[556,24,3760]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 417, ''),
