(422, 'desecrate', 'Desecrate', 'Desecrates the ground, spawning corpses based on monsters in the current area and dealing chaos damage over time to enemies. If you are using the Raise Spectre skill there is a chance to spawn spectral corpses matching your most recently raised Spectres. Spectral corpses cannot be interacted with except by Minion skills.', 230, 'Art/2DArt/SkillIcons/Desecrate.dds', '[1,22,20]', '[1,7,8,13,14,15,31,34,21,41,55,71,132]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/desecrate.jpg', 0, 'Desecrate', 1, 22, 1, '[4428,4122,10414]', '[3396,24,217]', '[]', 1, 1, '[6918]', 8, 3, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(423, 'flesh_offering', 'Flesh Offering', 'Consumes a corpse, which temporarily empowers your minions with swiftness. The skill consumes other nearby corpses, increasing the duration for each corpse consumed.', 231, 'Art/2DArt/SkillIcons/FleshOffering.dds', '[6,20]', '[1,4,8,31,5,13,15,14,124]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/fleshoffering.jpg', 0, 'FleshOffering', 0, 22, 1, '[4398,4572,10741,16067]', '[217,8591,217,4481]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(424, 'vaal_flesh_offering', 'Vaal Flesh Offering', '', 232, 'Art/2DArt/SkillIcons/FleshOffering.dds', '[1,20]', '[1,4,8,31,5,13,15,14,124,37]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/fleshoffering.jpg', 1, 'VaalFleshOffering', 0, 22, 1, '[4398,4572,10741,16067]', '[217,8591,217,4481]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(425, 'bone_offering', 'Bone Offering', 'Consumes a corpse, granting all of your minions the power to block both attacks and spells. The skill consumes other nearby corpses, increasing the duration for each corpse consumed.', 233, 'Art/2DArt/SkillIcons/BoneOffering.dds', '[6,20]', '[1,4,8,31,5,13,15,14,124]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/boneoffering.jpg', 0, 'BoneOffering', 0, 22, 1, '[4397,4565,10741,16068]', '[217,1090,217,4481]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(426, 'glacial_cascade', 'Glacial Cascade', 'Icicles emerge from the ground in a series of small bursts, each damaging enemies caught in the area.', 234, 'Art/2DArt/SkillIcons/Upheaval.dds', '[1,2]', '[1,6,7,13,14,15,21,31,29,27,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/GlacialCascade.jpg', 0, 'GlacialCascade', 0, 22, 1, '[4096,4344,4259,6553]', '[24,1106,436,2152]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
