(453, 'molten_strike', 'Molten Strike', 'Infuses your melee weapon with molten energies to attack with physical and fire damage. This attack causes balls of molten magma to launch forth from the enemies you hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land.', 257, 'Art/2DArt/SkillIcons/MoltenStrike.dds', '[1,2]', '[0,2,7,19,20,28,40,81,90,23]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4057,4314,4245,11985,11987]', '[24,175,436,174,9969]', '[]', 1, 1, '[11983]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(454, 'molten_strike_alt_x', 'Molten Strike of the Zenith', 'Infuses your two-handed melee weapon with molten energies to attack with physical and fire damage. This attack causes balls of molten magma to launch forth from the enemies you hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land. Every fifth time you attack with this skill it fires more, high-damage projectiles.', 257, 'Art/2DArt/SkillIcons/MoltenStrike.dds', '[1,2]', '[0,2,7,19,20,28,40,81,90,23]', '[15,16,17,57,14]', '', '', 1, '', 0, 22, 1, '[4057,4314,4245,11985,11987]', '[24,175,436,174,9969]', '[]', 1, 1, '[11983]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 453, ''),
(455, 'molten_strike_alt_y', '[DNT] MoltenStrikeAltY', 'Infuses your melee weapon with molten energies to attack with physical and fire damage. This attack causes balls of molten magma to launch forth from the enemies you hit, divided amongst all enemies hit by the strike. These will deal area attack damage to enemies where they land.', 257, 'Art/2DArt/SkillIcons/MoltenStrike.dds', '[1,2]', '[0,2,7,19,20,28,40,81,90,23]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4057,4314,4245,11985,11987]', '[24,175,436,174,9969]', '[]', 1, 1, '[11983]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 453, ''),
(456, 'vaal_molten_strike', 'Vaal Molten Strike', 'Infuses your melee weapon with molten energies to attack with physical and fire damage. This attack causes balls of molten magma to launch forth causing area attack damage to enemies where they land.', 257, 'Art/2DArt/SkillIcons/MoltenStrike.dds', '[1,2]', '[0,2,7,19,20,28,40,81,18,37,121]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[4057,4314,4245,11985,11987,18537]', '[24,175,436,174,9969,8142]', '[]', 1, 1, '[11983]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
