(467, 'fire_nova', 'Fire Nova Mine', 'Lay a remote mine that you can detonate to create a series of fire novas. Each sequential nova from the same mine will do higher damage than the previous.', 267, 'Art/2DArt/SkillIcons/FireNovaMine.dds', '[4]', '[1,6,31,7,28,21,35,71,11]', '[]', '', '', 1, '', 1, 22, 1, '[4284,4077,4334]', '[218,24,2320]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(468, 'tornado_shot', 'Tornado Shot', 'Fires a piercing shot that travels until it reaches the targeted location. It will then fire projectiles out in all directions from that point, which will travel for a short time before disappearing.', 268, 'Art/2DArt/SkillIcons/TornadoShot.dds', '[1,2,20]', '[0,2,56,13,15,14,40,57,31]', '[13]', '', '', 1, 'TornadoShot', 0, 22, 1, '[4312,4092,18051]', '[556,24,18050]', '[]', 1, 1, '[]', 8, 5, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(469, 'tornado_shot_alt_x', 'Tornado Shot of Cloudburst', 'Fires a single payload arrow into the air to land at a targeted location. It will then fire arrows out in all directions from that point.', 268, 'Art/2DArt/SkillIcons/TornadoShot.dds', '[1,2,20]', '[0,2,88,13,15,14,40,57,31]', '[13]', '', '', 1, 'TornadoShot', 0, 22, 1, '[4312,4092,18051]', '[556,24,18050]', '[]', 1, 1, '[]', 8, 5, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 468, ''),
