(486, 'herald_of_ash', 'Herald of Ash', 'Grants a buff providing fire damage based on your physical damage. While you have this buff, if you kill an enemy, other enemies near them will be burned based on the overkill damage. The burn inflicted by this skill can only be affected by modifiers to damage over time (burning damage is damage over time).', 281, 'Art/2DArt/SkillIcons/HeraldofAsh.dds', '[4]', '[1,4,11,24,7,34,28,22,51,8,63,71,84,85,89]', '[]', '', '', 1, 'HeraldOfAsh', 0, 22, 1, '[4118,4381,9288,15211,15241]', '[24,14196,4602,14925,15106]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(487, 'herald_of_ice', 'Herald of Ice', 'Grants a buff adding cold damage to spells and attacks. If you shatter an enemy, this skill will cause them to explode and deal AoE cold damage to enemies near them. This damage is not affected by modifiers to spell damage.', 282, 'Art/2DArt/SkillIcons/HeraldofIce.dds', '[4]', '[1,4,11,6,7,29,22,51,63,71,84,85,89]', '[]', '', '', 1, 'HeraldOfIce', 0, 22, 1, '[4119,4382,9287,15212,15242]', '[24,14196,4602,14925,15106]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(488, 'herald_of_thunder', 'Herald of Thunder', 'Grants a buff which adds lightning damage to spells and attacks. If you kill a shocked enemy, this skill will create a storm, causing lightning bolts to strike enemies around you for a duration. The damage inflicted by this skill is not affected by modifiers to spell damage.', 283, 'Art/2DArt/SkillIcons/HeraldofThunder.dds', '[4]', '[1,4,11,6,7,8,30,22,51,63,71,84,85,89]', '[]', '', '', 1, 'HeraldOfThunder', 0, 22, 1, '[4120,4383,5672,15214,15244]', '[24,14196,4602,14925,15106]', '[]', 1, 1, '[12065]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(489, 'herald_of_agony', 'Herald of Agony', 'Grants a buff giving more poison damage and a chance to inflict poison. When you poison an enemy while you have this buff, you gain Virulence, and summon an Agony Crawler minion that uses projectile and area attacks. You will lose Virulence over time, at a rate which increases the more Virulence you have. The minion will die when you have no Virulence.', 284, 'Art/2DArt/SkillIcons/HeraldOfAgony.dds', '[4]', '[1,4,11,51,5,63,41,27,76,116,84,85,89]', '[]', '', '', 1, 'HeraldOfAgony', 0, 22, 1, '[8518,9289,15210,15240]', '[14196,4602,14925,15106]', '[6,0,41,2,40]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(490, 'herald_of_purity', 'Herald of Purity', 'Grants a buff which lets you deal more physical damage. When you kill an enemy while you have this buff, this skill will summon a Sentinel of Purity, or refresh the duration and life of an existing one instead if you have the maximum number of them. The Sentinels of Purity have a single-target melee attack and an area melee attack.', 285, 'Art/2DArt/SkillIcons/HeraldOfLight.dds', '[4]', '[1,4,11,51,5,63,8,27,76,84,85,89,128]', '[]', '', '', 1, 'HeraldOfLight', 0, 22, 1, '[8517,8437,15213,15243]', '[14196,4602,14925,15106]', '[6,0,19,20,23,7]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(491, 'herald_of_the_breach', 'Herald of the Hive', 'Grants a buff which causes you to deal more damage for each Herald skill affecting you. While you have this buff, this skill turns the space around you into a tear in reality, releasing pulses that damage enemies around you. Inflicting Ailments causes you to gain Otherworldly Pressure, which increases the frequency of the pulses. You will lose Otherworldly Pressure over time, at a rate which increases the more of it you have. The damage inflicted by this skill is not affected by modifiers to spell damage.', 286, 'Art/2DArt/SkillIcons/SovereignAmalgamate.dds', '[4]', '[1,4,11,51,63,8,84,85,27,29,28,30,41,7,71,89]', '[]', '', '', 1, 'HeraldOfTheBreach', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 0, 1, NULL, ''),
(492, 'rampage_summon_animated_weapon', '', '', 287, '', '[4]', '[1]', '[]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
