(494, 'consecrate', 'Consecrate', 'Creates an area of Consecrated Ground, providing life regeneration and reducing the effect of curses for you and allies who stand in it.', 289, 'Art/2DArt/BuffIcons/consecrated.dds', '[4]', '[1,8,31,7,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
