(496, 'poachers_mark', 'Poacher''s Mark', 'Curses a single enemy, lowering their physical damage reduction, and adding physical damage to all hits against them. Attacking the cursed enemy will grant life and mana, and killing them will grant a frenzy charge. You can only have one Mark at a time.', 290, 'Art/2DArt/SkillIcons/PoachersMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97]', '[]', '', '', 1, '', 1, 22, 1, '[4366,4402]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(497, 'poachers_mark_triggered', 'Poacher''s Mark', 'Curses a single enemy, lowering their physical damage reduction, and adding physical damage to all hits against them. Attacking the cursed enemy will grant life and mana, and killing them will grant a frenzy charge. You can only have one Mark at a time.', 290, 'Art/2DArt/SkillIcons/PoachersMark.dds', '[1,2]', '[1,13,14,15,21,31,68,69,84,85,97,89]', '[]', '', '', 1, '', 1, 22, 1, '[4366,4402]', '[1393,217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
