(803, 'sunder_old', 'Sunder', 'Slams the ground with a Mace, Sceptre, Axe or Staff, creating a wave of broken ground that damages enemies in an area in front of you. Enemies hit by the wave will release a circular shockwave, dealing damage to other enemies around them.', 463, 'Art/2DArt/SkillIcons/ShockwaveSlam.dds', '[1,2,10]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[4438,4142,4452,18238]', '[70,24,436,11626]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(804, 'sunder', 'Sunder', 'Slams the ground, creating a slow wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Using the skill again will stop the previous wave. Requires a Mace, Sceptre, Axe, Staff or Unarmed.', 464, 'Art/2DArt/SkillIcons/ShockwaveSlam.dds', '[1,2,10]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[4438,4142,4452,18238]', '[70,24,436,11626]', '[]', 1, 1, '[12407]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(805, 'sunder_alt_x', 'Sunder of Earthbreaking', 'Slams the ground, creating a wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Requires a Mace, Sceptre, Axe, Staff or Unarmed.', 464, 'Art/2DArt/SkillIcons/ShockwaveSlam.dds', '[1,2,10]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[4438,4142,4452,18238]', '[70,24,436,11626]', '[]', 1, 1, '[12407]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 804, ''),
(806, 'sunder_alt_y', 'Sunder of Trarthus', 'Slams the ground, creating a slow wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Using the skill again will stop the previous wave. When the wave reaches a target or terrain, it can restart aiming towards an enemy, if one is in range. Requires a Mace, Sceptre, Axe, Staff or Unarmed.', 464, 'Art/2DArt/SkillIcons/ShockwaveSlam.dds', '[1,2,10]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[4438,4142,4452,18238]', '[70,24,436,11626]', '[]', 1, 1, '[12407]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 804, ''),
