(812, 'summon_spectral_wolf', 'Summon Spectral Wolf', 'Summons a spectral wolf companion that attacks nearby enemies and dies after a duration. Each spectral wolf grants you a buff that adds damage to your attacks. If you have the maximum number of them, refreshes the duration and life of an existing one instead.', 469, 'Art/2DArt/SkillIcons/IllusionaryWolf.dds', '[4]', '[1,5,8,17,13,14,15,21,31,36,49,76,4]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,19,20,23]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(813, 'summon_spectral_wolf_triggered', 'Summon Spectral Wolf', 'Summons a spectral wolf companion that attacks nearby enemies and dies after a duration. Each spectral wolf grants you a buff that adds damage to your attacks. If you have the maximum number of them, refreshes the duration and life of an existing one instead.', 469, 'Art/2DArt/SkillIcons/IllusionaryWolf.dds', '[4]', '[1,5,8,17,13,14,15,21,31,36,49,76,4,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,19,20,23]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(814, 'summon_spectral_tiger', 'Summon Spectral Tiger', 'Summons a Spectral Tiger Companion that attacks nearby enemies and dies after a duration. Each Spectral Tiger grants you a buff that increases Critical Strike Chance, and increases Attack and Cast Speed. If you have the maximum number of them, refreshes the duration and life of an existing one instead.', 469, 'Art/2DArt/SkillIcons/SummonSpectralTiger.dds', '[4]', '[1,5,8,17,13,14,15,21,31,36,49,76,4,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,19,20,23]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
