(819, 'frost_bolt', 'Frostbolt', 'Fires a slow-moving projectile that pierces through enemies, dealing cold damage.', 471, 'Art/2DArt/SkillIcons/FrostBolt.dds', '[2,1]', '[1,2,56,6,13,14,15,21,29,31,69]', '[]', '', '', 1, '', 0, 22, 1, '[4628,4784,4785,5742]', '[24,218,457,175]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
