(823, 'vortex', 'Vortex', 'An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it.', 473, 'Art/2DArt/SkillIcons/FrostVortex.dds', '[1,22]', '[1,6,7,13,14,15,21,29,31,8,67,71,83,69,34]', '[]', '', '', 1, '', 0, 22, 1, '[4629,4636,4786,8082,8851,18339]', '[24,436,217,8081,3396,18282]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(824, 'vortex_alt_x', 'Vortex of Projection', 'An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it. If the caster targets near their Frostbolt projectiles, it will explode from a number of those projectiles instead, destroying them.', 473, 'Art/2DArt/SkillIcons/FrostVortex.dds', '[1,22]', '[1,6,7,13,14,15,21,29,31,8,67,71,83,69,34]', '[]', '', '', 1, '', 0, 22, 1, '[4629,4636,4786,8082,8851,18339]', '[24,436,217,8081,3396,18282]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 823, ''),
(825, 'vortex_alt_y', '[DNT] FrostBoltNovaAltY', 'An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it.', 473, 'Art/2DArt/SkillIcons/FrostVortex.dds', '[1,22]', '[1,6,7,13,14,15,21,29,31,8,67,71,83,69,34]', '[]', '', '', 1, '', 0, 22, 1, '[4629,4636,4786,8082,8851,18339]', '[24,436,217,8081,3396,18282]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 823, ''),
(826, 'blight', 'Blight', 'Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren''t already debuffed by Blight are also hindered for a shorter secondary duration, slowing their movement. Continued channelling adds layers of damage to the debuff, each with their own duration.', 474, 'Art/2DArt/SkillIcons/Blight.dds', '[1,11]', '[1,41,7,14,47,8,34,48,71]', '[]', '', '', 1, '', 0, 22, 1, '[4141,4451,4422,6398,15784]', '[24,436,5248,8067,218]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(827, 'blight_alt_x', 'Blight of Contagion', 'Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren''t already debuffed by Blight are also hindered for a shorter secondary duration, slowing their movement. Continued channelling adds layers of damage to the debuff, each with their own duration. The damaging debuff is spread by Contagion.', 474, 'Art/2DArt/SkillIcons/Blight.dds', '[1,11]', '[1,41,7,14,47,8,34,48,71]', '[]', '', '', 1, '', 0, 22, 1, '[4141,4451,4422,6398,15784]', '[24,436,5248,8067,218]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 826, ''),
(828, 'blight_alt_y', 'Blight of Atrophy', 'Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren''t already debuffed by Blight are also hindered for a longer secondary duration, slowing their movement and reducing their life regeneration rate. Continued channelling adds layers of damage to the debuff, each with their own duration.', 474, 'Art/2DArt/SkillIcons/Blight.dds', '[1,11]', '[1,41,7,14,47,8,34,48,71]', '[]', '', '', 1, '', 0, 22, 1, '[4141,4451,4422,6398,15784]', '[24,436,5248,8067,218]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 826, ''),
(829, 'vaal_blight', 'Vaal Blight', 'Apply a powerful debuff to enemies around you which deals chaos damage over time. Then applies two additional layers in a larger area, growing greatly in size each time. Enemies are also substantially hindered for a shorter secondary duration, slowing their movement.', 475, 'Art/2DArt/SkillIcons/Blight.dds', '[4]', '[1,41,7,14,8,34,48,37,71,83,21]', '[]', '', '', 1, 'VaalBlight', 1, 22, 1, '[4141,4451,4422,6398,15784]', '[24,436,5248,8067,218]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
