(839, 'blade_flurry', 'Blade Flurry', 'Repeatedly hit enemies in a circle in front of you while channelling, dealing damage to and around the enemy. The damage is continually boosted while channelling. You unleash an additional hit for each stage reached once the channelling ends. Requires a Dagger, Claw or One-Handed Sword.', 482, 'Art/2DArt/SkillIcons/ChargedAttack.dds', '[1,18,17]', '[0,7,47,19]', '[6,7,9,10,56]', '', '', 1, 'ChargedAttack', 0, 22, 1, '[4631,4638,18105,18106,18744]', '[24,436,18107,18108,18745]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(840, 'blade_flurry_alt_x', 'Blade Flurry of Incision', 'Repeatedly hit enemies in a circle in front of you while channelling, dealing damage to and around the enemy. The critical strike chance is continually boosted while channelling. You unleash an additional hit for each stage reached once the channelling ends. Requires a Dagger, Claw or One-Handed Sword.', 482, 'Art/2DArt/SkillIcons/ChargedAttack.dds', '[1,18,17]', '[0,7,47,19]', '[6,7,9,10,56]', '', '', 1, 'ChargedAttack', 0, 22, 1, '[4631,4638,18105,18106,18744]', '[24,436,18107,18108,18745]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 839, ''),
(841, 'blade_flurry_alt_y', '[DNT] ChargedAttackAltY', 'Repeatedly hit enemies in a circle in front of you while channelling, dealing damage to and around the enemy. The damage is continually boosted while channelling. You unleash an additional hit for each stage reached once the channelling ends. Requires a Dagger, Claw or One-Handed Sword.', 482, 'Art/2DArt/SkillIcons/ChargedAttack.dds', '[1,18,17]', '[0,7,47,19]', '[6,7,9,10,56]', '', '', 1, 'ChargedAttack', 0, 22, 1, '[4631,4638,18105,18106,18744]', '[24,436,18107,18108,18745]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 839, ''),
(842, 'vaal_blade_flurry', 'Vaal Blade Flurry', 'Channel to create an expanding circle area around you that blinds enemies within it. When you stop channelling, deals damage in a smaller area around each enemy in the circle. Requires a Dagger, Claw or One-Handed Sword.', 483, 'Art/2DArt/SkillIcons/ChargedAttack.dds', '[1,18,17]', '[0,7,47,19,37,89,121]', '[6,7,9,10,56]', '', '', 1, 'ChargedAttack', 0, 22, 1, '[4631,4638,18105,18106,18744]', '[24,436,18107,18108,18745]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(843, 'abberaths_fury_explosion', 'Abberath''s Fury', 'While you run, this skill creates a small explosion with each step, dealing fire damage in an area around you.', 484, 'Art/2DArt/SkillIcons/AbberathsHooves.dds', '[4]', '[7,31,36,1,6,49,28,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
