(870, 'ancestral_warchief', 'Ancestral Warchief', 'Summons an Ancestor Totem which attacks enemies with a powerful slam while you''re near it. Being near it grants you more melee damage. Requires a Melee Weapon or Unarmed.', 504, 'Art/2DArt/SkillIcons/SlamAncestorTotem.dds', '[1,2,20]', '[0,25,19,7,91,23]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 15, 1, '[4632,4635]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(871, 'ancestral_warchief_alt_x', '[DNT] AncestralWarchiefAltX', 'Summons an Ancestor Totem which attacks enemies with a powerful slam while you''re near it. Being near it grants you more melee damage. Requires a Melee Weapon or Unarmed.', 504, 'Art/2DArt/SkillIcons/SlamAncestorTotem.dds', '[1,2,20]', '[0,25,19,7,91,23]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 15, 1, '[4632,4635]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 870, ''),
(872, 'ancestral_warchief_alt_y', '[DNT] AncestralWarchiefAltY', 'Summons an Ancestor Totem which attacks enemies with a powerful slam while you''re near it. Being near it grants you more melee damage. Requires a Melee Weapon or Unarmed.', 504, 'Art/2DArt/SkillIcons/SlamAncestorTotem.dds', '[1,2,20]', '[0,25,19,7,91,23]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 15, 1, '[4632,4635]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 870, ''),
(873, 'vaal_ancestral_warchief', 'Vaal Ancestral Warchief', 'Summons an Ancestor Totem which attacks enemies with a powerful cascading slam while you''re near it. If the enemies are far away, it will leap toward them as it slams. Being near it grants you more melee damage. Requires a Melee Weapon or Unarmed.', 505, 'Art/2DArt/SkillIcons/SlamAncestorTotem.dds', '[1,2,20]', '[0,25,19,7,37,121]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 16, 1, '[4632,4635]', '[24,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(874, 'lacerate', 'Lacerate', 'Slashes twice, releasing waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. The slashes will have a chance to inflict bleeding in Blood Stance, or have a wider angle in Sand Stance. Can be used with Axes and Swords. You are in Blood Stance by default.', 506, 'Art/2DArt/SkillIcons/BloodLacerate.dds', '[1,2]', '[0,7,23,19,27]', '[9,15,11,16,10]', '', '', 1, 'DoubleSlash', 0, 22, 1, '[4630,4637,4639,8112,8113,18079]', '[24,556,436,8025,8026,18078]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(875, 'lacerate_alt_x', 'Lacerate of Butchering', 'Slashes twice, releasing wide waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. Requires a Two Handed Axe or Two Handed Sword.', 506, 'Art/2DArt/SkillIcons/SandLacerate.dds', '[1,2]', '[0,7,23,19]', '[15,16]', '', '', 1, 'DoubleSlash', 0, 22, 1, '[4630,4637,4639,8112,8113,18079]', '[24,556,436,8025,8026,18078]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 874, ''),
(876, 'lacerate_alt_y', 'Lacerate of Haemorrhage', 'Slashes twice, releasing waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. Requires a One Handed Axe or One Handed Sword.', 506, 'Art/2DArt/SkillIcons/BloodLacerate.dds', '[1,2]', '[0,7,23,19,27]', '[9,11,10]', '', '', 1, 'DoubleSlash', 0, 22, 1, '[4630,4637,4639,8112,8113,18079]', '[24,556,436,8025,8026,18078]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 874, ''),
