(878, 'elemental_projectiles', 'Elemental Projectiles', 'Fires a burst of three piercing projectiles in an arc in front of you.', 508, 'Art/2DArt/SkillIcons/IllusionaryWolf.dds', '[1,2]', '[1,6,13,15,10,14,7,71]', '[]', '', '', 1, 'ElementalProjectiles', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
