(881, 'dark_pact', 'Dark Bargain', 'This spell removes some life from one of your Skeleton minions near you or the targeted location to deal chaos damage in an area around it. This effect will chain to your other nearby skeletons. If you have no skeletons near you or the targeted location, it will sacrifice your own life to deal damage instead.', 511, 'Art/2DArt/SkillIcons/SkeletalChains.dds', '[1,3,22]', '[1,6,15,14,7,13,31,21,18,41,5,69,71,83]', '[]', '', '', 1, 'SkeletalChains', 0, 22, 1, '[6473,6474,6589,18226]', '[218,436,24,18137]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DarkPactTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(882, 'dark_pact_alt_x', 'Dark Bargain of Trarthus', 'This spell deals chaos damage in an area around you. Casting this spell will cause you to gain Ruin. If this spell inflicts your seventh Ruin, it will sacrifice a large portion of your life to deal extra chaos damage based on the amount sacrificed, and remove all Ruin from you.', 511, 'Art/2DArt/SkillIcons/SkeletalChains.dds', '[4]', '[1,6,15,14,7,13,31,21,41,69,71,83]', '[]', '', '', 1, 'SkeletalChains', 0, 22, 1, '[6473,6474,6589,18226]', '[218,436,24,18137]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DarkPactTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 881, ''),
(883, 'dark_pact_alt_y', '[DNT] DarkPactAltY', 'This spell removes some life from one of your Skeleton minions near you or the targeted location to deal chaos damage in an area around it. This effect will chain to your other nearby skeletons. If you have no skeletons near you or the targeted location, it will sacrifice your own life to deal damage instead.', 511, 'Art/2DArt/SkillIcons/SkeletalChains.dds', '[1,3,22]', '[1,6,15,14,7,13,31,21,18,41,5,69,71,83]', '[]', '', '', 1, 'SkeletalChains', 0, 22, 1, '[6473,6474,6589,18226]', '[218,436,24,18137]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/DarkPactTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 881, ''),
(884, 'monster_aura_increased_damage_taken', 'Increased Damage Taken Aura', 'Enemies affected by this aura will take increased damage from all sources', 512, 'Art/2DArt/SkillIcons/IllusionaryWolf.dds', '[4]', '[38,7,1,71,11]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
