(900, 'elemental_warding', 'Elemental Warding', 'Fires projectiles in all directions, converting all their physical damage to a random element, and grants a buff which makes you unaffected by curses for a duration. Removes curses on you when used.', 528, 'Art/2DArt/SkillIcons/CurseNova.dds', '[4]', '[1,6,31,36,49,2,56,28,29,30,8,4,27]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
