(980, 'blade_vortex', 'Blade Vortex', 'This spell creates ethereal blades which orbit in an area around you, dealing damage every 0.6 seconds to all enemies in their radius. As more blades are added, the damage becomes greater and more frequent.', 603, 'Art/2DArt/SkillIcons/SpinningEtherealBlades.dds', '[4]', '[1,6,7,8,14,21,31,22,69,71,27]', '[]', '', '', 1, 'BladeVortex', 0, 22, 1, '[4133,4419,4445,8087,18538,18539]', '[24,217,436,8088,13173,14166]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/BladeVortexTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(981, 'blade_vortex_alt_x', 'Blade Vortex of the Scythe', 'This spell creates a swarm of ethereal blades which briefly orbit in an area around you, dealing damage every 0.6 seconds to all enemies in their radius.', 603, 'Art/2DArt/SkillIcons/SpinningEtherealBlades.dds', '[4]', '[1,6,7,8,14,21,31,22,69,71,27]', '[]', '', '', 1, 'BladeVortex', 0, 22, 1, '[4133,4419,4445,8087,18538,18539]', '[24,217,436,8088,13173,14166]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/BladeVortexTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 980, ''),
