(983, 'spectral_shield_throw', 'Spectral Shield Throw', 'Throws a spectral copy of your shield as a projectile which cannot pierce, and deals off-hand damage augmented by the defences of the shield. When it collides with something it will shatter, launching a number of smaller shards as projectiles in all directions. Modifiers that cause additional projectiles to be fired will add more shards, not more copies of the shield.', 604, 'Art/2DArt/SkillIcons/ThrownShield.dds', '[2,1]', '[0,40,2,56,59,27]', '[26]', '', '', 1, 'ThrownShield', 0, 22, 1, '[7834,7835,7836,9965,9968,18219,18220,18221,18257]', '[24,177,175,174,9969,18133,18134,1107,18132]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(984, 'spectral_shield_throw_alt_x', 'Spectral Shield Throw of Shattering', 'Throws a spectral copy of your shield as a projectile which cannot pierce, and deals off-hand damage augmented by the evasion of the shield. When it collides with something it will shatter, launching a number of smaller shards as projectiles in all directions. Modifiers that cause additional projectiles to be fired will add more shards, not more copies of the shield.', 604, 'Art/2DArt/SkillIcons/ThrownShield.dds', '[2,1]', '[0,40,2,56,59,29]', '[26]', '', '', 1, 'ThrownShield', 0, 22, 1, '[7834,7835,7836,9965,9968,18219,18220,18221,18257]', '[24,177,175,174,9969,18133,18134,1107,18132]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 983, ''),
(985, 'spectral_shield_throw_alt_y', 'Spectral Shield Throw of Trarthus', 'Throws a spectral copy of your shield as a piercing projectile which deals off-hand damage augmented by the defences of the shield. When it reaches the targeted location it will hover in place, repeatedly firing a number of smaller shards as projectiles in all directions. The rate at which it releases shards will increase until all shards have been fired. Modifiers that cause additional projectiles to be fired will add more shards, not more copies of the shield.', 604, 'Art/2DArt/SkillIcons/ThrownShield.dds', '[2,1]', '[0,40,2,56,59,27]', '[26]', '', '', 1, 'ThrownShield', 0, 22, 1, '[7834,7835,7836,9965,9968,18219,18220,18221,18257]', '[24,177,175,174,9969,18133,18134,1107,18132]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 983, ''),
