(1502, 'chain_hook', 'Chain Hook', 'When used at range, throws out a chain, pulling you to the enemy hit dealing damage in an area behind them. When close to the enemy, just causes the area damage directly. Requires a One Handed Mace, Sceptre, Sword or Axe.', 993, 'Art/2DArt/SkillIcons/ChainStrike.dds', '[2,1]', '[0,7,6,33,19,23]', '[9,10,11,12,32]', '', '', 1, '', 0, 22, 1, '[10039,18214]', '[24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1503, 'chain_hook_alt_x', 'Chain Hook of Angling', 'Cast your fishing rod towards a number of enemies in front of you. Non-unique enemies far away from you are pulled towards you.', 1101, 'Art/2DArt/SkillIcons/ChainStrike.dds', '[2,1]', '[0,6,19,23]', '[37]', '', '', 1, '', 0, 22, 1, '[10039,18214]', '[24,18129]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1502, ''),
(1504, 'chain_hook_alt_y', 'Chain Hook of Trarthus', 'Throws chains ahead of you, attaching them to targets hit. Enemies chained to you will grant rage when hit. When chains are broken, they snap and deal attack damage in an area around the target they were attached to. Requires a One Handed Mace, Sceptre, Sword or Axe.', 993, 'Art/2DArt/SkillIcons/ChainStrike.dds', '[2,1]', '[0,7,6,19,23]', '[9,10,11,12,32]', '', '', 1, '', 0, 22, 1, '[10039,18214]', '[24,18129]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1502, ''),
