(1506, 'blitz', '[UNUSED] Blitz (NOT CURRENTLY USED)', '[UNUSED] Swing twice, gaining rage with each hit. Every 10 rage, perform a large area of effect attack. At 50 rage, perform an even larger attack, and lose 10 rage.', 995, 'Art/2DArt/BuffIcons/TRexDebuff.dds', '[1,2]', '[0,20,23,19,27]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 0, 'Blitz', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
