(1510, 'frostblink', 'Frostblink', 'Teleport to a location, damaging enemies and leaving Chilled ground in an area at both ends of the teleport. Shares a cooldown with other Blink skills.', 998, 'Art/2DArt/SkillIcons/Frostblink.dds', '[2,1,22]', '[1,33,8,31,29,67,78,79,7,31,6,14,13,15,63,85,89]', '[]', '', '', 1, 'IceDash', 0, 22, 1, '[10034,10499,10035]', '[3396,217,11855]', '[]', 1, 1, '[]', 8, 6, 0, 'Metadata/Monsters/Totems/FrostblinkTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1511, 'frostblink_alt_x', 'Frostblink of Wintry Blast', 'Teleport to a location, damaging enemies in an area at both ends of the teleport. Deals higher damage to chilled enemies, then removes chill from them. Cannot be supported by Unleash.', 998, 'Art/2DArt/SkillIcons/Frostblink.dds', '[2,1,22]', '[1,33,31,29,78,7,31,6,14,13,15,21,109,71]', '[]', '', '', 1, 'IceDash', 0, 22, 1, '[10034,10499,10035]', '[3396,217,11855]', '[]', 1, 1, '[]', 8, 6, 0, 'Metadata/Monsters/Totems/FrostblinkTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1510, ''),
