(1513, 'flesh_and_stone', 'Flesh and Stone', 'Buffs you, and affects nearby enemies with an aura, differently depending on your stance. Both stances are more impactful against enemies closer to you. Using the skill again alternates between Blood Stance and Sand Stance.', 999, 'Art/2DArt/SkillIcons/SandArmour.dds', '[4]', '[1,4,38,52,63,11,7,84,85,89,92,27]', '[]', '', '', 1, '', 0, 22, 1, '[10036,15206,15236,15258,16120]', '[14196,14925,15106,14217,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
