(1524, 'summon_carrion_golem', 'Summon Carrion Golem', 'Summons a Carrion Golem that grants added physical damage for your non-golem minions. The Carrion Golem attacks with a series of slashes that increase in speed and damage, as well as a cascade of bone spikes, and deals more damage for each of your non-golem minions near it.', 1010, 'Art/2DArt/SkillIcons/SummonCarrionGolem.dds', '[1]', '[31,27,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,33,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1525, 'summon_carrion_golem_alt_x', 'Summon Carrion Golem of Hordes', 'Summons a Carrion Golem. The Carrion Golem attacks with a series of slashes that increase in speed and damage, as well as a cascade of bone spikes.', 1010, 'Art/2DArt/SkillIcons/SummonCarrionGolem.dds', '[1]', '[31,27,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,33,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 1524, ''),
(1526, 'summon_carrion_golem_alt_y', 'Summon Carrion Golem of Scavenging', 'Summons a Carrion Golem. The Carrion Golem attacks with a series of slashes that increase in speed and damage, can consume corpses to heal itself and gain the ability to unleash a devastating cascade of bone spikes, and deals more damage for each of your non-golem minions near it.', 1010, 'Art/2DArt/SkillIcons/SummonCarrionGolem.dds', '[1]', '[31,27,15,5,17,21,1,14,13,50,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[5211]', '[3396]', '[0,19,20,33,7,23]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 1524, ''),
