(1541, 'icicle_mine', 'Icicle Mine', 'Throws a mine that fires projectiles around it when detonated. These projectiles quickly dissipate as they travel, before disappearing.', 1021, 'Art/2DArt/SkillIcons/ColdProjectileMine.dds', '[1,2]', '[1,6,2,35,29,11,56,38,7,52,86]', '[]', '', '', 1, '', 0, 22, 1, '[10403,10406,10409,10452,18543,18544]', '[24,1883,95,10453,10271,3026]', '[]', 1, 1, '[]', 5, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1542, 'icicle_mine_alt_x', 'Icicle Mine of Fanning', 'Throws a mine that fires projectiles at enemies when detonated. These projectiles quickly dissipate as they travel, before disappearing.', 1021, 'Art/2DArt/SkillIcons/ColdProjectileMine.dds', '[1,2]', '[1,6,2,35,29,11,56,38,7,52,86]', '[]', '', '', 1, '', 0, 22, 1, '[10403,10406,10409,10452,18543,18544]', '[24,1883,95,10453,10271,3026]', '[]', 1, 1, '[]', 5, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1541, ''),
(1543, 'icicle_mine_alt_y', 'Icicle Mine of Sabotage', 'Throws a mine that fires projectiles around it when detonated. These projectiles quickly dissipate as they travel, before disappearing.', 1021, 'Art/2DArt/SkillIcons/ColdProjectileMine.dds', '[1,2]', '[1,6,2,35,29,11,56,38,7,52,86]', '[]', '', '', 1, '', 0, 22, 1, '[10403,10406,10409,10452,18543,18544]', '[24,1883,95,10453,10271,3026]', '[]', 1, 1, '[]', 5, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1541, ''),
(1544, 'summon_skitterbots', 'Summon Skitterbots', 'Summon a Chilling Skitterbot and a Shocking Skitterbot, which will trigger your traps and detonate your mines. Mines detonated by Skitterbots will re-arm and can then be detonated again. The Skitterbots grant you more trap and mine damage, and cannot be targeted or damaged.', 1022, 'Art/2DArt/SkillIcons/LightningFireSkitterbots.dds', '[4]', '[1,4,63,5,76,116,11,29,30,66,16,7,38,52,86,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[10538,15223,15253]', '[14196,14925,15106]', '[]', 1, 1, '[21468]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1545, 'blight_tower_aura', '[UNUSED] Blight Tower Aura', '', 1023, 'Art/2DArt/SkillIcons/auraresist.dds', '[4]', '[]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
