(1547, 'monster_quick_dodge', '', 'Performs a series of quick teleports towards a targeted location. If using the "Attack in Place" option, the direction is reversed. Shares a cooldown with other Blink skills.', 986, 'Art/2DArt/SkillIcons/QuickDash.dds', '[1]', '[1,33,78,79]', '[]', '', '', 1, '', 0, 22, 1, '[10043]', '[10041]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1548, 'pestilent_strike', 'Pestilent Strike', 'Attacks with your weapon, inflicting a debuff on enemies hit by the strike. If a debuffed enemy dies while poisoned, Pestilent Strike inflicts a secondary chaos damage over time debuff on enemies around them, based on the poisons on the slain enemy. This damage is not affected by your damage modifiers. Requires a Claw or Dagger.', 1025, 'Art/2DArt/SkillIcons/MambaStrike.dds', '[1,2]', '[0,19,20,23,7,8,41]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10531,10532,10533,18234]', '[24,217,436,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1549, 'pestilent_strike_alt_x', '[DNT] PestilentStrikeAltX', 'Attacks with your weapon, inflicting a debuff on enemies hit by the strike. If a debuffed enemy dies while poisoned, Pestilent Strike inflicts a secondary chaos damage over time debuff on enemies around them, based on the poisons on the slain enemy. This damage is not affected by your damage modifiers. Requires a Claw or Dagger.', 1025, 'Art/2DArt/SkillIcons/MambaStrike.dds', '[1,2]', '[0,19,20,23,7,8,41]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10531,10532,10533,18234]', '[24,217,436,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1548, ''),
(1550, 'pestilent_strike_alt_y', '[DNT] PestilentStrikeAltY', 'Attacks with your weapon, inflicting a debuff on enemies hit by the strike. If a debuffed enemy dies while poisoned, Pestilent Strike inflicts a secondary chaos damage over time debuff on enemies around them, based on the poisons on the slain enemy. This damage is not affected by your damage modifiers. Requires a Claw or Dagger.', 1025, 'Art/2DArt/SkillIcons/MambaStrike.dds', '[1,2]', '[0,19,20,23,7,8,41]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10531,10532,10533,18234]', '[24,217,436,3548]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1548, ''),
(1551, 'venom_gyre', 'Venom Gyre', 'Fires a returning projectile that can be caught. Caught projectiles spiral outwards when you use Whirling Blades and do not return. Requires a Dagger or Claw.', 1026, 'Art/2DArt/SkillIcons/SnappingAdder.dds', '[1,2]', '[0,40,2,41,8,56]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10527,10528,18200,18201]', '[24,9911,18121,1108]', '[]', 1, 1, '[10529]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1552, 'venom_gyre_alt_x', '[DNT] VenomGyreAltX', 'Fires a returning projectile that can be caught. Caught projectiles spiral outwards when you use Whirling Blades and do not return. Requires a Dagger or Claw.', 1026, 'Art/2DArt/SkillIcons/SnappingAdder.dds', '[1,2]', '[0,40,2,41,8,56]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10527,10528,18200,18201]', '[24,9911,18121,1108]', '[]', 1, 1, '[10529]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1551, ''),
(1553, 'venom_gyre_alt_y', '[DNT] VenomGyreAltY', 'Fires a returning projectile that can be caught. Caught projectiles spiral outwards when you use Whirling Blades and do not return. Requires a Dagger or Claw.', 1026, 'Art/2DArt/SkillIcons/SnappingAdder.dds', '[1,2]', '[0,40,2,41,8,56]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10527,10528,18200,18201]', '[24,9911,18121,1108]', '[]', 1, 1, '[10529]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1551, ''),
(1554, 'vaal_venom_gyre', 'Vaal Venom Gyre', 'Creates already-caught projectiles without firing them first, both immediately and over a secondary duration. Caught projectiles spiral outwards when you use Whirling Blades and do not return. Requires a Dagger or Claw.', 1026, 'Art/2DArt/SkillIcons/SnappingAdder.dds', '[4]', '[0,40,2,41,8,112,37]', '[6,7,56]', '', '', 1, '', 0, 22, 1, '[10527,10528,18200,18201]', '[24,9911,18121,1108]', '[]', 1, 1, '[10529]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1555, 'create_fungal_ground_on_kill', 'Contaminate', 'Creates a patch of Fungal Ground at the targeted location.', 1027, 'Art/2DArt/BuffIcons/FungalGroundBuff.dds', '[1,2]', '[1,7,8,31,49,89,36]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
