(1557, 'shrapnel_ballista', 'Shrapnel Ballista', 'Summons a ballista totem that fires multiple arrows with extreme force, breaking them apart into shrapnel. Enemies can be hit by multiple arrows from the same attack. Requires a Bow.', 1029, 'Art/2DArt/SkillIcons/ShotgunTotemSkillIcon.dds', '[1,2,20]', '[0,2,56,40,13,15,25,82,113]', '[13]', '', '', 1, '', 0, 18, 1, '[10828,10829,10830,18291,18343,18345,12638]', '[175,177,6360,70,18288,18290,20449]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1558, 'shrapnel_ballista_alt_x', 'Shrapnel Ballista of Steel', 'Summons a ballista totem that consumes your Steel Shards to fire multiple arrows with extreme force, breaking them apart into shrapnel. Enemies can be hit by multiple arrows from the same attack. Requires a Bow. Steel Shards are gained with the Call of Steel Skill.', 1029, 'Art/2DArt/SkillIcons/ShotgunTotemSkillIcon.dds', '[1,2,20]', '[0,2,56,40,13,15,25,82,113,27]', '[13]', '', '', 1, '', 0, 18, 1, '[10828,10829,10830,18291,18343,18345,12638]', '[175,177,6360,70,18288,18290,20449]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1557, ''),
(1559, 'shrapnel_ballista_alt_y', '[DNT] ShrapnelBallistaAltY', 'Summons a ballista totem that fires multiple arrows with extreme force, breaking them apart into shrapnel. Enemies can be hit by multiple arrows from the same attack. Requires a Bow.', 1029, 'Art/2DArt/SkillIcons/ShotgunTotemSkillIcon.dds', '[1,2,20]', '[0,2,56,40,13,15,25,82,113]', '[13]', '', '', 1, '', 0, 18, 1, '[10828,10829,10830,18291,18343,18345,12638]', '[175,177,6360,70,18288,18290,20449]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1557, ''),
(1560, 'ensnaring_arrow', 'Ensnaring Arrow', 'Fires an arrow that remains in the ground behind its final target, tethering that enemy to it. Ensnared enemies have less movement speed while trying to break the snare. The snare will break if they leave the area of effect.', 1030, 'Art/2DArt/SkillIcons/EnsnaringArrow.dds', '[1,2]', '[0,40,57,2,56,13,15,14,31,7]', '[13]', '', '', 1, '', 0, 22, 1, '[10893,10892,18233]', '[436,4602,11127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1561, 'ensnaring_arrow_alt_x', '[DNT] EnsnaringArrowAltX', 'Fires an arrow that remains in the ground behind its final target, tethering that enemy to it. Ensnared enemies have less movement speed while trying to break the snare. The snare will break if they leave the area of effect.', 1030, 'Art/2DArt/SkillIcons/EnsnaringArrow.dds', '[1,2]', '[0,40,57,2,56,13,15,14,31,7]', '[13]', '', '', 1, '', 0, 22, 1, '[10893,10892,18233]', '[436,4602,11127]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1560, ''),
