(1563, 'artillery_ballista', 'Artillery Ballista', 'Summons a ballista totem that propels a sequence of fiery arrows into the air. The arrows impact the ground in a line, each dealing area damage to enemies around it. Requires a Bow.', 1031, 'Art/2DArt/SkillIcons/MortarTotemSkillIcon.dds', '[1,2,20]', '[0,40,13,15,25,7,28,61,10,82,113]', '[13]', '', '', 1, '', 0, 19, 1, '[10826,10827,18203,18205]', '[595,175,6120,18122]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1564, 'artillery_ballista_alt_x', 'Artillery Ballista of Cross Strafe', 'Summons a ballista totem that propels a sequence of fiery arrows into the air. The arrows impact the ground in two perpendicular lines, each dealing area damage to enemies around it. Requires a Bow.', 1031, 'Art/2DArt/SkillIcons/MortarTotemSkillIcon.dds', '[1,2,20]', '[0,40,13,15,25,7,28,61,10,82,113]', '[13]', '', '', 1, '', 0, 19, 1, '[10826,10827,18203,18205]', '[595,175,6120,18122]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1563, ''),
(1565, 'artillery_ballista_alt_y', 'Artillery Ballista of Focus Fire', 'Summons a ballista totem that propels a number of fiery arrows into the air, each targeting a specific enemy. Arrows deal area damage to enemies around it on landing. Requires a Bow.', 1031, 'Art/2DArt/SkillIcons/MortarTotemSkillIcon.dds', '[1,2,20]', '[0,40,13,15,25,7,28,61,10,82,113]', '[13]', '', '', 1, '', 0, 19, 1, '[10826,10827,18203,18205]', '[595,175,6120,18122]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1563, ''),
