(1572, 'orion_circle_maze_blast', '', '', 1037, '', '[1,2]', '[1,7,6,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1573, 'unique_mirage_warriors', 'Reflection', 'When you attack with The Saviour and deal a critical strike, this skill can summon a Mirage Saviour. Summoned Mirage Saviours will fight for you using whichever of your attack skills you dealt the critical strike with that caused them to be summoned. Mirage Saviours will not be resummoned using the same skills if you already have the maximum number of them.', 1038, 'Art/2DArt/SkillIcons/ReflectionSkill.dds', '[4]', '[8]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[10845]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1574, 'orion_beam_bomb', '', '', 1039, '', '[1,2]', '[1,7,6,71,30,27,41]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1575, 'arcane_cloak', 'Arcane Cloak', 'Spends a portion of your mana to grant a buff that takes some of the damage from hits for you until depleted. The buff grants added lightning damage based on the amount of mana spent by this skill. Shares a cooldown with other Guard skills.', 1040, 'Art/2DArt/SkillIcons/ArcaneCloak.dds', '[4]', '[1,4,63,8,31,77,30,89,103]', '[]', '', '', 1, '', 0, 22, 1, '[11016,22126]', '[9521,9521]', '[]', 1, 1, '[11897,11018]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1576, 'projectile_portal', '[UNUSED] Projectile Portal', '[UNUSED] Places a projectile portal. With two portals active, any of your projectiles that impact one portal will be teleported to the other portal, retaining their direction and speed. In layman''s terms, speedy thing goes in, speedy thing comes out.', 1041, 'Art/2DArt/SkillIcons/townportal.dds', '[1]', '[1,8,63,31,14,13,15,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1577, 'stormbind', 'Stormbind', 'Channel to spread runes on the ground in a growing pattern. The runes fade away after a duration, or will be immediately removed and deal damage in a circular area when detonated by Rune Blast. Enemies standing on the runes are Hindered, reducing their movement speed.', 1042, 'Art/2DArt/SkillIcons/StormbindRune.dds', '[1]', '[1,7,6,71,47,30,14,8,103]', '[]', '', '', 1, '', 0, 22, 1, '[11940,11941,18247,18248]', '[436,24,1492,2111]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1578, 'stormbind_alt_x', 'Stormbind of Teleportation', 'Channel to spread runes on the ground in a growing pattern. The runes fade away after a duration, or will be immediately removed and deal damage in a circular area when detonated by Rune Blast. Enemies standing on the runes are Hindered, reducing their movement speed.', 1042, 'Art/2DArt/SkillIcons/StormbindRune.dds', '[1]', '[1,7,6,71,47,30,14,8,103]', '[]', '', '', 1, '', 0, 22, 1, '[11940,11941,18247,18248]', '[436,24,1492,2111]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1577, ''),
(1579, 'stormbind_alt_y', '[DNT] StormBindAltY', 'Channel to spread runes on the ground in a growing pattern. The runes fade away after a duration, or will be immediately removed and deal damage in a circular area when detonated by Rune Blast. Enemies standing on the runes are Hindered, reducing their movement speed.', 1042, 'Art/2DArt/SkillIcons/StormbindRune.dds', '[1]', '[1,7,6,71,47,30,14,8,103]', '[]', '', '', 1, '', 0, 22, 1, '[11940,11941,18247,18248]', '[436,24,1492,2111]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1577, ''),
(1580, 'rune_blast', 'Rune Blast', 'Channel to improve runes placed by Stormbind based on the mana you spend channelling this skill. Release to detonate the targeted rune, which will cause other runes to detonate in a chain reaction.', 1043, 'Art/2DArt/SkillIcons/StormbindChannelling.dds', '[1]', '[1,47,103]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1581, 'rune_blast_alt_x', 'Rune Blast of Teleportation', 'Channel to improve runes placed by Stormbind based on the mana you spend channelling this skill. Release to detonate the targeted rune, which will cause other runes to detonate in a chain reaction. Detonation can teleport you to the targeted Rune.', 1043, 'Art/2DArt/SkillIcons/StormbindChannelling.dds', '[1]', '[1,47,103,33,78,79]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1582, 'kinetic_bolt', 'Kinetic Bolt', 'Fire a projectile from your wand that changes direction in a zig-zag pattern at regular intervals or when hitting enemies. Each time it changes direction, a secondary projectile breaks off, flying in the direction it changed away from.', 1044, 'Art/2DArt/SkillIcons/ZigZagWand.dds', '[1,2,20]', '[0,2,56,13,15,14,40,31,126]', '[8]', '', '', 1, 'ZigZagWand', 0, 22, 1, '[11935,11936,18244,18245]', '[177,70,108,3889]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1583, 'kinetic_bolt_alt_x', 'Kinetic Bolt of Fragmentation', 'Fire a projectile from your wand that changes direction in a zig-zag pattern at regular intervals or when hitting enemies. Each time it changes direction, a secondary projectile breaks off, flying in the direction it changed away from. Multiple of these projectiles can hit the same target.', 1044, 'Art/2DArt/SkillIcons/ZigZagWand.dds', '[1,2,20]', '[0,2,56,13,15,14,40,31,126]', '[8]', '', '', 1, 'ZigZagWand', 0, 22, 1, '[11935,11936,18244,18245]', '[177,70,108,3889]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1582, ''),
(1584, 'kinetic_bolt_alt_y', '[DNT] KineticBoltAltY', 'Fire a projectile from your wand that changes direction in a zig-zag pattern at regular intervals or when hitting enemies. Each time it changes direction, a secondary projectile breaks off, flying in the direction it changed away from.', 1044, 'Art/2DArt/SkillIcons/ZigZagWand.dds', '[1,2,20]', '[0,2,56,13,15,14,40,31,126]', '[8]', '', '', 1, 'ZigZagWand', 0, 22, 1, '[11935,11936,18244,18245]', '[177,70,108,3889]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1582, ''),
(1585, 'blade_blast', 'Blade Blast', 'Deals spell damage in a targeted area. Each time this spell deals damage,  it will detonate any of your Lingering Blades it touches, dealing damage again in an area around them. Up to 50 Blades can be detonated this way.', 1045, 'Art/2DArt/SkillIcons/BladeBurst.dds', '[1,22]', '[1,7,13,15,14,6,31,21,55,69,71,27]', '[]', '', '', 1, 'BladeBurst', 0, 22, 1, '[11937,11939,18538,18539]', '[436,24,13173,14166]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/BladeBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1586, 'blade_blast_alt_x', 'Blade Blast of Unloading', 'Deals spell damage in an area around you. If you have Blade Vortex blades orbiting you, it will detonate each of them in turn, dealing damage again in an area around you for each one.', 1045, 'Art/2DArt/SkillIcons/BladeBurst.dds', '[4]', '[1,7,13,15,14,6,31,21,69,71,27,83]', '[]', '', '', 1, 'BladeBurst', 1, 22, 1, '[11937,11939,18538,18539]', '[436,24,13173,14166]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/BladeBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1585, ''),
(1587, 'blade_blast_alt_y', 'Blade Blast of Dagger Detonation', 'Deals spell damage in an area around you. Your equipped daggers add to this damage.', 1045, 'Art/2DArt/SkillIcons/BladeBurst.dds', '[4]', '[1,7,13,15,14,6,31,21,69,71,27,83]', '[]', '', '', 1, 'BladeBurst', 1, 22, 1, '[11937,11939,18538,18539]', '[436,24,13173,14166]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/BladeBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1585, ''),
(1588, 'blood_whirl', '[UNUSED] Blood Whirl', '[UNUSED] Whily Twirly ', 1046, 'Art/2DArt/SkillIcons/cyclone.dds', '[1,23]', '[0,7,19,33,47,27,89]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, 'BloodWhirl', 0, 22, 1, '[11026]', '[9521]', '[]', 1, 1, '[]', 8, 0, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1589, 'affliction_boss_final_grow_beam', '', '', 1047, '', '[1,2]', '[1,7,8,28,31]', '[]', '', '', 1, 'AfflictionDemonBeam', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1590, 'affliction_split', '', '', 1048, '', '[2]', '[]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1591, 'channelled_snipe', 'Snipe', 'Channel to charge up your bow, gaining stages. Release to trigger one supported bow skill for each stage gained. If there are no supported skills, but at least one stage was gained, this skill will fire its own arrow instead. Cannot be used by Totems.', 1049, 'Art/2DArt/SkillIcons/SnipeSkillIcon.dds', '[18,11,22]', '[0,40,57,2,56,47,27]', '[13]', '', '', 1, '', 0, 22, 1, '[18649,18650]', '[70,6199]', '[]', 1, 1, '[11103]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1592, 'napalm_arrows', 'Conflagration', 'Fire arrows into the air that rain down around the targeted area, dealing area damage on impact and leaving the arrows stuck in the ground for a duration. If you move close to a stuck arrow, it will explode, dealing area damage and applying a fire damage over time debuff, as well as causing other stuck arrows in range to also explode.', 1310, 'Art/2DArt/SkillIcons/Conflagration.dds', '[1,2,20]', '[0,40,28,57,7,10,61,14,13,15,31,88,8,34]', '[13]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1593, 'kinetic_rain', 'Kinetic Rain', 'Swing your wand to cause a number of projectiles to rain down within a large area in front of you, directly targeting the locations of enemies in the area. The locations where each projectile will land are shown with markers before they fall. Each projectile explodes when hitting the ground, dealing area damage and triggering Kinetic Anomaly. Cannot be used by Totems, Traps, or Mines.', 1313, 'Art/2DArt/SkillIcons/KineticRain.dds', '[1,2]', '[0,7,2,126,40,88]', '[8]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1594, 'kinetic_rain_kinetic_instability', 'Kinetic Anomaly', 'Gathers kinetic energy into an anomaly at the targeted location, which will explode when enemies are near it, dealing your wand''s damage in an area. The anomaly will dissipate after a duration.', 1314, 'Art/2DArt/SkillIcons/Windstorm.dds', '[1,2]', '[0,7,31,8,126,49,36]', '[8]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1595, 'kinetic_rain_alt_x', 'Kinetic Rain of Impact', 'Swing your wand to cause a number of projectiles to rain down within a large area in front of you, directly targeting the locations of enemies in the area. The locations where each projectile will land are shown with markers before they fall. Each projectile explodes when hitting the ground, dealing area damage.', 1313, 'Art/2DArt/SkillIcons/KineticRain.dds', '[1,2]', '[0,7,2,13,15,31,14,126,40,88]', '[8]', '', '', 1, '', 0, 19, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1596, 'kinetic_shell', 'Somatic Shell', 'Fire a damaging projectile from your wand which aims itself towards an enemy and applies a shell to the first enemy struck. Damage from hits against that target is taken from the shell first. If fully depleted, the shell will explode, dealing area damage and firing a projectile at another target to apply a new shell to it. If multiple projectiles are fired by an exploding shell, only the first one to hit a target can apply a shell.', 1315, 'Art/2DArt/SkillIcons/KineticShell.dds', '[2,1]', '[8,27,13,15,14,56,0,126,7,2,40]', '[8]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1597, 'thunderstorm', 'Thunderstorm', 'Fires an arrow into the air to land at a targeted location. On impact, deals area damage and creates a thunderstorm which blinds enemies within it. Entering the thunderstorm will cause it to gain stages, and leaving it will cause it to dissipate. Leaving the storm while it is at maximum stages will cause it to explode, dealing damage and triggering Thunderburst. You must use this skill yourself, it cannot be used by Totems, Traps, Mines, or other objects that use skills for you.', 1309, 'Art/2DArt/SkillIcons/Windstorm.dds', '[1,2]', '[0,7,40,8,30,88,10,112]', '[13]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1598, 'thunderstorm_thunderburst', 'Thunderburst', 'Fires projectiles from the targeted location that move randomly and damage enemies they pierce through. They explode after a duration, dealing area damage.', 1311, 'Art/2DArt/SkillIcons/Windstorm.dds', '[1,2]', '[0,2,31,8,40,49,36,30,81,7]', '[13]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1599, 'kinetic_fusillade', 'Kinetic Fusillade', 'Wave your wand to create a hovering kinetic projectile. After a short duration, the projectile is fired at an enemy, dealing area damage on impact and chaining to further targets. Using this attack again will reset the duration for all hovering projectiles. Multiple projectiles fired in sequence will attempt to target different enemies. Cannot be directly used by traps or mines.', 1312, 'Art/2DArt/SkillIcons/KineticFullisade.dds', '[1,2]', '[0,31,2,40,126,8,14,56,7]', '[8]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/KineticFusilladeTotem.ais', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1600, 'kinetic_fusillade_alt_x', 'Kinetic Fusillade of Detonation', 'Wave your wand to create multiple hovering kinetic projectiles. After a short duration, the projectiles explode, dealing area damage. Using this attack again will reset the duration for all hovering projectiles. Cannot be directly used by traps or mines.', 1312, 'Art/2DArt/SkillIcons/KineticFullisade.dds', '[1,2]', '[0,31,2,40,126,8,14,56,7]', '[8]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, 'Metadata/Monsters/Totems/KineticFusilladeTotem.ais', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1599, ''),
(1601, 'holy_hammers', 'Holy Hammers', 'Slam the ground, calling down a Holy Hammer from above. On hitting an enemy, another Hammer will cascade forward, repeating if further enemies are hit, up to a cap. A Power Charge can be expended to call down additional Hammers to either side of the initial slam. Requires a Mace, Sceptre or Staff.', 1323, 'Art/2DArt/SkillIcons/HolyHammers.dds', '[1,2]', '[0,91,19,7,30,14,23]', '[14,57,12,17,32]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1602, 'holy_hammers_alt_x', 'Holy Hammers of Spirals', 'Slam the ground, consuming all Power Charges and calling down a cascade of holy hammers from above in an outward spiral. Further hammers are called down for each Power Charge consumed. Requires a Mace, Sceptre or Staff.', 1323, 'Art/2DArt/SkillIcons/HolyHammers.dds', '[1,2]', '[0,91,19,7,30,14,23]', '[14,57,12,17,32]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1601, ''),
(1603, 'shield_of_light', 'Shield of Light', 'Retaliate against a blocked hit with a sweep of your Shield, unleashing a wave of light in a cone in front of you. Additional waves will also emanate from allies in a radius around the first target struck, towards that target.', 1324, 'Art/2DArt/SkillIcons/ShieldofLight.dds', '[1,2,24]', '[0,19,7,6,30,27,89,120,9]', '[26]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1604, 'holy_strike', 'Holy Strike', 'Infuse your weapon with holy energy and swing. Successfully hitting an enemy will summon forth a copy of your Main Hand weapon as a Holy Armament. These Holy Armaments are undamageable minions, and will attack the enemies you target with Holy Strike. Requires a Mace, Sceptre or Staff.', 1325, 'Art/2DArt/SkillIcons/HolyStrike.dds', '[1,2]', '[76,5,0,20,19,23,30,8,116]', '[12,17,14,57,32]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[0,19,20,23,30,116]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1605, 'discus_slam', 'Divine Blast', 'Project a beam of holy light from your shield to a targeted location, causing an implosion of holy energy. This energy then lingers for a short duration, before blasting outwards in a larger and more damaging explosion.', 1328, 'Art/2DArt/SkillIcons/DiscusSlam.dds', '[1,2]', '[7,0,27,8,28]', '[26]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1606, 'discus_slam_alt_x', 'Divine Blast of Radiance', 'Project a beam of holy light from your shield to a targeted location, causing an implosion of holy energy. This energy then lingers for a short duration as an orb, periodically releasing larger explosions. Increases and reductions to attack speed affect the rate at which explosions occur.', 1328, 'Art/2DArt/SkillIcons/DiscusSlam.dds', '[1,2]', '[7,0,27,8,28,99]', '[26]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1605, ''),
(1607, 'suspend_in_time', 'Suspend in Time', 'Creates a Suspended Mirage - an astral-infused clone of yourself that is suspended in time, just before the release of the spellcast that triggered them. On reaching three Suspended Mirages, all Suspended Mirages will be released, using the spell which was cast to create them. Suspended Mirages are not created by Vaal spells, channelling spells, instant spells, or spells which create minions.', 1330, 'Art/2DArt/SkillIcons/StoppedHourglassIcon.dds', '[1]', '[1,89,31,5,8,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1608, 'pack_teleport', '', '', 1050, '', '[1,2]', '[1]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1609, 'teleport_explode_kill', '', '', 1051, '', '[1,2]', '[1,7]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1610, 'affliction_daemon_destroy_corpse_projectile', '', '', 1052, '', '[6]', '[1,7,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1611, 'affliction_daemon_destroy_corpse_spawn_monster', '', '', 1053, '', '[6]', '[1,7,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1612, 'spellslinger', 'Spellslinger', 'Reserves mana based on the supported spells to cause those spells to trigger when you fire projectiles from a wand attack.', 1054, 'Art/2DArt/SkillIcons/Spellslinger.dds', '[4]', '[1,63,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1613, 'embrace_madness', 'Embrace Madness', 'Grants Glorious Madness. Using this skill again will remove Glorious Madness and the Touched Debuffs it inflicts, but you will be unable to Embrace Madness again until the cooldown expires.', 1055, 'Art/2DArt/BuffIcons/LeagueItemDebuff.dds', '[4]', '[1,4,63,89,11]', '[]', '', '', 1, '', 0, 22, 1, '[11860]', '[6412]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1614, 'arcanist_brand', 'Arcanist Brand', 'Creates a magical brand which can attach to a nearby enemy. It periodically activates while attached, triggering linked spells. The brand will detach if the enemy dies.', 1056, 'Art/2DArt/SkillIcons/ConduitSigilPurple.dds', '[1,2]', '[1,8,21,64]', '[]', '', '', 1, '', 0, 22, 1, '[12515,18215]', '[218,18130]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1615, 'rallying_cry', 'Rallying Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. Nearby allies gain a buff based on the damage of your weapon.', 1057, 'Art/2DArt/SkillIcons/RallyingCry.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,5623,4578,12489,12488,4414,12487]', '[9795,4602,4602,12496,12495,217,12004]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1616, 'infernal_cry', 'Infernal Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants a portion of their physical damage as extra fire damage. In addition to being taunted, enemies are inflicted with a secondary debuff causing them to explode when they die, dealing fire damage in an area.', 1058, 'Art/2DArt/SkillIcons/WarCryInfernal.dds', '[4]', '[7,8,28,6,62,89]', '[]', '', '', 1, 'AbyssalCry', 0, 22, 1, '[9796,4128,4415,12464,16118]', '[9795,24,217,3396,436]', '[]', 1, 1, '[16077,436]', 8, NULL, 0, '', '[39,16,10,11,17,4,18,29,19,26]', 0, 0, 1, NULL, ''),
(1617, 'brandsurge', 'Brandsurge', 'Overcharges your brands near the targeted area, causing them to accelerate how quickly they activate and expire. Deals damage in an area around each overcharged brand when it expires.', 1059, 'Art/2DArt/SkillIcons/BrandDetonate.dds', '[2,1]', '[1,31,27,6,7,71,21,13,15,14,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1618, 'seismic_cry', 'Seismic Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent slam attacks. The user and nearby allies gain a buff that increases their armour and stun threshold.', 1060, 'Art/2DArt/SkillIcons/SeismicCry.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,5623,12472,12475]', '[9795,4602,12470,13422]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1619, 'ancestral_cry', 'Ancestral Cry', 'Performs a warcry, taunting all nearby enemies to attack the user and exerting subsequent strike attacks. The user and nearby allies gain a buff that  grants elemental resistances.', 1061, 'Art/2DArt/SkillIcons/WarCryAncestral.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,5623,12471,12474,16117]', '[9795,4602,12470,13422,12004]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1620, 'infernal_cry_on_hit_explosion', 'Combust', 'Deals attack damage in an area.', 1062, 'Art/2DArt/SkillIcons/WarCryInfernal2.dds', '[2,1]', '[0,7,6,31,36,19,49]', '[9,10,15,11,16,12,32,17,14,36,57]', '', '', 1, '', 0, 22, 1, '[12468,16075]', '[436,16076]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1621, 'fiery_impact', 'Fiery Impact', 'Deals attack damage in an area.', 1062, 'Art/2DArt/SkillIcons/FieryBlast.dds', '[2,1]', '[0,7,6,31,36,19,49,89]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1622, 'penance_brand', 'Penance Brand', 'Creates a magical brand which can attach to a nearby enemy. It periodically activates while attached, adding energy to the branded enemy. When the branded enemy reaches 20 energy, a large explosion occurs and the brand is removed. All energy is removed from the enemy when the brand is detached.', 1063, 'Art/2DArt/SkillIcons/PhysicalLightningBrand.dds', '[1,2]', '[1,6,7,27,30,8,14,13,15,31,21,64,71]', '[]', '', '', 1, '', 0, 22, 1, '[12510,12511,12512]', '[24,218,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1623, 'penance_brand_alt_x', 'Penance Brand of Dissipation', 'Creates a magical brand which can attach to a nearby enemy. It periodically activates while attached, adding energy to the branded enemy and causing a pulse that deals damage to the branded enemy and other nearby enemies. The pulse gains area of effect and damage for each energy on the branded enemy, up to 20. All energy is removed from the enemy when the brand is detached.', 1063, 'Art/2DArt/SkillIcons/PhysicalLightningBrand.dds', '[1,2]', '[1,6,7,27,30,8,14,13,15,31,21,64,71]', '[]', '', '', 1, '', 0, 22, 1, '[12510,12511,12512]', '[24,218,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1622, ''),
(1624, 'penance_brand_alt_y', 'Penance Brand of Conduction', 'Creates a magical brand which can attach to a nearby enemy. It periodically activates while attached, adding energy to the branded enemy and nearby enemies who do not have energy. When the brand is detached, all enemies with energy are dealt damage.', 1063, 'Art/2DArt/SkillIcons/PhysicalLightningBrand.dds', '[1,2]', '[1,6,7,27,30,8,14,13,15,31,21,64,71]', '[]', '', '', 1, '', 0, 22, 1, '[12510,12511,12512]', '[24,218,436]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1622, ''),
(1625, 'wintertide_brand', 'Wintertide Brand', 'Creates a magical brand which can attach to a nearby enemy, dealing cold damage over time and chilling them. It periodically activates while attached, gaining stages that raise the damage. When removed, a short-duration debuff dealing the same damage over time and chill is applied to each nearby enemy. The brand keeps its charges while detached.', 1064, 'Art/2DArt/SkillIcons/ColdBrand.dds', '[1,2]', '[1,7,29,8,14,13,15,31,21,64,71,34,66,16,48]', '[]', '', '', 1, '', 0, 22, 1, '[12507,12508,12509,18215]', '[24,12364,3622,18130]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1626, 'wintertide_brand_alt_x', '[DNT] WintertideBrandAltX', 'Creates a magical brand which can attach to a nearby enemy, dealing cold damage over time and chilling them. It periodically activates while attached, gaining stages that raise the damage. When removed, a short-duration debuff dealing the same damage over time and chill is applied to each nearby enemy. The brand keeps its charges while detached.', 1064, 'Art/2DArt/SkillIcons/ColdBrand.dds', '[1,2]', '[1,7,29,8,14,13,15,31,21,64,71,34,66,16,48]', '[]', '', '', 1, '', 0, 22, 1, '[12507,12508,12509,18215]', '[24,12364,3622,18130]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 1625, ''),
(1627, 'wintertide_brand_alt_y', '[DNT] WintertideBrandAltY', 'Creates a magical brand which can attach to a nearby enemy, dealing cold damage over time and chilling them. It periodically activates while attached, gaining stages that raise the damage. When removed, a short-duration debuff dealing the same damage over time and chill is applied to each nearby enemy. The brand keeps its charges while detached.', 1064, 'Art/2DArt/SkillIcons/ColdBrand.dds', '[1,2]', '[1,7,29,8,14,13,15,31,21,64,71,34,66,16,48]', '[]', '', '', 1, '', 0, 22, 1, '[12507,12508,12509,18215]', '[24,12364,3622,18130]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, 1625, ''),
(1628, 'earthshatter', 'Earthshatter', 'Slam the ground, sending out rectangular fissures that deal area damage to enemies and thrust a spike from the ground when they end. Warcries or other Slam Attacks performed by you or allied players near any spike will cause them to shatter, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed.', 1065, 'Art/2DArt/SkillIcons/SpikeSlam.dds', '[1,2,23]', '[0,7,19,91,23,8,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[12513,12514,18198]', '[24,436,18120]', '[]', 1, 1, '[12423,12424]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1629, 'earthshatter_alt_x', 'Earthshatter of Fragility', 'Slam the ground, sending out rectangular fissures that deal area damage to enemies and thrust a spike from the ground when they end. The spikes shatter after a duration, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed.', 1065, 'Art/2DArt/SkillIcons/SpikeSlam.dds', '[1,2,23]', '[0,7,19,91,23,8,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[12513,12514,18198]', '[24,436,18120]', '[]', 1, 1, '[12423,12424]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1628, ''),
(1630, 'earthshatter_alt_y', 'Earthshatter of Prominence', 'Slam the ground, sending out a rectangular fissure that deals area damage to enemies and thrusts a large spike from the ground where it ends. Warcries or other Slam Attacks performed by you or allied players near the spike will cause it to shatter, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed.', 1065, 'Art/2DArt/SkillIcons/SpikeSlam.dds', '[1,2,23]', '[0,7,19,91,23,8,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[12513,12514,18198]', '[24,436,18120]', '[]', 1, 1, '[12423,12424]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1628, ''),
(1631, 'generals_cry', 'General''s Cry', 'Performs a warcry, taunting nearby enemies to attack the user, and summoning Mirage Warriors from nearby corpses. The Mirage Warriors each use a linked attack skill once before dissipating.', 1066, 'Art/2DArt/SkillIcons/WarCryGenerals.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,12466,12469,18752,18753]', '[9795,3396,12045,18754,18755]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1632, 'generals_cry_alt_x', '[DNT] GeneralsCryAltX', 'Performs a warcry, taunting nearby enemies to attack the user, and summoning Mirage Warriors from nearby corpses. The Mirage Warriors each use a linked attack skill once before dissipating.', 1066, 'Art/2DArt/SkillIcons/WarCryGenerals.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,12466,12469,18752,18753]', '[9795,3396,12045,18754,18755]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, 1631, ''),
