(1635, 'summon_mirage_chieftain', 'Tawhoa''s Chosen', 'This skill is triggered when you use a Slam or Strike skill, and summons a Mirage Chieftain who will use that Slam or Strike skill once before dissipating.', 1068, 'Art/2DArt/SkillIcons/TawhoaForestsStrength.dds', '[4]', '[1,31,36,49,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
