(1639, 'blazing_salvo', 'Blazing Salvo', 'Fires projectiles which fly in an arc, dealing area damage on impact with either enemies or the ground near where you target. Targeting farther away causes the projectiles to spread out and land over a wider area.', 1072, 'Art/2DArt/SkillIcons/Ember.dds', '[1,2]', '[1,6,7,13,15,14,31,28,2,56,21,69,71]', '[]', '', '', 1, '', 0, 22, 1, '[13237,13238,18337]', '[24,175,18280]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1640, 'blazing_salvo_alt_x', '[DNT] Blazing Salvo of Wildfire', '[DNT] Fires a ring of projectiles which fly in an arc, dealing area damage on impact with either enemies or the ground near where you target', 1072, 'Art/2DArt/SkillIcons/Ember.dds', '[1,2]', '[1,6,7,13,15,14,31,28,2,56,21,69,71]', '[]', '', '', 1, '', 0, 22, 1, '[13237,13238,18337]', '[24,175,18280]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1639, ''),
