(1663, 'lancing_steel_new', 'Lancing Steel', 'Thrust an Axe or Sword forward, consuming your Steel Shards to form a cluster of shards in front of you. The cluster will fire a number of projectiles in sequence, aiming at enemies in front of or close to it. Steel Shards are gained with the Call of Steel Skill.', 1084, 'Art/2DArt/SkillIcons/LancingSteel.dds', '[1,2]', '[0,2,6,10,40,27,81,95]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[8850,8881,8884,13192,13248]', '[24,8883,8568,13187,175]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1664, 'lancing_steel_new_alt_x', 'Lancing Steel of Spraying', 'Thrust an Axe or Sword forward to form a cluster of shards in front of you. The cluster will fire a number of projectiles in sequence, aiming at enemies in front of or close to it.', 1084, 'Art/2DArt/SkillIcons/LancingSteel.dds', '[1,2]', '[0,2,6,10,40,81]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[8850,8881,8884,13192,13248]', '[24,8883,8568,13187,175]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1663, ''),
(1665, 'lancing_steel_new_alt_y', '[DNT] LancingSteelAltY', 'Thrust an Axe or Sword forward, consuming your Steel Shards to form a cluster of shards in front of you. The cluster will fire a number of projectiles in sequence, aiming at enemies in front of or close to it. Steel Shards are gained with the Call of Steel Skill.', 1084, 'Art/2DArt/SkillIcons/LancingSteel.dds', '[1,2]', '[0,2,6,10,40,27,81,95]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[8850,8881,8884,13192,13248]', '[24,8883,8568,13187,175]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1663, ''),
(1666, 'corpse_walk', 'Corpse Walk', 'Spawns corpses around you while you move, based on monsters in the current area. If you are using the Raise Spectre skill there is a chance to spawn spectral corpses matching your most recently raised Spectres. Spectral corpses cannot be interacted with except by Minion skills.', 1085, 'Art/2DArt/SkillIcons/DisturbtheDead.dds', '[4]', '[7,31,36,49,132]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
