(1668, 'player_glacial_cascade', 'Glacial Cascade', 'Icicles emerge from the ground in a series of small bursts, each damaging enemies caught in the area and knocking them back in the direction of the next burst.', 1086, 'Art/2DArt/SkillIcons/Upheaval.dds', '[1,2]', '[1,6,7,13,14,15,21,31,29,27,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/GlacialCascade.jpg', 0, 'GlacialCascade', 0, 22, 1, '[4096,4344,4259,6553,13249]', '[24,1106,436,2152,450]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1669, 'player_glacial_cascade_alt_x', 'Glacial Cascade of the Fissure', 'Icicles emerge from the ground in a series of small bursts, each damaging enemies caught in the area.', 1086, 'Art/2DArt/SkillIcons/Upheaval.dds', '[1,2]', '[1,6,7,13,14,15,21,31,29,27,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/GlacialCascade.jpg', 0, 'GlacialCascade', 0, 22, 1, '[4096,4344,4259,6553,13249]', '[24,1106,436,2152,450]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1668, ''),
(1670, 'player_glacial_cascade_alt_y', '[DNT] GlacialCascadeAltY', 'Icicles emerge from the ground in a series of small bursts, each damaging enemies caught in the area and knocking them back in the direction of the next burst.', 1086, 'Art/2DArt/SkillIcons/Upheaval.dds', '[1,2]', '[1,6,7,13,14,15,21,31,29,27,69,71]', '[]', '', 'http://webcdn.pathofexile.com/public/chris/GlacialCascade.jpg', 0, 'GlacialCascade', 0, 22, 1, '[4096,4344,4259,6553,13249]', '[24,1106,436,2152,450]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1668, ''),
(1671, 'death_wish', 'Death Wish', 'As you channel this spell, it spreads its effect to more of your minions. When you stop channelling, each affected minion explodes, and this skill deals spell damage around them.  The explosion of the minion is not affected by modifiers to spell damage, and cannot be reflected.', 1087, 'Art/2DArt/SkillIcons/Deathwish.dds', '[1]', '[1,47,71,7,6,5,28]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(1672, 'hexblast', 'Hexblast', 'Deals chaos damage to a single enemy, dealing more damage if they are Hexed, then removing the Hex. If the enemy was Hexed, also deals area damage to other enemies around the target, boosting damage and removing Hexes from those enemies in the same way.', 1088, 'Art/2DArt/SkillIcons/DoomBlastSkill.dds', '[1,2,22]', '[1,6,7,41,13,14,15,21,31,69,96,71,89]', '[]', '', '', 1, '', 0, 22, 1, '[13251,13252,18252]', '[24,436,3466]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1673, 'hexblast_alt_x', 'Hexblast of Contradiction', 'Deals chaos damage to a single enemy, dealing more damage if they are Hexed, then removing the Hex. If the enemy was Hexed, also deals area damage to other enemies around the target, boosting damage and removing Hexes from those enemies in the same way.', 1088, 'Art/2DArt/SkillIcons/DoomBlastSkill.dds', '[1,2,22]', '[1,6,7,41,13,14,15,21,31,69,96,71,89]', '[]', '', '', 1, '', 0, 22, 1, '[13251,13252,18252]', '[24,436,3466]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1672, ''),
