(1677, 'unseen_strike', 'Unseen Strike', 'Launches a spinning blade that deals weapon damage to enemies. If firing multiple projectiles, they will be fired in a circle.', 1090, 'Art/2DArt/SkillIcons/SecretBlade.dds', '[1,2]', '[2,0,40,31,56,27,89]', '[6,7,56,9,10,12,32,11]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1678, 'shield_shatter', 'Shield Shatter', 'Your shield shatters, dealing physical spell damage to enemies in an area, based on the shield''s quality. For a short duration after this, you will be unable to block and will gain no defences from your shield, but your spells will deal added physical damage.', 1091, 'Art/2DArt/SkillIcons/EverglassBarrier.dds', '[4]', '[6,27,1,7,71,83,31,36,49,8]', '[26]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1679, 'ward_shatter', 'Ward Shatter', 'Your ward shatters, dealing physical spell damage to enemies in an area, based on the amount of ward you have. Enemies hit are inflicted with Enervation, a Debuff that lowers Movement Speed by 20% and prevents Life and Energy Shield Recovery for 4 seconds.', 1091, 'Art/2DArt/SkillIcons/WardShatter.dds', '[4]', '[6,27,1,7,71,83,31,36,49]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
