(1682, 'oil_arrow', 'Flammable Shot', '[UNUSED] The environmentally unsustainable child of Explosive Arrow and Flame Wall', 1093, 'Art/2DArt/SkillIcons/fusearrow.dds', '[1,2]', '[0,40,57,2,56,6,7,8,14,13,15,28,31,34]', '[13]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1683, 'hydrosphere', 'Hydrosphere', 'Create a sphere of water, or move an existing sphere and reset its duration. The sphere continually applies a drenched debuff with a short duration to enemies in its area or those it moves through. You can hit the sphere with other skills to inflict Cold and Lightning Ailments (other than Chill). The sphere pulses when created, at regular intervals while afflicted by an Ailment, and after moving, damaging all drenched enemies in a large area.', 1094, 'Art/2DArt/SkillIcons/Hydrosphere.dds', '[1,22]', '[6,1,7,8,13,15,31,71,29,14,99,21,69,30,27]', '[]', '', '', 1, '', 1, 22, 1, '[13959]', '[24]', '[]', 1, 1, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1684, 'hydrosphere_alt_x', '[DNT] HydrosphereAltX', 'Create a sphere of water, or move an existing sphere and reset its duration. The sphere continually applies a drenched debuff with a short duration to enemies in its area or those it moves through. You can hit the sphere with other skills to inflict Cold and Lightning Ailments (other than Chill). The sphere pulses when created, at regular intervals while afflicted by an Ailment, and after moving, damaging all drenched enemies in a large area.', 1094, 'Art/2DArt/SkillIcons/Hydrosphere.dds', '[1,22]', '[6,1,7,8,13,15,31,71,29,14,99,21,69,30,27]', '[]', '', '', 1, '', 1, 22, 1, '[13959]', '[24]', '[]', 1, 1, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1683, ''),
(1685, 'hydrosphere_alt_y', '[DNT] HydrosphereAltY', 'Create a sphere of water, or move an existing sphere and reset its duration. The sphere continually applies a drenched debuff with a short duration to enemies in its area or those it moves through. You can hit the sphere with other skills to inflict Cold and Lightning Ailments (other than Chill). The sphere pulses when created, at regular intervals while afflicted by an Ailment, and after moving, damaging all drenched enemies in a large area.', 1094, 'Art/2DArt/SkillIcons/Hydrosphere.dds', '[1,22]', '[6,1,7,8,13,15,31,71,29,14,99,21,69,30,27]', '[]', '', '', 1, '', 1, 22, 1, '[13959]', '[24]', '[]', 1, 1, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1683, ''),
(1686, 'hydrosphere_triggered', 'Hydrosphere', 'Create a sphere of water, or move an existing sphere and reset its duration. The sphere continually applies a drenched debuff with a short duration to enemies in its area or those it moves through. You can hit the sphere with other skills to inflict Cold and Lightning Ailments (other than Chill). The sphere pulses when created, at regular intervals while afflicted by an Ailment, and after moving, damaging all drenched enemies in a large area.', 1094, 'Art/2DArt/SkillIcons/Hydrosphere.dds', '[1,22]', '[6,1,7,8,13,15,31,71,29,14,99,21,69,30,27,36,49,89]', '[]', '', '', 1, '', 1, 22, 0, '[13959]', '[24]', '[]', 1, 0, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
