(1688, 'aegis_elementalist', 'Primal Aegis', 'Calls forth a protective aegis which takes elemental damage from hits for you until depleted. The aegis will be restored to its full value after a short delay if you stop taking elemental damage from hits, or if depleted.', 795, 'Art/2DArt/BuffIcons/PrimalAegis.dds', '[4]', '[1,31,36,49,98]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
