(1698, 'steelskin_ally', 'Steelskin', 'Applies a buff which can take some of the damage from hits for you before being depleted. Shares a cooldown with other Guard skills.', 985, 'Art/2DArt/BuffIcons/QuickGuard.dds', '[3]', '[1,4,63,8,31,77,89]', '[]', '', '', 1, '', 0, 22, 1, '[9672,10027,22126]', '[9521,1037,9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1699, 'unearth_channelled', 'Unearth', 'Fires a projectile that will pierce through enemies to impact the ground at the targeted location, creating a Bone Archer corpse where it lands.', 777, 'Art/2DArt/SkillIcons/BoneLance.dds', '[1,11,23]', '[1,2,56,14,6,7,71,27,47,132]', '[]', '', '', 1, '', 0, 22, 1, '[6976,7371,7375]', '[6432,24,218]', '[]', 1, 1, '[6918]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
