(1701, 'exsanguinate', 'Exsanguinate', 'Releases several tendrils of blood from your character, targeting enemies in a narrow angle in front of you. The beams deal physical damage and inflict a physical damage over time debuff to enemies, which can stack up to 3 times. Effects which allow skills to chain can apply to these tendrils.', 1102, 'Art/2DArt/SkillIcons/BloodTendrilsSkill.dds', '[1,2]', '[1,6,13,14,15,18,21,31,27,69,34,8]', '[]', '', '', 1, '', 0, 22, 1, '[14354,14355,14373,18246,18153]', '[24,217,8828,1105,18275]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1702, 'exsanguinate_alt_x', 'Exsanguinate of Transmission', 'Releases a tendril of blood from your character, which will target an enemy in front of you, then chain to other enemies. The tendril deals physical damage and inflicts a physical damage over time debuff to enemies, which can stack up to 3 times.', 1102, 'Art/2DArt/SkillIcons/BloodTendrilsSkill.dds', '[1,2]', '[1,6,13,14,15,18,21,31,27,69,34,8]', '[]', '', '', 1, '', 0, 22, 1, '[14354,14355,14373,18246,18153]', '[24,217,8828,1105,18275]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1701, ''),
(1703, 'exsanguinate_alt_y', '[DNT] ExsanguinateAltY', 'Releases several tendrils of blood from your character, targeting enemies in a narrow angle in front of you. The beams deal physical damage and inflict a physical damage over time debuff to enemies, which can stack up to 3 times. Effects which allow skills to chain can apply to these tendrils.', 1102, 'Art/2DArt/SkillIcons/BloodTendrilsSkill.dds', '[1,2]', '[1,6,13,14,15,18,21,31,27,69,34,8]', '[]', '', '', 1, '', 0, 22, 1, '[14354,14355,14373,18246,18153]', '[24,217,8828,1105,18275]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1701, ''),
(1704, 'corrupting_fever', 'Corrupting Fever', 'Draws out your own blood to power a buff for a duration, letting this skill inflict the Corrupting Blood debuff on enemies you hit, dealing physical damage over time for a short secondary duration. The buff''s duration will be refreshed if you spend enough life before it expires.', 1103, 'Art/2DArt/SkillIcons/CorruptedBloodStream.dds', '[4]', '[1,4,8,31,63,27,89,34,14]', '[]', '', '', 1, '', 0, 22, 1, '[14358,14359]', '[24,217]', '[]', 1, 1, '[14369]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(1705, 'resentment', 'Cinders', 'While active, your bow attacks inflict Cinderflame. Cinderflame deals fire damage over time, and can stack up to ten times. This skill cannot be cast by Totems.', 1103, 'Art/2DArt/SkillIcons/Resentment.dds', '[4]', '[1,4,8,31,36,63,89,34,28,24]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[16,10,11,17]', 1, 0, 1, NULL, ''),
(1706, 'animosity', 'Tears of Rot', 'While active, this skill inflicts the Weeping Black debuff on impaled enemies you hit with bow attacks. Weeping Black deals physical damage over time, and can stack up to five times. This skill cannot be cast by Totems.', 1103, 'Art/2DArt/BuffIcons/Animosity.dds', '[4]', '[1,4,8,31,36,63,89,34,27]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
