(1710, 'reap', 'Reap', 'A bloody scythe swipes across a selected area, applying a physical damage over time debuff and hitting enemies with physical damage. If any survive, you gain a blood charge which raises the damage and cost of the skill. Players can have 5 maximum blood charges.', 1107, 'Art/2DArt/SkillIcons/Bloodreap.dds', '[18,22]', '[1,6,27,34,7,71,8,13,14,15,21,69,55,31]', '[]', '', '', 1, '', 0, 22, 1, '[14356,14357,18246,18154]', '[24,436,1105,18275]', '[]', 1, 1, '[14371]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1711, 'reap_alt_x', 'Reap of Butchery', 'A bloody scythe swipes around you, applying a physical damage over time debuff and hitting enemies with physical damage. If any survive, you gain a blood charge which raises the damage and cost of the skill. Players can have 5 maximum blood charges.', 1107, 'Art/2DArt/SkillIcons/Bloodreap.dds', '[4]', '[1,6,27,34,7,71,8,13,14,15,21,69,31]', '[]', '', '', 1, '', 1, 22, 1, '[14356,14357,18246,18154]', '[24,436,1105,18275]', '[]', 1, 1, '[14371]', 8, 3, 0, 'Metadata/Monsters/Totems/ReapTotemAlt.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1710, ''),
(1712, 'reap_alt_y', '[DNT] BloodreapAltY', 'A bloody scythe swipes across a selected area, applying a physical damage over time debuff and hitting enemies with physical damage. If any survive, you gain a blood charge which raises the damage and cost of the skill. Players can have 5 maximum blood charges.', 1107, 'Art/2DArt/SkillIcons/Bloodreap.dds', '[18,22]', '[1,6,27,34,7,71,8,13,14,15,21,69,55,31]', '[]', '', '', 1, '', 0, 22, 1, '[14356,14357,18246,18154]', '[24,436,1105,18275]', '[]', 1, 1, '[14371]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1710, ''),
(1713, 'vaal_reap', 'Vaal Reap', 'Bloody scythes swipe around a selected area, hitting enemies with physical damage. An area of boiling blood is left beneath them for a duration which deals physical damage over time. Also gives a bonus to maximum Blood Charges for a secondary duration.', 1108, 'Art/2DArt/SkillIcons/Bloodreap.dds', '[18,22]', '[1,6,27,34,7,71,8,13,14,15,37,21]', '[]', '', '', 1, '', 1, 22, 1, '[14356,14357,18246,18154]', '[24,436,1105,18275]', '[]', 1, 1, '[]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1714, 'petrified_blood', 'Petrified Blood', 'Applies a buff that protects the lower half of your life, preventing some of the immediate life loss when damaged by hits and applying the loss over time instead. Your life cannot be raised above low life other than by flasks, and while above low life, skills will cost life as well as mana.', 1097, 'Art/2DArt/SkillIcons/PetrifiedBlood.dds', '[4]', '[1,4,63,84,85,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[14360,15216,15246]', '[14196,14925,15106]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1715, 'queens_demand', 'Queen''s Demand', 'Alternates triggering Flames of Judgement and Storm of Judgement', 1109, 'Art/2DArt/SkillIcons/QueensDemand.dds', '[1,2]', '[1,21,69]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
