(1719, 'defiance_banner', 'Defiance Banner', 'You must gain Valour from melee combat to use this skill, which will consume all Valour to place a banner with an aura. The aura will be larger and more powerful the more Valour was consumed. The banner lasts for a duration, but will end early if you leave the aura, or use the skill again while it''s active.', 1113, 'Art/2DArt/SkillIcons/ArmourandEvasionBanner.dds', '[1]', '[4,7,1,8,38,63,71,70,87,84,85,89]', '[]', '', '', 1, '', 0, 22, 1, '[8842,14842,15229]', '[14217,1979,14925]', '[]', 1, 1, '[20791]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(1720, 'voltaxic_burst', 'Voltaxic Burst', 'Each cast of this spell waits for a short duration, releasing a burst of lightning and chaos spell damage in an area around you when that duration ends. Enemies killed by this damage, or shortly after, will explode. The explosions of the corpses are not affected by modifiers to spell damage, and cannot be reflected.', 1114, 'Art/2DArt/SkillIcons/VoidburstIcon.dds', '[1,22]', '[1,6,7,13,14,15,21,31,41,30,69,71,83,8]', '[]', '', '', 1, '', 0, 22, 1, '[14812,14813,14825,18256]', '[24,436,12401,10860]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/VoltaxicBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, NULL, ''),
(1721, 'voltaxic_burst_alt_x', '[DNT] VoltaxicBurstAltX', 'Each cast of this spell waits for a short duration, releasing a burst of lightning and chaos spell damage in an area around you when that duration ends. Enemies killed by this damage, or shortly after, will explode. The explosions of the corpses are not affected by modifiers to spell damage, and cannot be reflected.', 1114, 'Art/2DArt/SkillIcons/VoidburstIcon.dds', '[1,22]', '[1,6,7,13,14,15,21,31,41,30,69,71,83,8]', '[]', '', '', 1, '', 0, 22, 1, '[14812,14813,14825,18256]', '[24,436,12401,10860]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/VoltaxicBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1720, ''),
(1722, 'voltaxic_burst_alt_y', '[DNT] VoltaxicBurstAltY', 'Each cast of this spell waits for a short duration, releasing a burst of lightning and chaos spell damage in an area around you when that duration ends. Enemies killed by this damage, or shortly after, will explode. The explosions of the corpses are not affected by modifiers to spell damage, and cannot be reflected.', 1114, 'Art/2DArt/SkillIcons/VoidburstIcon.dds', '[1,22]', '[1,6,7,13,14,15,21,31,41,30,69,71,83,8]', '[]', '', '', 1, '', 0, 22, 1, '[14812,14813,14825,18256]', '[24,436,12401,10860]', '[]', 1, 1, '[]', 8, 3, 0, 'Metadata/Monsters/Totems/VoltaxicBurstTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13,4]', 0, 0, 1, 1720, ''),
(1723, 'rage_vortex', 'Rage Vortex', 'Spin with a sword or axe to deal damage in an area around you. Sacrifices some rage to send a ragestorm forward. While enemies are inside it, the ragestorm will slow its movement and repeatedly deal attack damage based on your attack speed.', 1115, 'Art/2DArt/SkillIcons/RageVortex.dds', '[2,1]', '[0,19,7,8,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[14845,14846]', '[24,436]', '[]', 1, 1, '[14409,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1724, 'rage_vortex_alt_x', 'Rage Vortex of Berserking', 'Spin with a sword or axe to deal damage in an area around you. If you have at least 10 rage, create a ragestorm attached to you that repeatedly deals attack damage to enemies inside based on your attack speed. The ragestorm consumes rage at an accelerating rate, and ends if you run out.', 1115, 'Art/2DArt/SkillIcons/RageVortex.dds', '[2,1]', '[0,19,7,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[14845,14846]', '[24,436]', '[]', 1, 1, '[14409,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1723, ''),
(1725, 'rage_vortex_alt_y', '[DNT] RageVortexAltY', 'Spin with a sword or axe to deal damage in an area around you. Sacrifices some rage to send a ragestorm forward. While enemies are inside it, the ragestorm will slow its movement and repeatedly deal attack damage based on your attack speed.', 1115, 'Art/2DArt/SkillIcons/RageVortex.dds', '[2,1]', '[0,19,7,8,23]', '[9,10,15,11,16]', '', '', 1, '', 0, 22, 1, '[14845,14846]', '[24,436]', '[]', 1, 1, '[14409,18323]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1723, ''),
(1726, 'battlemages_cry', 'Battlemage''s Cry', 'Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that boosts critical strike chance.', 1116, 'Art/2DArt/SkillIcons/DivineCry.dds', '[4]', '[4,7,8,62,89]', '[]', '', '', 1, '', 0, 22, 1, '[9796,5623,14803,14804]', '[9795,4602,4602,12004]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1727, 'absolution', 'Absolution', 'Damages enemies in an area, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the corpse will be consumed to summon a Sentinel of Absolution for a secondary duration, or to refresh the duration and life of an existing one instead if you have the maximum number of them.', 1117, 'Art/2DArt/SkillIcons/AbsolutionBlast.dds', '[11,18,22]', '[1,5,8,27,30,17,76,6,7,21,55,31,14,13,15,69,128]', '[]', '', '', 1, '', 0, 22, 1, '[14805,14820,14821,18235]', '[4549,218,10084,12160]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1728, 'absolution_alt_x', 'Absolution of Inspiring', 'Damages enemies in an area, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the corpse will be consumed to summon a Sentinel of Absolution for a secondary duration, or to refresh the duration and life of an existing one instead if you have the maximum number of them.', 1117, 'Art/2DArt/SkillIcons/AbsolutionBlast.dds', '[11,18,22]', '[1,5,8,27,30,17,76,6,7,21,55,31,14,13,15,69,128]', '[]', '', '', 1, '', 0, 22, 1, '[14805,14820,14821,18235]', '[4549,218,10084,12160]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1727, ''),
(1729, 'absolution_alt_y', '[DNT] AbsolutionAltY', 'Damages enemies in an area, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the corpse will be consumed to summon a Sentinel of Absolution for a secondary duration, or to refresh the duration and life of an existing one instead if you have the maximum number of them.', 1117, 'Art/2DArt/SkillIcons/AbsolutionBlast.dds', '[11,18,22]', '[1,5,8,27,30,17,76,6,7,21,55,31,14,13,15,69,128]', '[]', '', '', 1, '', 0, 22, 1, '[14805,14820,14821,18235]', '[4549,218,10084,12160]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1727, ''),
(1730, 'vaal_absolution', 'Vaal Absolution', 'Causes one of your existing Sentinels of Absolution to Ascend, becoming more powerful, gaining new spells, and overriding its duration, while maintaining its other bonuses, including from support gems. If you cannot have more Ascended Sentinels of Absolution, an existing one will be refreshed instead.', 95, 'Art/2DArt/SkillIcons/AbsolutionBlast.dds', '[1,4]', '[1,5,8,27,30,37,21,128]', '[]', '', '', 1, '', 0, 22, 1, '[14805,14820,14821,18235]', '[4549,218,10084,12160]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1731, 'ambush_player', 'Ambush', 'Teleports you to a nearby enemy, applying a buff to you for a short duration and blinding the enemy for a secondary duration. Performing a melee attack with a One-Handed Weapon removes the buff to exert that attack.', 1118, 'Art/2DArt/SkillIcons/AmbushIcon.dds', '[1,2]', '[1,33,8,78,31,89,102]', '[]', '', '', 1, '', 0, 22, 1, '[14856,14857]', '[3396,14481]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1732, 'blade_trap', 'Blade Trap', 'Throws a trap which, once triggered, swings two copies of your equipped Dagger, Claw or One Handed Sword around it in circles, each repeatedly damaging enemies it spins through.', 1119, 'Art/2DArt/SkillIcons/BladeTrap.dds', '[2,1]', '[0,6,15,7,32,7]', '[9,7,56,6,10]', '', '', 1, '', 1, 22, 1, '[14806,14807,19353]', '[24,436,12665]', '[]', 1, 1, '[]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1733, 'blade_trap_alt_x', 'Blade Trap of Greatswords', 'Throws a trap which, once triggered, swings two copies of your equipped Two Handed Sword around it in circles for a duration, each repeatedly damaging enemies it spins through', 1119, 'Art/2DArt/SkillIcons/BladeTrap.dds', '[2,1]', '[0,6,15,7,32,7,89,8]', '[15]', '', '', 1, '', 1, 22, 1, '[14806,14807,19353]', '[24,436,12665]', '[]', 1, 1, '[]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1732, ''),
(1734, 'blade_trap_alt_y', 'Blade Trap of Laceration', 'Throws a trap which, once triggered, swings two copies of your equipped Dagger, Claw, One Handed Sword or One Handed Axe around it in a circle, each damaging enemies it spins through.', 1119, 'Art/2DArt/SkillIcons/BladeTrap.dds', '[2,1]', '[0,6,15,7,32,7,27]', '[9,7,56,6,10,11]', '', '', 1, '', 1, 22, 1, '[14806,14807,19353]', '[24,436,12665]', '[]', 1, 1, '[]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1732, ''),
(1735, 'forbidden_rite', 'Forbidden Rite', 'Lobs an exploding projectile near the targeted location, and extra projectiles toward enemies around you. The projectiles deal chaos damage based on your life and energy shield. Casting this spell damages you.', 1120, 'Art/2DArt/SkillIcons/Soulfeast.dds', '[1,2]', '[1,6,7,13,15,14,31,41,2,56,21,69,71,41]', '[]', '', '', 1, '', 0, 22, 1, '[14818,14819,14836,18226]', '[24,177,175,18137]', '[]', 1, 1, '[14431]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1736, 'forbidden_rite_alt_x', 'Forbidden Rite of Soul Sacrifice', 'Lobs an exploding projectile near the targeted location, and extra projectiles toward enemies around you. The projectiles deal chaos damage based on your energy shield. Casting this spell damages you.', 1120, 'Art/2DArt/SkillIcons/Soulfeast.dds', '[1,2]', '[1,6,7,13,15,14,31,41,2,56,21,69,71,41]', '[]', '', '', 1, '', 0, 22, 1, '[14818,14819,14836,18226]', '[24,177,175,18137]', '[]', 1, 1, '[14431]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1735, ''),
(1737, 'forbidden_rite_alt_y', '[DNT] ForbiddenRiteAltY', 'Lobs an exploding projectile near the targeted location, and extra projectiles toward enemies around you. The projectiles deal chaos damage based on your life and energy shield. Casting this spell damages you.', 1120, 'Art/2DArt/SkillIcons/Soulfeast.dds', '[1,2]', '[1,6,7,13,15,14,31,41,2,56,21,69,71,41]', '[]', '', '', 1, '', 0, 22, 1, '[14818,14819,14836,18226]', '[24,177,175,18137]', '[]', 1, 1, '[14431]', 8, 2, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1735, ''),
(1738, 'manabond', 'Manabond', 'Deals lightning damage based upon your missing mana in a circular area around the targeted location, as well as in four rectangular extensions whose lengths depend upon your remaining mana.', 1121, 'Art/2DArt/SkillIcons/ManaVoid.dds', '[1,22]', '[1,7,6,71,30,14,15,13,55,21,69,31,103]', '[]', '', '', 1, '', 1, 22, 1, '[14808,14809,14828,18247,18248]', '[24,436,14827,1492,2111]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
