(1741, 'storm_rain', 'Storm Rain', 'Fires an arrow into the air to land at a targeted location, dealing area damage. The arrow sticks in the ground where it lands, and periodically fires a beam of lightning to another arrow near it, dealing area damage between them.', 1122, 'Art/2DArt/SkillIcons/PrismaticRain.dds', '[1,2]', '[0,40,57,7,10,14,13,15,31,88,30,61,6]', '[13]', '', '', 1, '', 1, 22, 1, '[14843,14844,18229]', '[24,176,18141]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1742, 'storm_rain_alt_x', 'Storm Rain of the Conduit', 'Fires an arrow into the air to land at a targeted location, dealing area damage. The arrow sticks in the ground where it lands, and periodically fires a beam of lightning to you, dealing area damage between the arrow and you.', 1122, 'Art/2DArt/SkillIcons/PrismaticRain.dds', '[1,2]', '[0,40,57,7,10,14,13,15,31,88,30,61,6]', '[13]', '', '', 1, '', 1, 22, 1, '[14843,14844,18229]', '[24,176,18141]', '[]', 1, 1, '[]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1741, ''),
