(1744, 'shield_crush', 'Shield Crush', 'Swipe your shield, dealing area damage in three waves in front of you. Enemies can be hit by two of the waves where they overlap.', 1123, 'Art/2DArt/SkillIcons/ShieldCrush.dds', '[1,2,22]', '[0,9,19,7,23,27]', '[26]', '', '', 1, '', 0, 22, 1, '[14847,14848,18219,18220,18221,18257]', '[24,70,18133,18134,1107,18132]', '[]', 1, 1, '[14839]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1745, 'shield_crush_alt_x', 'Shield Crush of the Chieftain', 'Swipe your shield, dealing area damage in three waves in front of you. Enemies can be hit by two of the waves where they overlap.', 1123, 'Art/2DArt/SkillIcons/ShieldCrush.dds', '[1,2,22]', '[0,9,19,7,23,28]', '[26]', '', '', 1, '', 0, 22, 1, '[14847,14848,18219,18220,18221,18257]', '[24,70,18133,18134,1107,18132]', '[]', 1, 1, '[14839]', 8, 6, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1744, ''),
