(1747, 'spectral_helix', 'Spectral Helix', 'Throws a spectral copy of your melee weapon. It spins around while flying in a large spiral, damaging enemies in its path, and bouncing if it collides with walls.', 202, 'Art/2DArt/SkillIcons/SpectralSpiral.dds', '[1,2,23]', '[0,40,2,56]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[14816,14817,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[14823,18241]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1748, 'spectral_helix_alt_x', '[DNT] SpectralHelixAltX', 'Throws a spectral copy of your melee weapon. It spins around while flying in a large spiral, damaging enemies in its path, and bouncing if it collides with walls.', 202, 'Art/2DArt/SkillIcons/SpectralSpiral.dds', '[1,2,23]', '[0,40,2,56]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[14816,14817,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[14823,18241]', 8, 3, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1747, ''),
(1749, 'spectral_helix_alt_y', 'Spectral Helix of Trarthus', 'Throws a trap which, once triggered, fires a spectral copy of your melee weapon. It spins around while flying in a large spiral, damaging enemies in its path, and bouncing if it collides with walls. If dual wielding, each Trap thrown will randomly use either the main hand or off hand weapon.', 202, 'Art/2DArt/SkillIcons/SpectralSpiral.dds', '[1,2,23]', '[0,40,2,56,32]', '[6,7,9,10,11,12,32,14,15,16,17,57,56]', '', '', 1, '', 0, 22, 1, '[14816,14817,18747,18748]', '[24,177,7218,18749]', '[]', 1, 1, '[14823,18241]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1747, ''),
(1750, 'summon_reaper', 'Summon Reaper', 'Summons a powerful Reaper which uses a variety of slashing area attacks. The Reaper''s presence weakens your other minions, and it will consume them to temporarily empower and heal itself. Using this skill while the Reaper is already summoned causes it to dash to the targeted location and perform a powerful attack.', 1124, 'Art/2DArt/SkillIcons/SummonReaper.dds', '[2,1,22]', '[31,27,15,5,17,1,14,13,76,89]', '[]', '', '', 1, '', 0, 22, 1, '[14849]', '[3396]', '[0,19,6,7,33,23,8]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1751, 'summon_reaper_alt_x', 'Summon Reaper of Revenants', 'Summons a Reaper which uses a variety of slashing area attacks. The presence of any Reapers weakens your other non-Reaper minions, and Reapers will consume them to temporarily empower and heal themselves.', 1124, 'Art/2DArt/SkillIcons/SummonReaper.dds', '[2,1,22]', '[31,15,5,17,1,14,13,76,21,69]', '[]', '', '', 1, '', 0, 22, 1, '[14849]', '[3396]', '[0,19,6,7,33,23,8]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 1750, ''),
(1752, 'summon_reaper_alt_y', 'Summon Reaper of Eviscerating', 'Summons a powerful Reaper which passively follows you without attacking enemies. The Reaper''s presence weakens your other minions, and it will consume them to temporarily empower and heal itself. Using this skill while the Reaper is already summoned causes it to dash to the targeted location and perform a powerful attack. Cannot be triggered, supported by Spell Echo or Unleash, or used by Totems, Traps, or Mines. ', 1124, 'Art/2DArt/SkillIcons/SummonReaper.dds', '[2,1,22]', '[27,5,17,1,76]', '[]', '', '', 1, '', 0, 22, 1, '[14849]', '[3396]', '[0,19,6,7,33,23,8]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, 1750, ''),
(1753, 'reaper_consume_minion', '', '', 1125, '', '[3]', '[1]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 0, NULL, ''),
(1754, 'boneshatter', 'Boneshatter', 'Attack enemies with a forceful melee strike that also hurts you. Successive uses will raise the damage dealt both to enemies and you. Stunning an enemy with the strike releases a damaging pulse. Requires a Mace, Sceptre, Axe or Staff.', 1126, 'Art/2DArt/SkillIcons/Boneshatter.dds', '[1,2]', '[0,20,23,19,7,8,27,117]', '[11,12,32,14,16,17,57]', '', '', 1, '', 0, 22, 1, '[14850,14851,18096]', '[24,342,18095]', '[]', 1, 1, '[14840]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1755, 'boneshatter_alt_x', 'Boneshatter of Complex Trauma', 'Attack enemies with a forceful melee strike that also hurts you. Successive uses will raise the damage dealt both to enemies and you. Stunning an enemy with the strike releases a damaging pulse. Requires a Mace, Sceptre, Axe or Staff.', 1126, 'Art/2DArt/SkillIcons/Boneshatter.dds', '[1,2]', '[0,20,23,19,7,8,27,117]', '[11,12,32,14,16,17,57]', '', '', 1, '', 0, 22, 1, '[14850,14851,18096]', '[24,342,18095]', '[]', 1, 1, '[14840]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1754, ''),
(1756, 'boneshatter_alt_y', 'Boneshatter of Carnage', 'Attack enemies with a forceful melee strike. Stunning an enemy with the strike releases a damaging pulse. Requires a Mace, Sceptre, Axe or Staff.', 1126, 'Art/2DArt/SkillIcons/Boneshatter.dds', '[1,2]', '[0,20,23,19,7]', '[11,12,32,14,16,17,57]', '', '', 1, '', 0, 22, 1, '[14850,14851,18096]', '[24,342,18095]', '[]', 1, 1, '[14840]', 8, 2, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1754, ''),
