(1758, 'explosive_concoction', 'Explosive Concoction', 'Throws a bottle that explodes to deal unarmed attack damage in an area. Can consume charges from your Ruby, Sapphire, and Topaz flasks to add further damage. Requires an empty main hand, and no off-hand weapon.', 1128, 'Art/2DArt/SkillIcons/ExplosiveFlaskIcon.dds', '[1,2]', '[0,40,7,31,28,29,30,6,2,56,105]', '[36]', '', '', 1, '', 0, 22, 1, '[14810,14811,14826]', '[24,436,740]', '[]', 1, 1, '[18317]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1759, 'explosive_concoction_alt_x', 'Explosive Concoction of Destruction', 'Throws a bottle that explodes to deal unarmed attack damage in an area. Can consume charges from your Ruby, Sapphire, and Topaz flasks to add further damage. Requires an empty main hand, and no off-hand weapon.', 1128, 'Art/2DArt/SkillIcons/ExplosiveFlaskIcon.dds', '[1,2]', '[0,40,7,31,28,29,30,6,2,56,105]', '[36]', '', '', 1, '', 0, 22, 1, '[14810,14811,14826]', '[24,436,740]', '[]', 1, 1, '[18317]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1758, ''),
