(1761, 'eye_of_winter', 'Eye of Winter', 'Fires a single eye projectile which constantly releases shard projectiles in a spiral. The shards will damage enemies they impact, dealing cold damage. The eye cannot damage enemies. When the eye dissipates or collides with terrain, it releases a faster spiral of extra shards.', 1129, 'Art/2DArt/SkillIcons/FrozenSphere.dds', '[1,2]', '[1,6,2,58,6,59,29,14,15,13,21,69,31]', '[]', '', '', 1, '', 0, 22, 1, '[14814,14815,18202,18204]', '[24,177,6120,18122]', '[]', 1, 1, '[14796,14822]', 8, 3, 0, 'Metadata/Monsters/Totems/EyeofWinterTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1762, 'eye_of_winter_alt_x', 'Eye of Winter of Finality', 'Fires a single eye projectile which cannot damage enemies. When the eye dissipates or collides with terrain, it releases a fast spiral of shards. The shards will deal cold damage to enemies they impact.', 1129, 'Art/2DArt/SkillIcons/FrozenSphere.dds', '[1,2]', '[1,6,2,58,6,59,29,14,15,13,21,69,31]', '[]', '', '', 1, '', 0, 22, 1, '[14814,14815,18202,18204]', '[24,177,6120,18122]', '[]', 1, 1, '[14796,14822]', 8, 3, 0, 'Metadata/Monsters/Totems/EyeofWinterTotem.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1761, ''),
(1763, 'eye_of_winter_alt_y', 'Eye of Winter of Transience', 'Fires a single eye projectile which releases a number shard projectiles in a spiral before dissipating. The shards will damage enemies they impact, dealing cold damage. The eye cannot damage enemies.', 1129, 'Art/2DArt/SkillIcons/FrozenSphere.dds', '[1,2]', '[1,6,2,58,6,59,29,14,15,13,21,69,31]', '[]', '', '', 1, '', 0, 22, 1, '[14814,14815,18202,18204]', '[24,177,6120,18122]', '[]', 1, 1, '[14796,14822]', 8, 3, 0, 'Metadata/Monsters/Totems/EyeofWinterTotemAltY.ais', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1761, ''),
