(1767, 'poisonous_concoction', 'Poisonous Concoction', 'Throws a bottle that explodes to deal unarmed attack damage in an area and has a chance to poison. Can consume charges from a Life flask to add further damage. Requires an empty main hand, and no off-hand weapon.', 1133, 'Art/2DArt/SkillIcons/PoisonousConcoction.dds', '[1,2]', '[0,40,7,31,41,6,2,56,105]', '[36]', '', '', 1, '', 0, 22, 1, '[15596,15597,15598]', '[24,436,740]', '[]', 1, 1, '[18317]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1768, 'poisonous_concoction_alt_x', 'Poisonous Concoction of Bouncing', 'Throws a single bottle that releases a burst when it hits the ground, dealing unarmed attack damage in an area with a chance to poison. The skill chains, bouncing randomly to deal damage multiple times. Can consume charges from a Life flask to add further damage. Requires an empty main hand, and no off-hand weapon.', 1133, 'Art/2DArt/SkillIcons/PoisonousConcoction.dds', '[1,2]', '[0,40,7,31,41,6,2,56,105,18]', '[36]', '', '', 1, '', 0, 22, 1, '[15596,15597,15598]', '[24,436,740]', '[]', 1, 1, '[18317]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1767, ''),
(1769, 'poisonous_concoction_alt_y', '[DNT] PoisonousConcoctionAltY', 'Throws a bottle that explodes to deal unarmed attack damage in an area and has a chance to poison. Can consume charges from a Life flask to add further damage. Requires an empty main hand, and no off-hand weapon.', 1133, 'Art/2DArt/SkillIcons/PoisonousConcoction.dds', '[1,2]', '[0,40,7,31,41,6,2,56,105]', '[36]', '', '', 1, '', 0, 22, 1, '[15596,15597,15598]', '[24,436,740]', '[]', 1, 1, '[18317]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1767, ''),
(1770, 'call_of_the_wild', '[DNT] Call of the Wild', '[DNT] Call the wild. Maybe it will answer.', 1134, 'Art/2DArt/BuffIcons/Bestiary.dds', '[1]', '[1,5,17,76,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[0,19,20,23,1,6,7,2,18,8,25,32,35,34,47,40,56]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1771, 'temporal_rift', 'Temporal Rift', 'Reserves mana to apply a buff and leave afterimages of your recent past. Cast the spell again to return to the oldest afterimage, teleporting to that location as well as resetting your Life, Mana and Energy Shield to the values they had then.', 1135, 'Art/2DArt/SkillIcons/Chronomancer1.dds', '[4]', '[1,4,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[15120,15601]', '[14217,3396]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
