(1773, 'tornado', 'Tornado', 'Create a Tornado that hinders and repeatedly damages enemies around it. It will move forward for a duration, during which your projectiles can collide with it to deal damage as though it was an enemy. Then it will chase down enemies for a secondary duration, and reflect a portion of the damage it took from your projectiles to them in addition to its own damage.', 1137, 'Art/2DArt/SkillIcons/Tornado.dds', '[1,2]', '[1,8,13,14,15,31,6,27,7,99,71]', '[]', '', '', 1, '', 0, 22, 1, '[15599,15600]', '[24,436]', '[]', 1, 1, '[15180]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1774, 'tornado_alt_x', '[DNT] TornadoAltX', 'Create a Tornado that hinders and repeatedly damages enemies around it. It will move forward for a duration, during which your projectiles can collide with it to deal damage as though it was an enemy. Then it will chase down enemies for a secondary duration, and reflect a portion of the damage it took from your projectiles to them in addition to its own damage.', 1137, 'Art/2DArt/SkillIcons/Tornado.dds', '[1,2]', '[1,8,13,14,15,31,6,27,7,99,71]', '[]', '', '', 1, '', 0, 22, 1, '[15599,15600]', '[24,436]', '[]', 1, 1, '[15180]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1773, ''),
(1775, 'tornado_alt_y', 'Tornado of Elemental Turbulence', 'Create a Tornado of a random element that hinders and repeatedly damages enemies around it, converting physical damage to its element. The Tornado will chase down enemies for a duration.', 1137, 'Art/2DArt/SkillIcons/Tornado.dds', '[1,2]', '[1,8,13,14,15,31,6,27,7,99,71,28,29,30,101,21,69]', '[]', '', '', 1, '', 0, 22, 1, '[15599,15600]', '[24,436]', '[]', 1, 1, '[15180]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1773, ''),
(1776, 'tornado_triggered', 'Tornado', 'Create a Tornado that hinders and repeatedly damages enemies around it. It will move forward for a duration, during which your projectiles can collide with it to deal damage as though it was an enemy. Then it will chase down enemies for a secondary duration, and reflect a portion of the damage it took from your projectiles to them in addition to its own damage.', 1137, 'Art/2DArt/SkillIcons/Tornado.dds', '[1,2]', '[1,8,13,14,15,31,6,27,7,99,71,36,49,89]', '[]', '', '', 1, '', 0, 22, 0, '[15599,15600]', '[24,436]', '[]', 1, 0, '[15180]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1777, 'energy_blade', 'Energy Blade', 'Grants a buff which significantly lowers your maximum Energy Shield to transform your equipped swords into swords formed from that energy. Casting the spell again removes the buff. This skill cannot be triggered or used with non-sword weapons.', 1138, 'Art/2DArt/SkillIcons/StormBlade.dds', '[4]', '[1,4,30,89]', '[9,10,15]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[15565,15566]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1778, 'soul_link', 'Soul Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, your Energy Shield will intercept some of the damage they would take. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1139, 'Art/2DArt/SkillIcons/SoulLink.dds', '[3,1]', '[1,4,8,106]', '[]', '', '', 1, '', 0, 22, 1, '[15590]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1779, 'flame_link', 'Flame Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, they deal additional fire damage based on your life. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1140, 'Art/2DArt/SkillIcons/FlameLink.dds', '[3,1]', '[1,4,8,106,28]', '[]', '', '', 1, '', 0, 22, 1, '[15591]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1780, 'vampiric_link', 'Vampiric Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, they get recovery from your life leech instead of you. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1141, 'Art/2DArt/SkillIcons/LeechLink.dds', '[3,1]', '[1,4,8,106]', '[]', '', '', 1, '', 0, 22, 1, '[15595]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1781, 'protective_link', 'Protective Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, they copy your block chance and recover life when they block. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1142, 'Art/2DArt/SkillIcons/BlockLink.dds', '[3,1]', '[1,4,8,106]', '[]', '', '', 1, '', 0, 22, 1, '[15593]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1782, 'intuitive_link', 'Intuitive Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, their hits can trigger your supported spells. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1143, 'Art/2DArt/SkillIcons/TriggerLink.dds', '[3,1]', '[1,4,8,106]', '[]', '', '', 1, '', 0, 22, 1, '[15592]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1783, 'destructive_link', 'Destructive Link', 'Targets an allied player to apply a buff which links you to them for a duration. While linked, they use your main hand critical strike chance. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines.', 1144, 'Art/2DArt/SkillIcons/CriticalLink.dds', '[3,1]', '[1,4,8,106]', '[]', '', '', 1, '', 0, 22, 1, '[15594]', '[217]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
