(1794, 'lightning_conduit', 'Lightning Conduit', 'Lightning strikes all Shocked enemies around a targeted location, then removes Shock from those enemies. Shocks cannot expire on enemies in range while casting this spell. Cannot be supported by Spell Cascade or Unleash.', 1154, 'Art/2DArt/SkillIcons/EnergyRelease.dds', '[1,22]', '[1,6,7,14,13,15,31,21,30,71,109]', '[]', '', '', 1, '', 0, 22, 1, '[16972,16971,16973,18199]', '[24,436,218,18120]', '[]', 1, 1, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1795, 'lightning_conduit_alt_x', 'Lightning Conduit of the Heavens', 'Lightning strikes a number of enemies around a targeted location. Cannot be supported by Spell Cascade.', 1154, 'Art/2DArt/SkillIcons/EnergyRelease.dds', '[1,22]', '[1,6,7,14,13,15,31,21,30,71,69]', '[]', '', '', 1, '', 0, 22, 1, '[16972,16971,16973,18199]', '[24,436,218,18120]', '[]', 1, 1, '[]', 8, 5, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1794, ''),
