(1797, 'approaching_flames', 'Approaching Flames', 'Become touched by the flames of the Cleansing Fire.', 1097, 'Art/2DArt/SkillIcons/InfinitePolarity.dds', '[4]', '[1,4,63,84,85,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1798, 'galvanic_field', 'Galvanic Field', 'Applies a buff boosting chance to shock. When you shock an enemy while you have this buff, creates a spherical field of energy attached to the shocked enemy for a duration, which will damage it and other nearby enemies with beams of lightning. The strength of the field depends on the magnitude of shock affecting the enemy when it is created.', 1155, 'Art/2DArt/SkillIcons/GalvanicField.dds', '[4]', '[1,6,7,4,8,30,18,99,31]', '[]', '', '', 1, '', 0, 22, 1, '[16974,16975,16976,18199]', '[24,218,174,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1799, 'galvanic_field_alt_x', 'Galvanic Field of Intensity', 'Applies a buff boosting chance to shock. When you shock an enemy while you have this buff, creates a spherical field of energy attached to the shocked enemy for a duration, which will damage it and other nearby enemies with beams of lightning.', 1155, 'Art/2DArt/SkillIcons/GalvanicField.dds', '[4]', '[1,6,7,4,8,30,18,99,31]', '[]', '', '', 1, '', 0, 22, 1, '[16974,16975,16976,18199]', '[24,218,174,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1798, ''),
(1800, 'galvanic_field_alt_y', '[DNT] GalvanicFieldAltY', 'Applies a buff boosting chance to shock. When you shock an enemy while you have this buff, creates a spherical field of energy attached to the shocked enemy for a duration, which will damage it and other nearby enemies with beams of lightning. The strength of the field depends on the magnitude of shock affecting the enemy when it is created.', 1155, 'Art/2DArt/SkillIcons/GalvanicField.dds', '[4]', '[1,6,7,4,8,30,18,99,31]', '[]', '', '', 1, '', 0, 22, 1, '[16974,16975,16976,18199]', '[24,218,174,18120]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, 1798, ''),
(1801, 'alchemists_mark', 'Alchemist''s Mark', 'Curses a single enemy, granting flask charges when you hit them and creating Burning Ground under them if your hit Ignites them, and Caustic Ground if it Poisons them. Damage modifiers do not apply to these ground effects. You can only have one Mark at a time.', 1156, 'Art/2DArt/SkillIcons/AlchemistsMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97,7,8,71,28,41]', '[]', '', '', 1, '', 0, 22, 1, '[16970]', '[1393]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1802, 'mtx_direct_line_of_ants', 'Direct Ants', 'Directs your ants to move to the target location.', 1157, 'Art/2DArt/SkillIcons/LineOfAntsSkillIcon.dds', '[1,20]', '[110,1,47]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1803, 'mtx_polymorph_player', 'Polymorph', 'Polymorphs a party member in town, or a player in your hideout, into an animal.', 1158, 'Art/2DArt/SkillIcons/CatAspect.dds', '[3]', '[110,1,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1804, 'mtx_bestiary_stampede_quicksilver', '', '', 1159, '', '[]', '[110,31,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1805, 'vaal_cleave', 'Vaal Cleave', 'The character swings their weapon (or both weapons if dual wielding) in an arc, damaging monsters in an area in front of them. Killing Blows on Rare or Unique enemies grant a buff that improves Cleave for a duration. Killing Blows on Rare Enemies also steal their modifiers for a secondary duration. Only works with Axes and Swords.', 5, 'Art/2DArt/SkillIcons/iconcleave.dds', '[1,2]', '[0,7,19,43,37,8,4,121]', '[9,10,11,15,16]', '', '', 1, '', 0, 22, 1, '[4044,4269,4239,5477,17439,17445,17447,18066]', '[24,70,436,5514,591,17440,17441,18065]', '[]', 1, 1, '[5479]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1806, 'frozen_legion', 'Frozen Legion', 'This spell consumes multiple cooldown uses to summon icy Statues in a ring. Each Statue uses your Frozen Sweep attack once before vanishing. Requires an Axe, Mace, Sceptre, or Staff. This skill cannot be triggered, supported by Spell Echo or Unleash, or used by Totems, Traps, or Mines. ', 1160, 'Art/2DArt/SkillIcons/FrozenLegion.dds', '[1,2]', '[1,89,29]', '[14,12,17,11,16,57,32]', '', '', 1, '', 0, 22, 1, '[17485,17486,18752,18753]', '[3396,10041,18754,18755]', '[]', 1, 1, '[17488]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1807, 'frozen_legion_alt_x', 'Frozen Legion of Rallying', 'This spell consumes multiple cooldown uses to summon icy Statues in a ring. Each Statue uses your Frozen Sweep attack once before vanishing. Requires an Axe, Mace, Sceptre, or Staff. This skill cannot be triggered, supported by Spell Echo or Unleash, or used by Totems, Traps, or Mines. ', 1160, 'Art/2DArt/SkillIcons/FrozenLegion.dds', '[1,2]', '[1,89,29]', '[14,12,17,11,16,57,32]', '', '', 1, '', 0, 22, 1, '[17485,17486,18752,18753]', '[3396,10041,18754,18755]', '[]', 1, 1, '[17488]', 8, NULL, 0, '', '[]', 0, 0, 1, 1806, ''),
(1808, 'frozen_legion_alt_y', '[DNT] FrozenLegionAltY', 'This spell consumes multiple cooldown uses to summon icy Statues in a ring. Each Statue uses your Frozen Sweep attack once before vanishing. Requires an Axe, Mace, Sceptre, or Staff. This skill cannot be triggered, supported by Spell Echo or Unleash, or used by Totems, Traps, or Mines. ', 1160, 'Art/2DArt/SkillIcons/FrozenLegion.dds', '[1,2]', '[1,89,29]', '[14,12,17,11,16,57,32]', '', '', 1, '', 0, 22, 1, '[17485,17486,18752,18753]', '[3396,10041,18754,18755]', '[]', 1, 1, '[17488]', 8, NULL, 0, '', '[]', 0, 0, 1, 1806, ''),
(1809, 'frozen_sweep', 'Frozen Sweep', 'This attack is used by your Statues to deal damage in an area around them while stepping forward. This skill cannot repeat and can only be used by Statues from Frozen Legion.', 1161, 'Art/2DArt/SkillIcons/FrozenSweep.dds', '[1]', '[0,19,7,29,93,94,111]', '[14,12,17,11,16,57,32]', '', '', 1, '', 0, 22, 1, '[17484,18364]', '[24,636]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1810, 'triggered_ghost_cannons', 'Ghostly Artillery', 'Manifest a row of Ghostly Cannons, each of which then fires after a short delay dealing the damage of the weapon that triggered it. For each additional projectile this skill would fire, create an additional Ghostly Cannon instead.', 1349, 'Art/2DArt/SkillIcons/CaptainCutlassTriggeredSkill.dds', '[1,2]', '[0,40,2,31,36,28,81,7,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1811, 'volcanic_fissure', 'Volcanic Fissure', 'Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts, releasing a burst of molten projectiles. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 1162, 'Art/2DArt/SkillIcons/VolcanicFissure.dds', '[1,2,10]', '[0,2,7,19,91,28,23,40,81,14]', '[12,17,32,57,14,11,16,36]', '', '', 1, '', 0, 22, 1, '[17482,17483]', '[24,175]', '[]', 1, 1, '[17487]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1812, 'volcanic_fissure_alt_x', 'Volcanic Fissure of Snaking', 'Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts dealing damage in an area. After erupting, the fissure continues moving towards enemies to cause further eruptions. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 1162, 'Art/2DArt/SkillIcons/VolcanicFissure.dds', '[1,2,10]', '[0,7,19,91,28,23,14]', '[12,17,32,57,14,11,16,36]', '', '', 1, '', 0, 22, 1, '[17482,17483]', '[24,175]', '[]', 1, 1, '[17487]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1811, ''),
(1813, 'volcanic_fissure_alt_y', '[DNT] VolcanicFissureAltY', 'Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts, releasing a burst of molten projectiles. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 1162, 'Art/2DArt/SkillIcons/VolcanicFissure.dds', '[1,2,10]', '[0,2,7,19,91,28,23,40,81,14]', '[12,17,32,57,14,11,16,36]', '', '', 1, '', 0, 22, 1, '[17482,17483]', '[24,175]', '[]', 1, 1, '[17487]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, 1811, ''),
(1814, 'vaal_volcanic_fissure', 'Vaal Volcanic Fissure', 'Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts, releasing a burst of molten projectiles. After erupting, the fissure continues moving towards enemies to cause further eruptions. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 1162, 'Art/2DArt/SkillIcons/VolcanicFissure.dds', '[1,2,10]', '[0,2,7,19,91,28,40,81,14,37,121]', '[12,17,32,57,14,11,16,36]', '', '', 1, '', 0, 22, 1, '[17482,17483,18537]', '[24,175,8142]', '[]', 1, 1, '[17487]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1815, 'crucible_channel', '[DNT] Crucible Channel', '[DNT] Hold up your weapon and see what happens', 1163, 'Art/2DArt/SkillIcons/ChargedAttack.dds', '[4]', '[47]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1816, 'summon_triggerbots', 'Summon Triggerbots', 'Summon two Triggerbots which follow you around and run towards enemies.', 1164, 'Art/2DArt/SkillIcons/SaboteurTriggerbots.dds', '[4]', '[1,4,5,76,116,31,36,49]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1817, 'summon_abyssal_constructs', 'Summon Bone Feeders', 'Summon two Bone Feeders which follow you around. Bone Feeders consume corpses they walk over, creating a temporary Aura after consuming 10 corpses. One Bone Feeder creates a Curse Aura of either Temporal Chains, Enfeeble or Punishment that ignores Curse Limits. The other Bone Feeder creates an Aura that causes Enemy Damage with Hits to be Unlucky.', 1339, 'Art/2DArt/SkillIcons/AbyssRevampAbyssalFiendsSmall.dds', '[4]', '[1,4,5,76,116,31,36,49]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1818, 'mtx_coin_flip', 'Flip a coin', 'Throw a coin into the air, letting fate decide the outcome.', 1165, 'Art/2DArt/SkillIcons/CoinFlipMicroSkill.dds', '[1]', '[110,1,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1819, 'blood_sand_triggered', 'Stance Swap', 'Casts a buff that grants different bonuses to attack skills depending on your stance. Using the skill again alternates between Blood Stance and Sand Stance.', 1166, 'Art/2DArt/BuffIcons/SandStance.dds', '[4]', '[1,4,63,11,63,84,85,89,92,36,49,89,31]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1820, 'gravity_sphere_triggered', 'Gravity Sphere', 'Creates a Gravity Sphere which Hinders enemies in an area around it, with the debuff being stronger on enemies closer to the sphere. The Gravity Sphere will consume the corpses of any enemies which die in its area. Can only have one Gravity Sphere at a time.', 1074, 'Art/2DArt/SkillIcons/BlackHole2.dds', '[1,22]', '[1,7,13,15,31,8,71,89,14,99,36,49]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1821, 'bone_corpses', 'Bone Corpses', 'Spawns Bone Archer corpses around the targeted location.', 1167, 'Art/2DArt/SkillIcons/BoneLance.dds', '[1,11,23]', '[1,14,15,13,31,21,69,7,71,36,49,89,132]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[6918]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1822, 'mtx_raccoon_trash', 'Summon Barrel', 'Creates a new home for your pet Raccoon.', 1168, 'Art/2DArt/SkillIcons/RaccoonPetSkillIcon.dds', '[4]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1823, 'prismatic_burst', 'Prismatic Burst', 'Chooses an element at random and deals damage of that type in an area. Having higher strength makes it more likely to choose fire, higher dexterity makes it more likely to choose cold, and higher intelligence makes it more likely to choose lightning.', 1169, 'Art/2DArt/SkillIcons/ElementalBurstSupportSkill.dds', '[1,2]', '[1,7,71,6,28,29,30,101,31,36,49,89,114]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 1, 1, NULL, ''),
(1824, 'windburst', 'Windburst', 'Fires projectiles that move randomly and damage enemies they pierce through. They explode after a duration, dealing area damage.', 1311, 'Art/2DArt/SkillIcons/TornadosSupportSkill.dds', '[1]', '[0,40,2,114,49,36,31,7,56,8]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1825, 'support_triggered_kinetic_instability', 'Kinetic Flux', 'Gathers kinetic energy into an anomaly at the targeted location, which will explode when enemies are near it, dealing your wand''s damage in an area. The anomaly will dissipate after a duration.', 1314, 'Art/2DArt/SkillIcons/KineticInstability.dds', '[1,2]', '[7,36,31,114,49,40,0,8,126,89]', '[8]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1826, 'support_triggered_living_lightning', 'Summon Living Lightning', 'Summons Living Lightning Minions, which target nearby enemies with a number of Melee Chaining Attacks before dissipating. Enemies will not directly engage these Minions, and can pass through them.', 1306, 'Art/2DArt/SkillIcons/LivingLightning.dds', '[1,2]', '[1,5,8,49,76,31,36,89,114,116]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,30,18,89,20,23,19]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 1, 1, NULL, ''),
(1827, 'support_triggered_rings_of_light', 'Rings of Light', 'Coalesce holy energy into a series of unstable rings hovering around a target. When you warcry, all Rings of Light within the warcry area will collapse, in a sequence of progressively larger explosions.', 1329, 'Art/2DArt/SkillIcons/RingsofLightSkill.dds', '[1,2]', '[0,30,8,31,36,49,114,7]', '[12,32,17,14,57]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1828, 'slow_dodge', 'Quickstep', 'Performs a series of quick teleports towards a targeted location, stopping if you would overlap with monsters or terrain. If using the "Attack in Place" option, the direction is reversed. Shares a cooldown with other Blink skills. Cannot be supported.', 1170, 'Art/2DArt/SkillIcons/QuickStep.dds', '[1]', '[1,33,78,79,89,104]', '[]', '', '', 1, '', 0, 22, 1, '[10043,10028]', '[10041,11854]', '[]', 1, 1, '[]', 8, 4, 0, '', '[]', 0, 0, 1, NULL, ''),
(1829, 'summon_sentinel_of_radiance', 'Summon Sentinel of Radiance', 'Summons a Sentinel of Radiance which follows you and attacks enemies in melee, while burning enemies around it and taking a portion of damage from hits for you. You can only have one Sentinel of Radiance.', 1171, 'Art/2DArt/SkillIcons/SummonSentinelofRadiance.dds', '[1,22]', '[1,5,17,76,21,55,31,14,13,15,69,128]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[34,0,19,20]', 1, 1, '[18871]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(1830, 'summon_elemental_relic', 'Summon Elemental Relic', 'Summons a Relic of a random element that stays near you. Depending on the element chosen, the relic minion will have an Anger, Hatred, or Wrath aura. These relics explode when they die, dealing elemental damage to enemies around them. If you already have a relic of the chosen element, its duration will be refreshed instead of summoning a new one.', 1172, 'Art/2DArt/SkillIcons/SummonElementalRelic.dds', '[1,2]', '[1,101,76,5,17,8,89,31,36,49]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[6,7,28,29,30,38]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1831, 'avenging_flame', 'Avenging Flame', 'Launches a fiery projectile high into the air, to drop on a target and deal area damage where it lands.', 1173, 'Art/2DArt/SkillIcons/FlamewoodSupport.dds', '[2]', '[1,6,7,71,28,61,10,31,114,36,49,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 1, 1, NULL, ''),
(1832, 'playtest_attack', 'Playtest Attack', 'Strike your foes down with a powerful blow.', 47, 'Art/2DArt/SkillIcons/iconbasicattack.dds', '[1,2]', '[0,40,57,2,20,23,19,56]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1833, 'playtest_spell', 'Playtest Spell', 'Unleashes a ball of fire towards a target which explodes, damaging nearby foes.', 36, 'Art/2DArt/SkillIcons/iconfireball.dds', '[1,2]', '[2,56,1,6,7,13,14,15,21,31,69,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1834, 'playtest_slam', 'Playtest Slam', 'Slams the ground in front of you, creating a wave that travels forward and damages enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 3, 'Art/2DArt/SkillIcons/icongroundslam.dds', '[1,2]', '[0,7,23,19,91,14]', '[12,32,14,17,11,16,36,57]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1835, 'mtx_hunting_dog_sit', 'Sit!', '', 1174, 'Art/2DArt/SkillIcons/TrainedDoggoSit.dds', '[4]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1836, 'mtx_hunting_dog_roll_over', 'Roll Over!', '', 1174, 'Art/2DArt/SkillIcons/TrainedDoggoRollOver.dds', '[4]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1837, 'mtx_hunting_dog_play_dead', 'Play Dead!', '', 1174, 'Art/2DArt/SkillIcons/TrainedDoggoPlayDead.dds', '[4]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1838, 'mtx_hunting_dog_pet', 'Who''s a Good Doggy?', '', 1174, 'Art/2DArt/SkillIcons/TrainedDoggoPet.dds', '[4]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1839, 'summon_spirit_of_kaom', 'Summon Spirit of Kaom', 'Summons an immortal chieftain minion of the Ngamahu tribe to fight alongside you for a duration. This minion grants you a buff which allows totems to take some damage from hits for you. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/NgamahuTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1840, 'summon_spirit_of_utula', 'Summon Spirit of Utula', 'Summons an immortal chieftain minion of the Kitava tribe to fight alongside you for a duration. This minion grants you a buff which makes a percentage of your leech recover instantly. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/KitavaTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1841, 'summon_spirit_of_akoya', 'Summon Spirit of Akoya', 'Summons an immortal chieftain minion of the Tukohama tribe to fight alongside you for a duration. This minion grants you a buff which regenerates rage. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/TukohamaTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1842, 'summon_spirit_of_kahuturoa', 'Summon Spirit of Kahuturoa', 'Summons an immortal chieftain minion of the Rongokurai tribe to fight alongside you for a duration. This minion grants you a buff which lets a percentage of your armour protect against all damage types. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/RongokuraiTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1843, 'summon_spirit_of_rakiata', 'Summon Spirit of Rakiata', 'Summons an immortal chieftain minion of the Tasalio tribe to fight alongside you for a duration. This minion grants you a buff which prevents your action speed being lowered. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/TasalioTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1844, 'summon_spirit_of_ikiaho', 'Summon Spirit of Ikiaho', 'Summons an immortal chieftain minion of the Arohongui tribe to fight alongside you for a duration. This minion grants you a buff which makes travel skills recover cooldowns faster. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/ArohonguiTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1845, 'summon_spirit_of_ahuana', 'Summon Spirit of Ahuana', 'Summons an immortal chieftain minion of the Ramako tribe to fight alongside you for a duration. This minion grants you a buff which prevents additional damage from suppressed spells. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/RamakoTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1846, 'summon_spirit_of_tawhanuku', 'Summon Spirit of Tawhanuku', 'Summons an immortal chieftain minion of the Hinekora tribe to fight alongside you for a duration. This minion grants you a buff which regenerates mana. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/HinekoraTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1847, 'summon_spirit_of_maata', 'Summon Spirit of Maata', 'Summons an immortal chieftain minion of the Tawhoa tribe to fight alongside you for a duration. This minion grants you a buff which refills flasks. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/TawhoaTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1848, 'summon_spirit_of_kiloava', 'Summon Spirit of Kiloava', 'Summons an immortal chieftain minion of the Valako tribe to fight alongside you for a duration. This minion grants you a buff which recovers life, mana and energy shield when you block. Shares a Cooldown with other Spirit Chieftain Skills.', 1175, 'Art/2DArt/SkillIcons/ValakoTribeSkill.dds', '[4]', '[1,5,76,17,89,8,31,49,36]', '[]', '', '', 1, '', 0, 22, 0, '[19068]', '[9521]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1849, 'spray_paint_celestial', 'Spray Paint Celestial', 'Paint the Town!', 1176, 'Art/2DArt/SkillIcons/PaintRingCelestial.dds', '[1]', '[110,1,47]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1850, 'spray_paint_magmatic', 'Spray Paint Magmatic', 'Paint the Town!', 1176, 'Art/2DArt/SkillIcons/PaintRingMagmatic.dds', '[1]', '[110,1,47]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1851, 'spray_paint_blood', 'Spray Paint Blood', 'Paint the Town!', 1176, 'Art/2DArt/SkillIcons/PaintRingBlood.dds', '[1]', '[110,1,47]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1852, 'summon_dark_effigy', 'Summon Dark Effigy', 'Creates a Dark Effigy tethered to you. It''s level matches your own. You and the Effigy take damage for each other. The Effigy is destroyed if you get too far away from it.', 1256, 'Art/2DArt/SkillIcons/passives/VoodooShamanVoodooDollSkill.dds', '[4]', '[1,89,5,76]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1853, 'mtx_mimic_transform', 'Transform into Mimic', 'Transforms you into a mimic of a stash chest while in a town or hideout', 1257, 'Art/2DArt/SkillIcons/MimicSkill.dds', '[1]', '[110,1,63,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1854, 'barkskin', 'Barkskin', 'Adopt the power of the forest, gradually covering your body in bark. Getting hit by enemy attacks causes bark to be removed. You take reduced damage from physical attack hits the more bark builds up, but higher chance to evade when less covered in bark.', 1258, 'Art/2DArt/SkillIcons/Barkskin.dds', '[4]', '[1,4,11,63,89,84,85,108]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1855, 'penance_mark', 'Penance Mark', 'Curses a single enemy, causing them to spawn multiple phantasms when hit. The phantasms will be allies of the marked enemy with the same monster level. They cast a projectile spell which deals physical damage, and are immune to curses and knockback. You can only have one Mark at a time.', 1259, 'Art/2DArt/SkillIcons/PenanceMark.dds', '[1,2,22]', '[1,13,14,15,21,31,68,69,84,85,97,8]', '[]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1856, 'minion_sacrifice', 'Affliction', 'Permanently Afflicts any of your damageable minions in a targeted area, causing them to take physical damage over time, at an accelerating rate. Each such minion causes you to regenerate life at a rate based on the current damage of it''s Affliction debuff. Afflicted Minions explode if their life is lowered to a fifth of maximum.', 1260, 'Art/2DArt/SkillIcons/MinionSacrifice.dds', '[1]', '[1,4,7,13,14,15,21,31,55,69,71,84,85,5]', '[]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1857, 'pacify', 'Pacify', 'Curses all targets in an area, having no effect at first, but causing them to deal no damage once 60% of the curse''s duration has expired.', 1261, 'Art/2DArt/SkillIcons/VoodooShaman.dds', '[1,2,22]', '[1,7,8,13,14,15,21,31,55,68,69,71,84,85,96]', '[]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1858, 'ravenous', 'Ravenous', 'Consumes a targeted corpse, granting you a buff that gives you bonuses against enemies of the same monster category as the corpse.', 1262, 'Art/2DArt/SkillIcons/RavenousSkill.dds', '[6,20]', '[1,4,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1859, 'instant_spell', '', '', 1264, '', '[2]', '[1,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1860, 'automation', 'Automation', 'While this skill is active, supported spells will be repeatedly triggered.', 1265, 'Art/2DArt/SkillIcons/AutomationSkill.dds', '[4]', '[1,63,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1861, 'call_to_arms', 'Autoexertion', 'Reserves mana based on the supported warcries to cause those warcries to be repeatedly triggered.', 1266, 'Art/2DArt/SkillIcons/CalltoArmsSkill.dds', '[4]', '[1,63,11,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1862, 'summon_sacred_wisp', 'Summon Sacred Wisps', 'This skill is triggered by supported skills to summon Sacred Wisps which use the triggering skill when you do.', 1267, 'Art/2DArt/SkillIcons/iconbasicattack.dds', '[1]', '[114,31,36,49,8,1]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[20455]', 8, NULL, 0, '', '[]', 0, 1, 1, NULL, ''),
(1863, 'triggered_detonate_mines', 'Detonate Mines', 'Detonates a Mine, starting a Detonation Sequence which will detonate other Mines around it.', 134, 'Art/2DArt/SkillIcons/detonatemines.dds', '[1,22]', '[1,13,14,31,63,89]', '[]', '', '', 1, 'DetonateMines', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1864, 'retaliation_swords', '[DNT] Retaliation Swords', '[DNT]', 334, 'Art/2DArt/SkillIcons/VigilantStrike.dds', '[1,2,24]', '[0,19,7,6,89,120]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1865, 'glacial_shield_swipe', 'Glacial Shield Swipe', 'Retaliate against a blocked hit with a sweep of your Shield, unleashing a wave of ice in a cone in front of you.', 1273, 'Art/2DArt/SkillIcons/IceWavesSkill.dds', '[1,2,24]', '[0,19,7,6,29,27,89,120,9]', '[26]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1866, 'crushing_fist', 'Crushing Fist', 'Retaliate against a blocked hit by calling forth a huge armoured fist to slam into the ground in front of you as you do the same, dealing weapon damage in an area.', 1272, 'Art/2DArt/SkillIcons/CrushingFistSkill.dds', '[1,2,24]', '[0,19,91,7,6,89,120]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1867, 'divine_retribution', 'Divine Retribution', 'Retaliate against a blocked hit with a surge of divine power, causing multiple waves of lightning bursts to expand outward from a targeted location. This skill cannot be Triggered or used by Totems, Traps, or Mines.', 1275, 'Art/2DArt/SkillIcons/RetaliationHolySpell.dds', '[11,18,24]', '[1,7,6,30,71,27,89,120,55]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[21091,21092]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1868, 'vengeful_cry', 'Vengeful Cry', 'Retaliate against a savage hit with a warcry, taunting all nearby enemies to attack the user. The user and nearby allies gain a buff which grants rage and prevents rage from being lost. Minions cannot gain rage.', 1274, 'Art/2DArt/SkillIcons/RageWarcrySkill.dds', '[4]', '[4,7,8,62,89,120]', '[]', '', '', 1, '', 0, 22, 1, '[9796,5623]', '[9795,4602]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[39,16,10,11,17]', 0, 0, 1, NULL, ''),
(1869, 'swordstorm', 'Swordstorm', 'Retaliate against a blocked hit with a hail of blades that rains down in front of you, repeatedly dealing the damage of both your weapons combined. Requires Dual Wielding Melee Weapons.', 1270, 'Art/2DArt/SkillIcons/RetaliationWeaponStorm.dds', '[1,2,24]', '[0,19,7,6,89,3,120]', '[6,7,9,10,11,12,32,56]', '', '', 1, '', 1, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1870, 'eviscerate', 'Eviscerate', 'Retaliate against a blocked hit with an arcing slash that releases two waves of force. Enemies close in front of you can be hit by both waves. Requires a Sword or Axe and a Shield.', 1271, 'Art/2DArt/SkillIcons/1HandShieldCounterattackSkill.dds', '[1,2,24]', '[0,19,7,6,89,120,9,27]', '[9,10,11]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
