(1872, 'ailment_bearer', 'Unbound Avatar', 'Gain Unbound Fury by inflicting Elemental Ailments with Hits on enemies. Once you reach maximum Unbound Fury, consume it to become Unbound, vastly augmenting your Elemental prowess.', 1269, 'Art/2DArt/SkillIcons/WardenAilmentBearer.dds', '[4]', '[1,4,7,63,84,85,89,28,29,30]', '[]', '', '', 1, '', 0, 22, 1, '[20663]', '[9521]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1873, 'mtx_player_die_beam', 'Fury of the Awakener', 'Die?', 1276, 'Art/2DArt/SkillIcons/SirusDieRing.dds', '[1]', '[110,1,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
