(1877, 'triggered_starfall', 'Starfall', 'Stars fall, raining destruction down over an area. Falling stars deal Attack Damage.' || char(13) || '
Cannot be Supported by Trigger Support Gems.', 99, 'Art/2DArt/SkillIcons/starfellskill.dds', '[1,2]', '[0,40,7,10,61,31,88,36,89,49,122]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 1, 0, 1, NULL, ''),
(1878, 'summon_void_spawn', 'Summon Void Spawn', 'Summon a Void Spawn minion, which casts a lightning projectile spell with a chance to shock enemies.', 1280, 'Art/2DArt/BuffIcons/DeepcallerBuff.dds', '[1,22]', '[1,5,21,31,69,76]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,40,2,56]', 1, 0, '[]', 8, 2, 0, '', '[]', 0, 0, 1, NULL, ''),
(1879, 'summon_shaper_apparition', 'Summon Shaper Memory', 'Consume Remembrance to summon a memory of the Shaper, which will use a skill once before fading away.', 1281, 'Art/2DArt/SkillIcons/SummonShaperApparition.dds', '[1,2]', '[1]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1880, 'zana_influence_memory_of_disbelief', 'Memory of Disbelief', 'Consumes Petals to cause affected nearby monsters to not be able to drop items that can have rarity. The number of Petals consumed is proportional to the Power of affected monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterNoDrops.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1881, 'zana_influence_memory_of_panic', 'Memory of Panic', 'Consumes Petals to cause affected monsters to revive on death, dropping loot and granting experience again. The number of Petals consumed is proportional to the Power of affected monsters. Does not affect Unique monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterRevive.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1882, 'zana_influence_memory_of_impatience', 'Memory of Impatience', 'Consumes Petals to extract Souls from nearby monsters. The number of Petals consumed is proportional to the Power of nearby monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterSouls.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1883, 'zana_influence_memory_of_familiarity', 'Memory of Familiarity', 'Consumes Petals to cause affected nearby monsters to have either 200% more item quantity or 90% less item quantity, and have all non-unique dropped items be of the same type. The number of Petals consumed is proportional to the Power of affected monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterSameItems.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1884, 'zana_influence_memory_of_impulsiveness', 'Memory of Impulsiveness', 'Consumes Petals to cause affected nearby monsters to have 200% increased Item Rarity and convert non-unique equipment items to Gold. The number of Petals consumed is proportional to the Power of affected monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterIncreasedItemRarity.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1885, 'zana_influence_memory_of_desire', 'Memory of Desire', 'Consumes Petals to cause affected nearby monsters to have a chance to gain bonus rewards and 100% increased Toughness. Higher rarity monsters have a higher chance to gain rewards. The number of Petals consumed is proportional to the Power of affected monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterRewards.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1886, 'zana_influence_memory_of_suspicion', 'Memory of Suspicion', 'Consumes Petals to cause affected nearby normal monsters to have a chance to be upgraded to magic or rare rarity.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterUpgradeRarity.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1887, 'zana_influence_memory_of_mocking', 'Memory of Mocking', 'Consumes Petals to gain the modifiers of affected nearby magic and rare monsters for 30 seconds. The number of Petals consumed is proportional to the Power of affected monsters.', 1283, 'Art/2DArt/SkillIcons/MemoryIconMonsterStealMods.dds', '[4]', '[63,89,84,102]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1888, 'unleash_power', '[DNT] Unleash Power', '[DNT] Unleash Power', 1284, 'Art/2DArt/SkillIcons/cyclone.dds', '[1,23]', '[1,7,33,47]', '[]', '', 'http://s3.amazonaws.com/pathofexile/image/skills/dexterity/cyclone.jpg', 0, 'UnleashPower', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, 0, 0, '', '[]', 0, 0, 1, NULL, ''),
(1889, 'call_mercenary', 'Order: To me!', 'Recalls any Mercenary accompanying you to your location. Recalled Mercenaries are healed for a portion of their maximum health.', 1286, 'Art/2DArt/SkillIcons/CallMercSkill.dds', '[4]', '[63,89,84]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
