(1891, 'mtx_command_cruelty_killer_bird', 'Mark as prey', 'Direct your flying companion to eviscerate another player''s pet.', 1288, 'Art/2DArt/SkillIcons/CarrionRaptorSkillIcon.dds', '[26]', '[110,63,84,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1892, 'manual_graft_trigger', 'Command Graft', 'Command your equipped Grafts to use their Skills.', 1289, 'Art/2DArt/SkillIcons/CommandGraftSkill.dds', '[1]', '[]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1893, 'graft_skill_xoph_molten_shell', 'Heart of Flame', 'When you are missing Life, this Graft will apply a Buff that takes some Damage from Hits for you before being depleted. When you are struck while the Buff is active, this skill will fire a nova of fiery projectiles which explode on impact.', 105, 'Art/2DArt/SkillIcons/cyclone.dds', '[3]', '[89,1,7,2,28,4,8,77]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1894, 'graft_skill_xoph_geyser_explosion', 'His Burning Message', 'When commanded, this Graft will cause a cataclysmic eruption that leaves multiple geysers of flame in its wake. These geysers will regularly fire off fiery mortars, firing more in a burst whenever you use a warcry. Triggering warcries will not cause these bursts of mortars.', 1297, 'Art/2DArt/SkillIcons/WardenAilmentBearer.dds', '[1]', '[89,8,7,2,0,28]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1895, 'graft_skill_xoph_flame_pillars', 'Call the Pyre', 'When you Attack with this Graft equipped, it will call forth pillars of ashen flame. These pillars deal Fire damage in an area, and cover Enemies they hit in Ash.', 1296, 'Art/2DArt/SkillIcons/LineOfAntsSkillIcon.dds', '[1]', '[28,7,0,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1896, 'graft_skill_xoph_ailment_buff', 'The Grey Wind Howls', 'While afflicted with an Elemental Ailment while this Graft is equipped, it will remove all Elemental Ailments from you and grant you Physical Damage gained as Extra of the Elemental Damage Types that match the removed Ailments.', 1294, 'Art/2DArt/BuffIcons/DeepcallerBuff.dds', '[3]', '[89,1,4]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1897, 'graft_skill_uulnetol_hand_slam', 'Return to Dust', 'This Graft will periodically target Rare or Unique Enemies in range, calling forth massive hands which slam down dealing high damage and stunning.', 1291, 'Art/2DArt/SkillIcons/SirusDieRing.dds', '[2]', '[89,19,7,27,0]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1898, 'graft_skill_uulnetol_bone_spires', 'Seize the Flesh', 'When you use a Warcry, this Graft will cause spires of bone to erupt from the earth around you. When you use an Exerted Attack, these spires will explode to deal damage in an area around them, inflicting Bleeding and Impaling Enemies.', 1302, 'Art/2DArt/SkillIcons/Bonespire.dds', '[1]', '[89,0,7,27]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1899, 'graft_skill_uulnetol_impale_buff', 'Violent Desire', 'While you have Rage, this Graft will periodically apply a buff to you which grants a chance to inflict an additional Impale and increased effect of Impales you inflict.', 1294, 'Art/2DArt/SkillIcons/TawhoaTribeSkill.dds', '[3]', '[89,8,4,27,1]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1900, 'graft_skill_uulnetol_lowlife_buff', 'Tender Embrace', 'While you are on Low Life, this Graft will periodically apply a buff to you which grants life recovery rate, as well as an Endurance Charge.', 1294, '', '[3]', '[89,8,4,1]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1901, 'graft_skill_esh_lightning_ring', 'Wreathed in Light', 'When commanded, this Graft will call down a ring of lightning bolts, dealing lightning damage and leaving behind Radiant ground.', 1290, 'Art/2DArt/SkillIcons/MimicSkill.dds', '[4]', '[89,1,7,6,30,8,4,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1902, 'graft_skill_esh_lightning_clones', 'Glowing Silhouette', 'While Enemies are nearby, this Graft will periodically bring Lightning-Imbued Clones of you into being. These Clones will move towards the nearest Enemy, detonating and leaving behind shocked ground.', 865, 'Art/2DArt/SkillIcons/BlackHole2.dds', '[2]', '[1,30,8,7,6,71,89]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1903, 'graft_skill_esh_lightning_hands', 'Enervating Grasp', 'When commanded, this Graft will summon forth a field of grasping hands, each of which clutches an enervating orb of Lightning. When an Enemy is near a hand, the orb it clutches will detonate to deal Lightning Damage and Sap on Hit.', 1300, 'Art/2DArt/SkillIcons/starfellskill.dds', '[1]', '[89,7,1,71,6,30]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1904, 'graft_skill_esh_jolt_buff', 'Overcharged Sinews', 'On Critically Striking an Enemy, this Graft will apply a stack of Jolt to you. Jolt grants more maximum Attack Damage at the cost of taking increased Damage, and can stack up to 10 times.', 1294, 'Art/2DArt/SkillIcons/detonatemines.dds', '[3]', '[89,1,30,4]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1905, 'graft_skill_tul_mortars', 'Falling Crystals', 'While equipped, this Graft will periodically fling icy mortars at Enemies in range that are Chilled or Frozen.', 1295, 'Art/2DArt/SkillIcons/RageWarcrySkill.dds', '[2,1]', '[7,2,89,29,6,1,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1906, 'graft_skill_tul_tornado', 'Dance in the White', 'When commanded, this Graft will call forth a devastating tornado which rapidly deals cold damage to Enemies within it. When you Critically Strike with an Attack while the Tornado is active, it will fire off a nova of icicle projectiles.', 1137, 'Art/2DArt/BuffIcons/DeepcallerBuff.dds', '[1]', '[89,1,6,2,8,7,67,34,29,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1907, 'graft_skill_tul_tornado_projectile', 'Icicles', 'Fires a nova of projectiles which deal cold damage.', 1293, 'Art/2DArt/BuffIcons/DeepcallerBuff.dds', '[1]', '[89,1,6,2,8,7,67,34,29,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1908, 'graft_skill_tul_summon', 'The Great Avalanche', 'When you use an Offering skill, this Graft will summon an army of Hiveborn Breach Monsters to do your bidding. These summoned monsters have their Physical Damage converted to Cold, and have a chance to apply Brittle on Hit.', 1305, 'Art/2DArt/SkillIcons/RaccoonPetSkillIcon.dds', '[1]', '[89,5,1]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,29,19]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
