(1912, 'solartwine_nova', 'Blazing Glare', 'When hit, release a nova of fiery vengeance, dealing spell fire damage and blinding enemies struck.', 1322, 'Art/2DArt/SkillIcons/Solartwine.dds', '[4,1]', '[89,7,1,28,36,31,83,49,71,6]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
