(1917, 'call_the_pyre', 'Call the Pyre', 'Calls forth pillars of ashen flame. These pillars deal Fire damage in an area, and cover Enemies they hit in Ash. Requires a Melee Weapon or Unarmed.', 1296, 'Art/2DArt/SkillIcons/Pyre.dds', '[1,2]', '[28,7,0,89,31,36,49,114]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1918, 'seize_the_flesh', 'Seize the Flesh', 'Cause spires of bone to erupt from the earth around you. When you use a slam on them, these spires will explode to deal damage in an area and inflicting bleeding.', 1302, 'Art/2DArt/SkillIcons/Bonespire.dds', '[1,2]', '[89,0,7,27,31,36,49,114,62]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1919, 'enervating_grasp', 'Foulgrasp', 'Summons forth a field of grasping hands, each of which clutches an orb of lightning. When an enemy is near a hand, the orb it clutches will detonate to deal lightning spell damage.', 1300, 'Art/2DArt/SkillIcons/Foulgrasp.dds', '[1,2]', '[89,7,1,71,6,30,31,36,49,114]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 1, 1, NULL, ''),
(1920, 'the_great_avalanche', 'Summon Hiveborn', 'Summons a horde of Hiveborn Breach monsters to do your bidding. These summoned monsters have all their physical damage converted to cold.', 1305, 'Art/2DArt/SkillIcons/Hiveborn.dds', '[1,2]', '[89,5,1,31,36,49,114,76]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[0,29,19,20,23]', 1, 0, '[]', 8, NULL, 0, '', '[]', 0, 1, 1, NULL, ''),
(1921, 'support_void_shockwave', 'Void Shockwave', 'Deals attack damage in an area. A number of enemies hit by the wave will release an additional wave.', 997, 'Art/2DArt/SkillIcons/VoidShockwave.dds', '[2,1]', '[0,7,6,31,36,19,114,89]', '[12,32,17,14,57,16,11]', '', '', 1, '', 0, 22, 0, '[10042]', '[10041]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1922, 'exploding_poison_toad', 'Bursting Toad', 'A toad leaps towards enemies and explodes, dealing spell damage in an area.', 1327, 'Art/2DArt/SkillIcons/Hextoad.dds', '[1]', '[1,7,6,41,36,31,114,71,96]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 1, 1, NULL, ''),
(1923, 'exploding_blood_toad', 'Explosive Toad', 'A toad spawns from the corpse of the slain enemy, leaps towards enemies and explodes, dealing forty percent of the slain enemy''s Life as Chaos Damage. This skill''s damage is not affected by modifiers to spell damage and cannot be reflected.', 1327, 'Art/2DArt/SkillIcons/Hextoad.dds', '[1]', '[7,6,41,36,31]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[4,18,29,10,11,16,17,19,26]', 0, 1, 1, NULL, ''),
(1924, 'triggered_fissure', 'Fissure', 'Creates multiple fissures that deal area damage while travelling outwards. Requires an Axe, Mace, Sceptre, Staff or Unarmed.', 1162, 'Art/2DArt/SkillIcons/ExceptionalSupportFissure.dds', '[1,2,10]', '[0,7,19,91,28,31,36,49,114,89]', '[12,17,32,57,14,11,16,36]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1925, 'triggered_voidstorm', 'Voidstorm', 'Creates a voidstorm that blinds enemies within it. Entering the storm will cause it to explode, dealing attack damage in an area.', 1309, 'Art/2DArt/SkillIcons/Voidstorm.dds', '[1,2]', '[0,7,6,40,89,8,31,36,114,112]', '[13,8]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1926, 'mtx_command_pied_piper_pet', 'Mesmerize', 'Direct your feline companion to mesmerize another player''s pet.', 1332, 'Art/2DArt/SkillIcons/MesmerHypnotiseIcon.dds', '[26]', '[110,63,84,89]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1927, 'mtx_pied_piper_pet_hypnotize', '', '', 1333, '', '[]', '[110,82]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1928, 'barnacle_snap', 'Savage Barnacle', 'Creates a giant barnacle that continually snaps at enemies, dealing off-hand area damage augmented by the defences of the shield. Increases and reductions to attack speed affect the rate at which damage occurs.', 1335, 'Art/2DArt/SkillIcons/Seablister.dds', '[1,2]', '[0,7,6,89,8,31,36]', '[26]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 0, 1, NULL, ''),
(1929, 'ghost_furnace', '[DNT] Ghost Furnace', '[DNT] For 8 seconds after you ignite a target, burn nearby enemies for Fire damage per second equal to a percentage of that Ignite''s damage per second. This damage cannot be modified.', 1073, 'Art/2DArt/BuffIcons/GhostflameLantern.dds', '[4]', '[1,4,28,7,100,71,49,31,36,34,8]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[16,10,11,17]', 0, 0, 1, NULL, ''),
(1930, 'mtx_command_land_shark_pet', 'Set Shark Bait', 'Direct your finned companion to feast upon another player''s pet.', 1336, 'Art/2DArt/SkillIcons/CommandShark.dds', '[26]', '[110,1,89,63]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 0, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1931, 'mtx_land_shark_consume', '', '', 1337, '', '[]', '[110,82]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 0, 0, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1932, 'crystalfall', 'Falling Crystal', 'A giant crystal of abyssal soulstone is called from above, falling to slam down at the targeted location.', 1338, 'Art/2DArt/SkillIcons/ExceptionalSupportCrystalFissure.dds', '[1,2]', '[91,7,36,31,114,89,19,6,0]', '[6,7,9,10,11,12,32,14,15,16,17,36,57,56,37]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[2,18,29,10,11,16,17,19,26,28,14,15,35]', 0, 1, 1, NULL, ''),
(1933, 'brine_torrent', 'Surging Torrent', 'Sets a marker at a location. After a short duration, a pillar of saltwater shoots up from target location, dealing Area Cold damage and creating an area of Brine Ground for 4 seconds.', 213, 'Art/2DArt/SkillIcons/passives/TideCaller.dds', '[1,22,20]', '[1,6,7,8,29,36,31,55,71]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, 3, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1934, 'mana_infused_staff', 'Mana-Infused Staff', 'Infuses your staff with arcane energy, lowering your mana costs and increasing your chance to block. When you block, you release an arcane wave, damaging enemies in a ring-shaped area over a duration.', 1344, 'Art/2DArt/SkillIcons/ManaInfusedStaff.dds', '[4]', '[133,103,22,4,11,63,84,89,1,7,6,8,30,71]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, ''),
(1935, 'pact_of_beidat', 'Pact of Beidat', 'Cast a pact, [EmpoweredSpell|Empowering] non-channelling spells that either fire projectiles, apply an effect to an area around a targeted location or fire chaining beams, causing them to deal more damage and have enhanced coverage. However, using this skill also burdens you with an [PactAffliction|Affliction].', 1341, 'Art/2DArt/SkillIcons/PactOfBeidat.dds', '[4]', '[1,134,4,89,84,85,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1936, 'pact_of_ghorr', 'Pact of Ghorr', 'Cast a pact, [EmpoweredSpell|Empowering] your damage over time spells but burdening you with an [PactAffliction|Affliction]. This skill also grants the [HungerOfGhorr|Hunger of Ghorr] buff for a duration causing Fleshrend to trigger periodically.', 1340, 'Art/2DArt/SkillIcons/PactOfGhorr.dds', '[4]', '[1,134,4,89,84,85,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1937, 'pact_of_ktash', 'Pact of K''Tash', 'Cast a pact, [EmpoweredSpell|Empowering] your damaging Vaal spells but burdening you with an [PactAffliction|Affliction]. Empowered Vaal spells deal more damage, have less soul gain prevention duration and regain consumed souls on use.', 1342, 'Art/2DArt/SkillIcons/PactOfKtash.dds', '[4]', '[1,134,4,89,84,85,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1938, 'pact_of_lycia', 'Pact of Lycia', 'Cast a pact, [EmpoweredSpell|Empowering] the next channelling spells you cast yourself but burdening you with an [PactAffliction|Affliction]. Empowered spells deal more damage and periodically trigger lightning bolts while channelling.', 1343, 'Art/2DArt/SkillIcons/PactOfLycia.dds', '[4]', '[1,134,4,89,84,85,31]', '[]', '', '', 1, '', 0, 22, 1, '[]', '[]', '[]', 1, 1, '[]', 8, NULL, 0, '', '[]', 0, 0, 1, NULL, ''),
(1939, 'triggered_bloodrend', 'Fleshrend', 'Fires a projectile that turns towards enemies in front of it. The projectile does not hit enemies, but as it travels it applies a short physical damage over time debuff to each enemy in an area around it, stacking up to 3 times. The debuff also increases the damage over time they take from all sources.', 965, 'Art/2DArt/SkillIcons/PactOfGhorrProjectiles.dds', '[2,1]', '[1,7,8,2,34,48,27,71,56,36,49,31]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, 3, 0, '', '[16,10,11,17,12,13]', 0, 0, 1, NULL, ''),
(1940, 'triggered_heavens_scourge', 'Heaven''s Scourge', 'A bolt of Beidat''s lightning strikes an area, dealing lightning damage.', 1350, 'Art/2DArt/SkillIcons/PactofLyciaLightningBolt.dds', '[2,1]', '[1,36,30,7,6,49,71,31]', '[]', '', '', 1, '', 0, 22, 0, '[]', '[]', '[]', 1, 0, '[]', 8, NULL, 0, '', '[3,18,29,10,11,16,17,19,26,27,12,13]', 0, 0, 1, NULL, '');
